-- SRS review-card backfill — BATCH 2 of 10 (729 rows).
-- Run each batch on its own in the Supabase SQL Editor; order does not matter and
-- each is idempotent. Together the 10 batches equal backfill_srs_payload.sql.
-- Covers Top 2 preboards/mocks/reviewer + main-app banks + Top 2 banks.
WITH d(qid, patch) AS (
  VALUES
  ('e975f2dd-24','{"options": ["Sattler’s layer", "Fibrous layer", "Chorio-capillaries", "Haller’s layer"], "correct": 3, "explanation": "Haller''s layer is the OUTER choroidal layer of LARGE vessels draining to the vortex veins. Hint: Haller = big outer vessels (H for Huge); Sattler = medium middle vessels."}'),
  ('93c62c73-23','{"options": ["Sattler’s layer", "Fibrous layer", "Chorio-capillaries", "Haller’s layer"], "correct": 0, "explanation": "Sattler''s layer is the MIDDLE choroidal layer of medium vessels/arterioles. Choriocapillaris is the innermost capillary layer. Hint: order from sclera inward, Haller (large) -> Sattler (medium) -> choriocapillaris (capillaries)."}'),
  ('7f0c6980-3o','{"options": ["Active transport", "Selective osmosis", "Diffusion", "Evaporation"], "correct": 2, "explanation": "Diffusion, the avascular lens draws nutrients from the aqueous mainly by diffusion (aided by active transport at the lens epithelium''s pump). If the key stresses the ''active metabolism,'' it may say active transport, VERIFY. Hint: avascular lens/cornea feed by diffusion from the aqueous."}'),
  ('fc72686a-1j','{"options": ["Ectopia lentis", "Hypoparathyroidism", "Hyperglycemia", "Radiation exposure"], "correct": 0, "explanation": "Ectopia lentis (lens dislocation) does NOT cause cataract, it displaces a clear lens. Hypoparathyroidism (hypocalcemia), hyperglycemia (diabetes), and radiation all DO cause cataract. Hint: ectopia lentis moves the lens; it does not cloud it."}'),
  ('4bd5fa99-14','{"options": ["Presence of deep anterior chamber", "Absence of purkinje images", "Iridodenesis", "Shows no fundus reflex"], "correct": 3, "explanation": "''Shows no fundus reflex'' is NOT a sign of aphakia, an aphakic eye has clear media and a good red reflex. True aphakic signs are a deep anterior chamber, iridodonesis (tremulous iris), and absent lens-derived Purkinje images. Hint: aphakia removes the lens, media stay clear, so the fundus reflex is present."}'),
  ('6dea0bdd-10','{"options": ["Eye drops treatment", "Placing contact lens", "Wearing bifocal lens", "Photochromic lens"], "correct": 1, "explanation": "A contact lens best corrects MONOCULAR aphakia (a thick aphakic spectacle would cause severe aniseikonia between the two eyes). Hint: one aphakic eye -> contact lens/IOL, not high-plus glasses, to avoid image-size mismatch."}'),
  ('0544792d-1s','{"options": ["Hyperopia", "Astigmatism", "Myopia", "Ametropia"], "correct": 2, "explanation": "Spherophakia (a small round lens) increases lens power, producing lenticular MYOPIA. Hint: rounder/steeper lens = more plus power = myopic shift."}'),
  ('ce124993-24','{"options": ["Hyperopia", "Astigmatism", "Myopia", "Ametropia"], "correct": 1, "explanation": "A lens coloboma (a notch in the lens edge) distorts the surface and produces astigmatism. Hint: an asymmetric/notched lens bends light unevenly = astigmatism."}'),
  ('385a4c98-4a','{"options": ["Lenticular hyperopia", "Lenticular astigmatism", "Lenticular myopia", "Presbyopia"], "correct": 2, "explanation": "''Second sight'' is lenticular MYOPIA from early nuclear sclerosis, the extra plus power lets a presbyope read without glasses again. Hint: nuclear cataract adds myopia, temporarily rescuing near vision = second sight."}'),
  ('3c537d22-3f','{"options": ["Opthalmoscopy", "Biomicroscopy", "Visual field test", "Perimetry"], "correct": 1, "explanation": "Biomicroscopy (slit lamp) shows the nature and depth/position of an opacity in the cornea or lens by optical sectioning. Hint: slit lamp = optical section = tells you WHERE in the cornea/lens the opacity sits."}'),
  ('ea8fd5b7-5d','{"options": ["Aniridia", "Axenfeld syndrome", "Marfan syndrome", "Peters anomaly"], "correct": 1, "explanation": "Axenfeld syndrome/anomaly, iris strands bridging to a prominent, anteriorly displaced Schwalbe''s line (posterior embryotoxon), with secondary glaucoma risk. Hint: iris strands to posterior embryotoxon = Axenfeld."}'),
  ('d9563447-17','{"options": ["Acquired", "Maternal illness during fetal life", "Histoplasmosis", "Trauma"], "correct": 1, "explanation": "Developmental (congenital) cataract results from maternal illness during fetal life (e.g., rubella), not from later acquired trauma. Hint: ''developmental'' = something during gestation, so maternal illness in pregnancy."}'),
  ('0d4fbe3e-1v','{"options": ["Anterior capsule", "Cortex", "Nucleus", "Posterior capsule"], "correct": 1, "explanation": "Cortex, senile cortical cataract typically begins peripherally in the cortex (wedge/cuneiform spokes). Note nuclear sclerotic cataract instead starts in the nucleus, so if the stem means nuclear, the answer shifts, VERIFY. Hint: cortical senile cataract = peripheral cortex spokes; nuclear = central nucleus."}'),
  ('1888e014-26','{"options": ["Intracaspular", "Extracapsular", "Phacoemulsification", "Laser cataract"], "correct": 1, "explanation": "Extracapsular extraction, the anterior capsule is opened/broken and the nucleus and cortex removed while the posterior capsule stays. Intracapsular removes the lens WITH its whole capsule intact. Hint: EXTRAcapsular leaves the posterior capsule behind (capsule is breached, not removed whole)."}'),
  ('e50936b2-2h','{"options": ["Blood", "Tears", "Vitreous", "Aqueous"], "correct": 3, "explanation": "Aqueous humor is the fluid that flows through and out of the eye and governs intraocular pressure. Hint: IOP is an aqueous balance, production vs outflow."}'),
  ('98c08311-28','{"options": ["Low ratio of calcium into the blood", "Edema", "Scarring due to inflammation", "Clogging of the meshwork"], "correct": 0, "explanation": "A low blood-calcium ratio does NOT raise IOP, so it is the exception. Edema, inflammatory scarring, and a clogged meshwork all impede outflow and raise IOP. Hint: IOP rises from blocked DRAINAGE, not from low calcium."}'),
  ('6e47c97d-21','{"options": ["Macula", "Lens", "Cornea", "Optic disc"], "correct": 3, "explanation": "The optic disc bears the ultimate damage of raised IOP (glaucomatous cupping and optic atrophy). Hint: glaucoma''s end organ is the optic nerve head (cupped disc)."}'),
  ('701f2e79-19','{"options": ["Uveitis", "Keratitis", "Marfan’s Syndrome", "Hyphema"], "correct": 2, "explanation": "Marfan''s syndrome is the connective-tissue disorder associated with congenital anomalies and glaucoma (plus ectopia lentis). Hint: Marfan = congenital connective-tissue disorder with lens and glaucoma issues."}'),
  ('6672f84c-19','{"options": ["Tonometry", "Visual field testing", "Opthalmoscopy", "Light reflex test"], "correct": 3, "explanation": "The light (pupil) reflex test is NOT a glaucoma work-up tool. Glaucoma is assessed by tonometry (IOP), perimetry (fields), and ophthalmoscopy (disc). Hint: glaucoma testing = pressure + field + disc, not the pupil light reflex."}'),
  ('ed9e2c02-29','{"options": ["Scintillating scotoma", "Arcuate scotoma", "Round scotoma", "Blindspot"], "correct": 1, "explanation": "Arcuate (Bjerrum) scotoma is the classic glaucomatous field defect, arcing from the blind spot along nerve-fiber bundles. Hint: nerve-fiber-bundle loss makes an ARC = arcuate scotoma."}'),
  ('2feb4141-1e','{"options": ["Axenfeld syndrome", "Diabetes", "Encephalofacial hemangioma", "Aniridia"], "correct": 1, "explanation": "Diabetes does NOT cause congenital glaucoma. Axenfeld, encephalofacial hemangioma (Sturge-Weber), and aniridia all do. Hint: congenital glaucoma tracks with structural/phakomatosis syndromes, not diabetes."}'),
  ('375072d9-4f','{"options": ["Retinal detachment", "Retinitis pigmentosa", "Central retinal artery occlusion", "Age-related macular degeneration"], "correct": 1, "explanation": "Retinitis pigmentosa, bone-spicule pigment in the mid-periphery, attenuated (thin) vessels, and a waxy pale disc, with nyctalopia and ring scotoma. Hint: bone spicules + waxy disc + night blindness = RP."}'),
  ('f7c93f9a-4u','{"options": ["Retinal detachment", "Glaucoma", "Macular degeneration", "Optic neuritis"], "correct": 0, "explanation": "Retinal detachment, the sensory retina separates from the RPE, giving flashes, floaters, and a rising ''curtain'' over the vision. Hint: flashes + floaters + a curtain = retinal detachment, an emergency."}'),
  ('5fe59257-4e','{"options": ["Peters anomaly", "Aniridia", "Axenfeld syndrome", "Coloboma"], "correct": 1, "explanation": "Aniridia, partial/complete iris absence with foveal hypoplasia, cataract, and glaucoma (WAGR-associated). Hint: no iris + foveal hypoplasia = aniridia."}'),
  ('96116b30-3z','{"options": ["Peters anomaly", "Marfan syndrome", "Sturge-Weber syndrome", "Aniridia"], "correct": 0, "explanation": "Peters anomaly, a central corneal opacity with defects of the posterior stroma, Descemet membrane, and endothelium (often iris/lens adhesions). Hint: central congenital corneal opacity with posterior defects = Peters."}'),
  ('02b5dfc3-4i','{"options": ["Hyperopia", "Astigmatism", "Lenticular myopia", "Emmetropia"], "correct": 1, "explanation": "Displacement of the lens (ectopia lentis, weak zonules) commonly causes astigmatism from the tilted/edge-in-pupil lens (and lenticular myopia). Hint: a tilted/subluxated lens refracts unevenly = astigmatism."}'),
  ('ff1cddbd-31','{"options": ["Hyperopia", "Irregular astigmatism", "Presbyopia", "Aphakia"], "correct": 1, "explanation": "Keratoconus produces irregular astigmatism from the cone-shaped, uneven cornea. Hint: an irregular cone cornea = irregular astigmatism (not correctable with simple cylinder)."}'),
  ('06ad16f3-38','{"options": ["Myopia", "Hyperopia", "Astigmatism", "Emmetropia"], "correct": 1, "explanation": "Congenital absence of the lens (aphakia) leaves the eye markedly HYPEROPIC (lost plus power). Hint: no lens = big hyperopia, needs strong plus correction."}'),
  ('4b9c8c78-3h','{"options": ["Hyperopia", "Regular astigmatism", "Irregular astigmatism", "Aphakia"], "correct": 2, "explanation": "Keratoconus (thinning + conical protrusion) gives IRREGULAR astigmatism. Hint: same as Q75, the cone cornea is irregular, so irregular astigmatism."}'),
  ('62e705b8-2k','{"options": ["Hyperopia", "Lenticular myopia", "Presbyopia", "Emmetropia"], "correct": 1, "explanation": "Lenticonus (a conical bulge of the lens surface) increases lens curvature, causing lenticular MYOPIA. Hint: steeper lens cone = more plus = myopia."}'),
  ('9401f5e6-27','{"options": ["Hyperopia", "Astigmatism", "Myopia", "Anisocoria"], "correct": 2, "explanation": "Advanced nuclear cataract causes a temporary MYOPIC shift (the denser nucleus adds plus power). Hint: nuclear sclerosis = index myopia = ''second sight.''"}'),
  ('20750922-2t','{"options": ["Hyperopia", "Myopia", "Irregular astigmatism", "Aphakia"], "correct": 0, "explanation": "A short axial length gives HYPEROPIA (axial hyperopia), the focus falls behind a too-short eye. Hint: short eye = light focuses behind the retina = hyperopia."}'),
  ('d6def69b-2u','{"options": ["Crystalline lens", "Sclera", "Choroid", "Ciliary body"], "correct": 0, "explanation": "The crystalline lens, high protein, active metabolism, and completely avascular (no blood supply, fed by aqueous). Hint: the transparent lens must be avascular to stay clear, yet it is metabolically busy."}'),
  ('0fc70d5e-14','{"options": ["20 mmHg", "24 mmHg", "50 mmHg", "25 mmHg"], "correct": 0, "explanation": "Normal IOP is about 10 to 21 mmHg, so 20 mmHg is the normal value here. 24, 25, and 50 are elevated. Hint: the upper end of normal IOP is around 21, so 20 fits normal."}'),
  ('df022dd2-6g','{"options": ["Visual acuity", "Microscopic analysis", "Equatorial value", "Denominator"], "correct": 0, "explanation": "Visual acuity is recorded as a fraction (e.g., 20/40): numerator = test distance, denominator = the distance at which a normal eye reads that line. Hint: Snellen fraction = your distance over the normal distance."}'),
  ('0f4fcb2a-2b','{"options": ["Microscope", "Micropsia", "Squinting", "Divergence"], "correct": 1, "explanation": "Micropsia, objects appear SMALLER than they are (as in macular edema separating photoreceptors). Hint: micro = small; micropsia = things look shrunken."}'),
  ('e2b99ced-v','{"options": ["Blepharitis", "Conjunctivitis", "Uveitis", "Scleritis"], "correct": 2, "explanation": "Uveitis = inflammation of the uveal tract (iris, ciliary body, choroid). Hint: uvea = iris + ciliary body + choroid; -itis = its inflammation."}'),
  ('af362179-1v','{"options": ["Cluster headache", "Unilateral headache", "Bilateral headache", "Brow ache"], "correct": 3, "explanation": "Brow ache, the aching over the brow from inflammation of the orbit/lids/eye and from glaucoma. Hint: ocular/orbital and glaucoma pain refers to a brow ache."}'),
  ('313955a7-1t','{"options": ["Nebula", "Glaucoma", "Leukoma", "Macula"], "correct": 1, "explanation": "Glaucoma is NOT a corneal opacity classification. The corneal opacity grades are nebula (faint), macula (moderate), and leukoma (dense). Hint: corneal opacity ladder = nebula < macula < leukoma; glaucoma is unrelated."}'),
  ('f986c975-23','{"options": ["Cluster headache", "Unilateral headache", "Bilateral headache", "Tension headaches"], "correct": 3, "explanation": "Tension (asthenopic) headache is linked to uncorrected refractive errors and muscle imbalance (eyestrain). Hint: eyestrain from refractive/muscle problems = tension/asthenopic headache."}'),
  ('bf5724b4-1k','{"options": ["Phenylephrine", "Oxybuprocane", "Cyclopentolate", "Pilocarpine"], "correct": 3, "explanation": "Pilocarpine (a miotic) increases aqueous OUTFLOW facility by pulling the trabecular meshwork open via ciliary contraction. Phenylephrine/cyclopentolate would worsen angle closure. Hint: pilocarpine pulls the drain open = more outflow = lower IOP."}'),
  ('eab5b631-3g','{"options": ["Optic chiasm", "Optic tract", "Lateral geniculate body", "Optic radiation"], "correct": 3, "explanation": "The optic radiation runs from the lateral geniculate body to the calcarine (visual) cortex on the lips of the calcarine fissure. Hint: LGB -> optic radiation -> calcarine cortex is the last leg of the visual pathway."}'),
  ('b68a3209-1w','{"options": ["Retina", "Inner coat", "Outer coat", "Cornea"], "correct": 0, "explanation": "The retina is the light-sensitive tissue lining the inner eye. (''Inner/outer coat'' are vague; cornea is the front window.) Hint: the photographic ''film'' of the eye = retina."}'),
  ('5a63e92f-41','{"options": ["Hereditary disorder", "Genes", "XX chromosome", "XY chromosome"], "correct": 1, "explanation": "Genes/DNA is the closest option, the stem describes the human genome (about 3 billion base pairs), but no choice actually says ''genome,'' so the item is loosely worded, VERIFY. Hint: 3 billion base pairs = the human genome, made of genes/DNA."}'),
  ('10b94565-4v','{"options": ["Oscilloscope", "Ophthalmoscope", "Slit lamp", "Biomicroscope"], "correct": 0, "explanation": "An oscilloscope displays the alternating bright/dark stripe pattern (a grating) whose spatial frequency (width) and contrast can be varied, used in contrast-sensitivity/visual testing. Hint: a stripe grating on a screen for vision testing = oscilloscope display."}'),
  ('30fb52e9-30','{"options": ["Direct Ophthalmoscopy", "Indirect Ophthalmoscopy", "Keratometry", "Corneal reflex test"], "correct": 0, "explanation": "Direct ophthalmoscopy gives an UPRIGHT, virtual image magnified about 15x (small field). Indirect gives an inverted image at lower magnification but wider field. Hint: DIRECT = upright, ~15x; INDIRECT = inverted, wide, lower power."}'),
  ('23a97dc6-4y','{"options": ["Allergic conjunctivitis", "Phlyctenular conjunctivitis", "Contact conjunctivitis", "Nevi"], "correct": 2, "explanation": "Contact (toxic) conjunctivitis, from drugs, cosmetics, hair products, or eye medications, with itching, chemosis, and thick discharge. Hint: reaction to a substance touching the eye = contact conjunctivitis."}'),
  ('d2863f42-1p','{"options": ["Opacities", "Leukomas", "Macula", "Nebula"], "correct": 1, "explanation": "Leukoma, a dense, totally opaque white corneal scar. Nebula is a faint haze, macula is a moderate opacity, leukoma is the densest. Hint: leukoma = leuko (white) = the fully opaque, whitest scar."}'),
  ('757bb2cc-m','{"options": ["hematology", "splancnology", "cardiology", "angiology"], "correct": 3, "explanation": "ANGIOLOGY = study of blood VESSELS (angio = vessel). Hematology = blood cells; splanchnology = viscera; cardiology = heart. Vessels = angiology."}'),
  ('c60c31bf-o','{"options": ["carpals", "patella", "stapes", "femur"], "correct": 3, "explanation": "The femur (thigh bone) is the longest, heaviest, and strongest bone in the body. Patella is the kneecap (a sesamoid), stapes is the smallest bone (ear), carpals are the small wrist bones. Pair this with Q29: stapes is the smallest, femur the largest."}'),
  ('67cdbb51-25','{"options": ["legs", "pelvis", "thigh", "forearm"], "correct": 2, "explanation": "The femur sits in the thigh, so the largest bone is found in the thigh. ''Legs'' anatomically refers to the lower leg (tibia/fibula) below the knee, not the thigh. Pelvis holds the hip bones, forearm holds radius/ulna."}'),
  ('c42c8aa1-14','{"options": ["nucleus", "cytoplasm", "cell membrane", "lysosome"], "correct": 0, "explanation": "The nucleus holds the chromosomes that replicate and segregate during mitosis, so it is the cell part responsible for division. Cytoplasm and cell membrane are support/boundary structures; lysosomes are the digestive organelles. (The centriole organizes the spindle, but it is not an option here.)"}'),
  ('6b6c5dd4-r','{"options": ["nephrons", "Haversian system", "myofibrils", "neurons"], "correct": 3, "explanation": "The neuron is the structural and functional unit of the nervous system, including the brain. Nephrons are the kidney unit, Haversian systems (osteons) the compact-bone unit, myofibrils the muscle-fiber unit. Match each unit to its system: neuron-brain, nephron-kidney, osteon-bone."}'),
  ('280f78e0-11','{"options": ["nephrons", "Haversian system", "myofibrils", "neurons"], "correct": 1, "explanation": "The Haversian system (osteon) is the structural unit of compact bone, hence of the skeletal system. Neurons = nervous system, myofibrils = muscle, nephrons = kidney. This is the skeletal counterpart to Q5."}'),
  ('5887ea60-1j','{"options": ["pelvic bones", "liver", "diaphragm", "stomach"], "correct": 2, "explanation": "The diaphragm is the muscular partition that separates the thoracic cavity above from the abdomino-pelvic cavity below. The liver and stomach sit just under it but do not divide the cavities; pelvic bones bound the pelvis. Same fact is re-asked in Q33."}'),
  ('693b3cc0-y','{"options": ["thoracic cavity", "pelvic cavity", "mediastinum", "abdominal cavity"], "correct": 2, "explanation": "The HEART lies in the MEDIASTINUM (the central compartment of the thoracic cavity between the lungs). ''Thoracic cavity'' is broader; pelvic/abdominal are elsewhere. Heart = mediastinum."}'),
  ('29d3b607-p','{"options": ["skin", "pancreas", "liver", "stomach"], "correct": 2, "explanation": "The LIVER is the largest GLAND (and largest internal organ) — metabolic, synthetic, detox functions. Skin is the largest organ overall but not a gland. Largest gland = liver."}'),
  ('c916a9bf-11','{"options": ["colon", "duodenum", "stomach", "small intestine"], "correct": 3, "explanation": "The small intestine (about 6 meters) is the longest organ of the digestive tract. The colon is wider but much shorter; the stomach and duodenum are short segments. Longest = small intestine; the duodenum is only its first short part."}'),
  ('85f65dac-s','{"options": ["stomach", "colon", "pancreas", "spleen"], "correct": 0, "explanation": "The STOMACH is the most DILATED (distensible, sac-like) part of the digestive tract. Colon/pancreas/spleen differ. Most dilated GI organ = stomach."}'),
  ('3b2c1497-1h','{"options": ["smooth muscle", "myocardium", "skeletal muscle", "none of the above"], "correct": 2, "explanation": "Skeletal (striated) muscle is under voluntary control of the somatic nervous system. Smooth muscle (viscera) and myocardium (heart) are involuntary, run by the autonomic system. Voluntary = skeletal; involuntary = smooth + cardiac."}'),
  ('be3f593a-15','{"options": ["left", "right"], "correct": 0, "explanation": "The left kidney is the larger and higher one; the right kidney sits lower because the liver pushes it down. Useful pair: LEFT is higher, RIGHT is lower (liver on the right). Connects to abdominal quadrant questions Q47-49."}'),
  ('38c30305-k','{"options": ["left", "right"], "correct": 1, "explanation": "The right lung is larger, with 3 lobes, while the left lung has only 2 lobes and a cardiac notch to make room for the heart. Mnemonic: the heart tilts left, so the LEFT lung is smaller. Right = 3 lobes, left = 2."}'),
  ('3801e663-n','{"options": ["sigmoid colon", "cecum", "ascending colon", "duodenum"], "correct": 1, "explanation": "The cecum is the first part of the large intestine (colon), receiving content from the ileum at the ileocecal valve; the appendix hangs off it. Order: cecum, ascending, transverse, descending, sigmoid. The duodenum belongs to the small intestine, not the colon."}'),
  ('10acc8f3-r','{"options": ["trachea", "vocal cords", "larynx", "bronchi"], "correct": 2, "explanation": "The larynx is the voice box, housing the vocal cords. The trachea is the windpipe below it, the bronchi branch into the lungs, and the vocal cords are inside the larynx but are not the box itself. Larynx = the box; cords = the strings inside."}'),
  ('08db640b-z','{"options": ["pleural cavity", "mediastinal cavity", "pelvic cavity", "cranial cavity"], "correct": 0, "explanation": "The lungs occupy the pleural cavities. The mediastinal cavity holds the heart (Q9), the pelvic cavity the lower viscera, the cranial cavity the brain. Pair Q9 and Q18: heart = mediastinum, lungs = pleural cavities."}'),
  ('e6fb41aa-m','{"options": ["lacrimal gland", "thyroid gland", "pineal gland", "adrenal gland"], "correct": 0, "explanation": "The lacrimal gland is exocrine (secretes tears through ducts), not endocrine. The thyroid, pineal, and adrenal glands are all endocrine (ductless, secrete hormones into blood). Exocrine = duct; endocrine = ductless/hormonal."}'),
  ('3e49eb0b-1n','{"options": ["parathyroid glands", "ovaries", "pancreas", "testes"], "correct": 0, "explanation": "The parathyroid is purely endocrine (PTH only), so it is the exception. The pancreas (enzymes + insulin), ovaries (ova + estrogen), and testes (sperm + testosterone) are all both exocrine and endocrine. Mixed glands have a ''product'' AND a ''hormone''."}'),
  ('50cf821b-1p','{"options": ["liver", "stomach", "brain", "pancreas"], "correct": 2, "explanation": "The brain holds the largest number of cells of the listed organs (tens of billions of neurons plus far more glia). Liver, stomach, and pancreas have fewer. Note the contrast with Q6: at the SYSTEM level blood cells dominate, but among these ORGANS the brain is densest."}'),
  ('c40e2816-q','{"options": ["white blood cells", "red blood cells", "platelets", "plasma"], "correct": 2, "explanation": "Thrombocytes are platelets, the cell fragments that initiate clotting. White cells (leukocytes) fight infection, red cells (erythrocytes) carry oxygen, and plasma is the fluid, not a cell. Thrombo = clot, so thrombocyte = clotting cell."}'),
  ('d3acbc90-l','{"options": ["knee cap", "ulna", "tibia", "calcaneus"], "correct": 0, "explanation": "The patella is the kneecap. The ulna is a forearm bone, the tibia the shin bone (Q39), and the calcaneus the heel bone. Patella = kneecap, a sesamoid bone in the quadriceps tendon."}'),
  ('d3699c68-q','{"options": ["arch of aorta", "vena cava", "pulmonary capillaries", "arterioles"], "correct": 0, "explanation": "The aorta (arch of aorta) is the largest artery. Vena cava is a vein, capillaries and arterioles are tiny. Hint: the aorta is the body''s main trunk line off the heart."}'),
  ('3b9b2c03-o','{"options": ["aorta", "capillary", "vena cava", "venule"], "correct": 2, "explanation": "The vena cava (superior and inferior) is the largest vein, returning blood to the right atrium. The aorta is the largest artery, while capillaries and venules are tiny. Keep the pair straight: aorta out, vena cava in."}'),
  ('6d71265f-r','{"options": ["210", "206", "305", "650"], "correct": 1, "explanation": "The adult human skeleton has 206 bones. Newborns have roughly 270 that fuse with growth. 206 is the high-yield number to memorize."}'),
  ('72db08e8-1g','{"options": ["gall bladder", "urinary bladder", "spleen", "liver"], "correct": 3, "explanation": "The liver produces and secretes bile; the gallbladder only stores and concentrates it. The urinary bladder stores urine, and the spleen filters blood, neither making bile. Produce = liver, store = gallbladder."}'),
  ('d83fbaeb-z','{"options": ["digestive system", "cardiovascular system", "urinary system", "endocrine system"], "correct": 0, "explanation": "The alimentary system is another name for the digestive (gastrointestinal) system, the tube from mouth to anus. Cardiovascular = vessels, urinary = kidneys/bladder, endocrine = hormone glands. Alimentary refers to ''nourishment'', so digestive."}'),
  ('51cb90ce-p','{"options": ["carpals", "patella", "stapes", "femur"], "correct": 2, "explanation": "The stapes (stirrup) in the middle ear is the smallest bone in the body. Femur is the largest (Q2), carpals are small wrist bones, patella the kneecap. Smallest = stapes, largest = femur."}'),
  ('0040a295-q','{"options": ["plantaris tendon", "Achilles tendon", "tendon of stapes", "vertebrae"], "correct": 1, "explanation": "The Achilles (calcaneal) tendon, connecting the calf muscles to the heel, is the largest and strongest tendon. The plantaris tendon is thin, the stapedius tendon is tiny, and vertebrae are bones, not tendons. Achilles = thickest tendon."}'),
  ('256cc40c-z','{"options": ["sartorius", "rectus femoris", "sternocleidomastoid", "latissimus dorsi"], "correct": 3, "explanation": "The latissimus dorsi is the widest (broadest) muscle, fanning across the back. Sartorius is the longest (Q36), not widest; SCM and rectus femoris are narrower. Lats = the broad back muscle."}'),
  ('91ff1f21-1q','{"options": ["diaphragm", "peritoneum", "fascia", "thoracic cage"], "correct": 0, "explanation": "The diaphragm separates the thoracic from the abdomino-pelvic cavity (same as Q8). The peritoneum lines the abdomen, fascia wraps structures, and the thoracic cage is bone, not a partition. Diaphragm = the dome that divides chest from abdomen."}'),
  ('acaebc2e-2e','{"options": ["capillary", "venule", "arteriole", "vena cava"], "correct": 0, "explanation": "Capillaries are the thinnest, smallest vessels, with walls one cell thick where gas and nutrient exchange occurs. Venules and arterioles are slightly larger feeder/drainage vessels; the vena cava is huge. Exchange happens only across capillary walls."}'),
  ('643cb734-10','{"options": ["sartorius", "rectus femoris", "sternocleidomastoid", "tensor tympani"], "correct": 0, "explanation": "The sartorius, running diagonally across the thigh, is the longest muscle in the body. Rectus femoris is shorter and straight, SCM is in the neck, tensor tympani is a tiny ear muscle. Sartorius = longest; latissimus = widest."}'),
  ('940aa2c6-1n','{"options": ["platelets", "monocytes", "erythrocytes", "lymphocytes"], "correct": 3, "explanation": "Lymphocytes finish maturing in lymphoid tissue (T cells in the thymus), so they are not fully ''formed'' in red marrow, making them the exception. Platelets, monocytes, and erythrocytes are all produced and released from red bone marrow. Marrow makes the rest; lymphocytes mature elsewhere."}'),
  ('878c1f42-12','{"options": ["platelets", "monocytes", "erythrocytes", "lymphocytes"], "correct": 1, "explanation": "Monocytes are the largest cellular elements of blood (largest leukocytes, up to ~20 microns). Platelets are tiny fragments, erythrocytes are ~7 microns, lymphocytes are smaller than monocytes. Largest blood cell = monocyte."}'),
  ('6cc8d106-r','{"options": ["carpals", "fibula", "tibia", "femur"], "correct": 2, "explanation": "The tibia is the shin bone, the large weight-bearing bone of the lower leg. The fibula is the slender calf bone (Q40), the femur the thigh, and carpals are wrist bones. Tibia = shin (front), fibula = calf (side)."}'),
  ('d456c9d4-r','{"options": ["carpals", "fibula", "tibia", "femur"], "correct": 1, "explanation": "The fibula is the calf bone, the thin lateral bone of the lower leg. The tibia is the shin (Q39), the femur the thigh, carpals the wrist. Pair them: tibia shin, fibula calf."}'),
  ('06dd79b5-10','{"options": ["B-lymphocytes", "T-lymphocytes", "macrophages", "neutrophiles"], "correct": 0, "explanation": "B-lymphocytes drive humoral (antibody-mediated) immunity by maturing into plasma cells that secrete antibodies. T-lymphocytes run cell-mediated immunity; macrophages and neutrophils are phagocytes of innate immunity. B = aBody (antiBody) = humoral."}'),
  ('37b013e7-u','{"options": ["submandibular", "sublingual", "parotid", "all of the above"], "correct": 2, "explanation": "The parotid is the largest salivary gland (in front of the ear, the one mumps swells). It is largest but mostly serous. Submandibular is smaller but secretes the most saliva (Q43); sublingual is the smallest. Largest = parotid; most saliva = submandibular."}'),
  ('b1d1cbc1-1t','{"options": ["submandibular", "sublingual", "parotid", "all of the above"], "correct": 0, "explanation": "The submandibular gland secretes the largest share of saliva (roughly 70%) despite not being the largest gland. The parotid is biggest by size (Q42) but contributes less volume; sublingual contributes least. Biggest gland and biggest output are different glands."}'),
  ('4f6f5c40-g','{"options": ["amylopsin", "ptyalin", "chymotrypsin", "cholecystokinin"], "correct": 1, "explanation": "Ptyalin is salivary amylase, starting starch digestion in the mouth. Amylopsin is pancreatic amylase (Q45), chymotrypsin a pancreatic protease, and cholecystokinin a gut hormone. Ptyalin = spit amylase; amylopsin = pancreas amylase."}'),
  ('e4f8a28f-i','{"options": ["amylopsin", "ptyalin", "chymotrypsin", "cholecystokinin"], "correct": 0, "explanation": "Amylopsin is pancreatic amylase, continuing starch breakdown in the small intestine. Ptyalin is the salivary version (Q44), chymotrypsin a protease, cholecystokinin a hormone. Remember the pair: ptyalin (mouth) vs amylopsin (pancreas)."}'),
  ('9f251940-2t','{"options": ["pepsin", "ptyalin", "chymotrypsin", "cholecystokinin"], "correct": 3, "explanation": "Cholecystokinin (CCK) is released by the duodenum when fats arrive and triggers gallbladder contraction to release bile (and pancreatic enzymes). Pepsin and chymotrypsin are proteases; ptyalin is salivary amylase. CCK literally means ''move the gallbladder'' (chole-cysto-kinin)."}'),
  ('09f0e961-2p','{"options": ["vermiform appendix", "spleen", "liver and biliary tree", "kidneys"], "correct": 1, "explanation": "The spleen sits in the left upper quadrant and is unique to that quadrant. The appendix is right lower (Q49), the liver/biliary tree right upper (Q48), and kidneys are retroperitoneal in both flanks. Spleen = LUQ landmark."}'),
  ('0c509dce-2q','{"options": ["vermiform appendix", "spleen", "liver and biliary tree", "kidneys"], "correct": 2, "explanation": "The liver and biliary tree occupy the right upper quadrant. The spleen is LUQ (Q47), the appendix RLQ (Q49). Liver bulk sits on the right under the diaphragm. RUQ = liver/gallbladder."}'),
  ('9a5a6281-2q','{"options": ["vermiform appendix", "spleen", "liver and biliary tree", "kidneys"], "correct": 0, "explanation": "The vermiform appendix is in the right lower quadrant (McBurney''s point area), the classic site of appendicitis pain. Spleen = LUQ, liver = RUQ, kidneys = bilateral flanks. RLQ pain points to the appendix."}'),
  ('5c96cc40-1k','{"options": ["long posterior ciliary nerve", "central retinal artery", "nerve fibers of ganglion cells", "central retinal vein"], "correct": 0, "explanation": "The long posterior ciliary nerves pierce the sclera around the optic nerve but do NOT pass through the lamina cribrosa. The lamina cribrosa transmits the ganglion-cell axons (optic nerve fibers) plus the central retinal artery and vein. Only the optic nerve fibers and central retinal vessels go through the sieve."}'),
  ('2d62c840-1j','{"options": ["epithelium", "Bowman’s membrane", "endothelium", "Descemet’s membrane"], "correct": 0, "explanation": "The corneal epithelium is the protective barrier layer, providing the surface ''detergence''/cleansing and blocking pathogens and water. Bowman''s and Descemet''s are acellular membranes; the endothelium pumps fluid. Epithelium = the front shield that keeps the cornea clean and dry-surfaced."}'),
  ('e12794cb-1m','{"options": ["stroma", "Bowman’s membrane", "endothelium", "epithelium"], "correct": 3, "explanation": "The corneal epithelium regenerates fully after injury (it heals without a scar). Bowman''s membrane does not regenerate (it scars), and the endothelium and stroma have very limited or no regenerative capacity. Only the epithelium truly replaces itself."}'),
  ('7b11f4ac-1h','{"options": ["lamina fusca", "lamina cribrosa", "lamina vitrea", "lamina suprachoroidea"], "correct": 2, "explanation": "The lamina vitrea (Bruch''s membrane) is the innermost choroidal layer to which the retinal pigment epithelium (RPE) is firmly adherent. Lamina fusca and lamina suprachoroidea are outer choroid layers; the lamina cribrosa is scleral. RPE sits on Bruch''s = lamina vitrea."}'),
  ('fb4da397-x','{"options": ["oculomotor nerve", "facial nerve", "ophthalmic division of trigeminal nerve", "maxillary division of trigeminal nerve"], "correct": 2, "explanation": "The cornea''s sensory supply is the ophthalmic division of the trigeminal nerve (via the long ciliary/nasociliary branches). The oculomotor and facial nerves are motor; the maxillary division serves the lower face, not the cornea. Corneal sensation = V1 (ophthalmic trigeminal)."}'),
  ('9607eb2f-z','{"options": ["pars plicata", "limbus", "lamina cribrosa", "pars plana"], "correct": 2, "explanation": "The lamina cribrosa is considered the most vulnerable part of the eyeball wall: it is the weak, sieve-like scleral region where the optic nerve exits and where raised pressure produces glaucomatous cupping. Pars plana is actually the safe surgical zone; limbus and pars plicata are not the weak point. Weak spot = lamina cribrosa."}'),
  ('b7ff6fe4-23','{"options": ["epithelium", "corneal stroma", "Bowman’s membrane", "Descemet membrane"], "correct": 3, "explanation": "Descemet''s membrane (and the endothelium) have no sensory nerve endings; corneal nerves from the nasociliary branch only reach the epithelium, Bowman''s layer, and anterior stroma. So Descemet''s is the layer without nasociliary innervation. Sensation thins out toward the back of the cornea."}'),
  ('14530a65-1i','{"options": ["2 short PCA and 7 ACA", "2 long PCA and 7 ACA", "7 long PCA and 2 ACA", "7 short PCA and 2 ACA"], "correct": 1, "explanation": "The iris (major arterial circle) is supplied by the 2 long posterior ciliary arteries plus the 7 anterior ciliary arteries. The short PCAs supply the choroid, not the iris circle. Remember 2 long PCA + 7 ACA feed the anterior uvea."}'),
  ('0516fef1-1i','{"options": ["scleral spur", "Schwalbe’s line", "annulus of Zinn", "iris root"], "correct": 0, "explanation": "Brucke''s muscle (the longitudinal/outer fibers of the ciliary muscle) originates from the scleral spur. The annulus of Zinn is the origin of the recti, Schwalbe''s line marks the trabecular edge, and the iris root is the iris attachment. Ciliary muscle anchors to the scleral spur."}'),
  ('eb7ec44e-2n','{"options": ["miosis", "contraction of zonular fibers", "contraction of ciliary muscles", "convergence of the eyeball"], "correct": 1, "explanation": "The accommodation triad (synkinesis) is convergence + miosis + ciliary muscle contraction. The ciliary muscle contracting actually RELAXES (slackens) the zonular fibers, so ''contraction of zonular fibers'' is the exception. Zonules loosen during accommodation; they do not contract."}'),
  ('ac0bce00-38','{"options": ["oculomotor nerve", "facial nerve", "sympathetic nerve", "trigeminal nerve"], "correct": 0, "explanation": "The oculomotor nerve (CN III) drives the near reflex, producing the synkinetic contraction of the ciliary muscle, sphincter pupillae (miosis), and (with the medial recti) convergence. The facial and trigeminal nerves and the sympathetics do not mediate the near triad. Near reflex = CN III."}'),
  ('6727a54f-1v','{"options": ["inferior oblique muscles", "sphincter pupillae", "ciliary muscles", "lateral rectus"], "correct": 3, "explanation": "The lateral rectus is NOT supplied by the oculomotor nerve; it is run by the abducens nerve (CN VI). CN III does supply the inferior oblique, sphincter pupillae, and ciliary muscle. Mnemonic LR6 SO4: lateral rectus = VI, superior oblique = IV, the rest = III."}'),
  ('ed490b5c-1i','{"options": ["collarette", "iris root", "iris crypts", "ora serrata"], "correct": 0, "explanation": "The collarette is the slightly raised ridge that divides the iris into the inner pupillary zone and the outer ciliary zone (and marks the minor arterial circle). The iris root anchors the iris peripherally, crypts are surface pits, and the ora serrata is a retinal landmark. Collarette = the iris dividing line."}'),
  ('44738a4e-55','{"options": ["muscular fascia", "ligament of Lockwood", "muscle cone", "check ligament"], "correct": 1, "explanation": "The suspensory ligament of Lockwood is the hammock-like thickening formed by the fused sheaths of the inferior rectus and inferior oblique with the fascia bulbi, slinging the globe from below. The muscle cone is the EOM space, check ligaments restrain horizontal recti. Lockwood = the floor hammock that holds the eye up."}'),
  ('cef88431-17','{"options": ["medial wall", "roof", "lateral wall", "floor"], "correct": 0, "explanation": "The MEDIAL orbital wall is QUADRILATERAL (rectangular) and the thinnest (lamina papyracea of the ethmoid, Q84). Roof/floor/lateral walls are triangular-ish. Medial wall = quadrilateral & paper-thin."}'),
  ('237298b5-1k','{"options": ["abducens nerve", "optic nerve", "trochlear nerve", "oculomotor nerve"], "correct": 1, "explanation": "The optic nerve passes through the OPTIC CANAL, not the superior orbital fissure, so it is the exception. The oculomotor, trochlear, and abducens nerves (plus V1 branches) all traverse the superior orbital fissure. SOF = III, IV, VI, V1; optic canal = II + ophthalmic artery."}'),
  ('37aa12c3-13','{"options": ["ethmoid", "lacrimal", "sphenoid", "maxilla"], "correct": 0, "explanation": "The LAMINA PAPYRACEA (paper-thin medial orbital wall) belongs to the ETHMOID bone — a common route for orbital cellulitis spread from ethmoid sinusitis. Ethmoid = lamina papyracea (medial wall)."}'),
  ('1b0e7141-o','{"options": ["ethmoid", "frontal", "sphenoid", "maxillary"], "correct": 3, "explanation": "The maxillary sinus (antrum of Highmore) is the largest paranasal sinus, sitting in the cheek below the orbital floor. Ethmoid, frontal, and sphenoid sinuses are smaller. Largest antrum = maxillary."}'),
  ('59022218-1b','{"options": ["mastoid sinuses", "sphenoid sinus", "maxillary antrum", "frontal sinuses"], "correct": 0, "explanation": "The mastoid ''sinuses'' (air cells) are part of the temporal bone, not paranasal sinuses. The true paranasal sinuses are the frontal, ethmoid, sphenoid, and maxillary. Paranasal = frontal/ethmoid/sphenoid/maxillary only (re-asked in Q83)."}'),
  ('d6d1d58c-z','{"options": ["orbital margins", "superior orbital fissure", "optic foramen", "inferior orbital fissure"], "correct": 2, "explanation": "The APEX of the orbit corresponds to the OPTIC FORAMEN/canal (where the optic nerve and ophthalmic artery exit posteriorly). The base = orbital margins (Q86). Orbital apex = optic foramen."}'),
  ('0b969d77-y','{"options": ["sphenoid", "lacrimal", "ethmoid", "maxilla"], "correct": 0, "explanation": "The SPHENOID is the BAT-WING-shaped bone (greater + lesser wings) at the skull base/posterior orbit. Lacrimal/ethmoid/maxilla differ. Bat-wing bone = sphenoid."}'),
  ('2365024c-1i','{"options": ["orbital margins", "superior orbital fissure", "optic foramen", "inferior orbital fissure"], "correct": 1, "explanation": "The superior orbital fissure lies between the greater and lesser wings of the sphenoid, effectively dividing them. The optic foramen sits in the lesser wing, and the inferior orbital fissure is between the greater wing and maxilla. SOF separates the two sphenoid wings."}'),
  ('e4ee0d6d-1s','{"options": ["trochlear nerve", "oculomotor nerve", "trigeminal nerve", "abducens nerve"], "correct": 2, "explanation": "The trigeminal nerve is NOT a pure motor nerve of the orbit; it is mainly sensory (with a small motor root to mastication). The trochlear, oculomotor, and abducens nerves are pure motor to the eye muscles. III, IV, VI = pure motor; V = sensory."}'),
  ('780c287e-t','{"options": ["formed by the union of muscular fascia of superior rectus", "formed by the union of muscular fascia of superior oblique", "formed by the union of muscular fascia of lateral rectus", "formed by the union of muscular fascia of inferior rectus"], "correct": 2, "explanation": "The CHECK LIGAMENTS arise from the muscular fascia of the LATERAL (and medial) rectus, attaching to the orbital walls to LIMIT (check) excessive muscle excursion. The lateral check ligament restrains the lateral rectus. Check ligaments = limit rectus pull (lateral one here)."}'),
  ('656f91d4-25','{"options": ["sphenoid sinus", "maxillary antrum", "frontal sinus", "ethmoid sinus"], "correct": 3, "explanation": "The ETHMOID SINUS has a HONEYCOMB of air cells (spongy network) — the ethmoidal air cells. Sphenoid/maxillary/frontal sinuses are single cavities. Honeycomb air cells = ethmoid sinus."}'),
  ('e5e8aaa0-1a','{"options": ["sphenoid", "frontal", "ethmoid", "lacrimal"], "correct": 0, "explanation": "The sphenoid bone houses the sella turcica that cradles the pituitary (the ''master gland''). Frontal, ethmoid, and lacrimal bones do not. Sphenoid = seat of the pituitary (Q89 sella turcica)."}'),
  ('20fa916c-1r','{"options": ["nasolacrimal duct", "posterior ethmoid sinus", "maxillary sinus", "middle ethmoid sinus"], "correct": 0, "explanation": "The NASOLACRIMAL DUCT opens into the INFERIOR meatus of the nose (beneath the inferior turbinate, valve of Hasner). The maxillary sinus and most sinuses drain to the MIDDLE meatus; posterior ethmoids to the superior meatus. Inferior meatus = NLD outlet."}'),
  ('954ca734-s','{"options": ["Mueller’s muscles", "LPS", "orbicularis oculi", "orbital septum"], "correct": 0, "explanation": "Mueller''s (superior tarsal) muscle is the smooth, involuntary lid muscle that provides a few millimeters of lift and is sympathetically innervated (its loss causes the ptosis of Horner''s). The LPS is voluntary (CN III), orbicularis oculi closes the lid, and the orbital septum is fascia. Involuntary lid lift = Mueller''s."}'),
  ('0335ea38-j','{"options": ["Meuller’s muscles", "LPS", "orbicularis oculi", "orbital septum"], "correct": 2, "explanation": "The orbicularis oculi is the periorbital (around-the-eye) muscle that closes the lids. Mueller''s muscle and the LPS act within the lid to raise it; the orbital septum is connective tissue. Orbicularis = the sphincter ring that shuts the eye."}'),
  ('d3359533-f','{"options": ["orbital septum", "bulbar fascia", "superior orbital fissure", "inferior orbital fissure"], "correct": 1, "explanation": "Tenon''s capsule is the bulbar fascia, the fibrous sheath enclosing the globe from limbus to optic nerve. The orbital septum is the lid fascia (Q81), and the fissures are bony slits. Tenon''s = the socket lining the eyeball moves within."}'),
  ('dfdcdccd-g','{"options": ["orbital septum", "bulbar fascia", "superior orbital fissure", "inferior orbital fissure"], "correct": 0, "explanation": "The orbital septum is the palpebral fascia, the fibrous sheet of the lids that contains orbital fat and acts as a barrier to infection spread. Bulbar fascia is Tenon''s (Q80). Orbital septum = the lid''s fascial curtain."}'),
  ('02287580-n','{"options": ["orbital septum", "bulbar fascia", "superior orbital fissure", "inferior orbital fissure"], "correct": 3, "explanation": "The sphenomaxillary fissure is another name for the inferior orbital fissure, lying between the greater wing of the sphenoid and the maxilla. The superior orbital fissure is the sphenoidal fissure; the orbital septum and bulbar fascia are not fissures. Inferior orbital fissure = sphenomaxillary fissure."}'),
  ('e4b1d13a-l','{"options": ["mastoid sinuses", "sphenoid sinus", "maxillary antrum", "frontal sinuses"], "correct": 0, "explanation": "Same rule as Q69: the mastoid air cells are temporal-bone spaces, not paranasal sinuses. The paranasal sinuses are frontal, ethmoid, sphenoid, and maxillary. Mastoid is the odd one out."}'),
  ('be93c792-12','{"options": ["nasal bone", "ethmoid bone", "lacrimal bone", "cheek bone"], "correct": 0, "explanation": "The nasal bone does NOT form part of the orbit. The orbit is built from frontal, sphenoid, zygomatic (cheek), maxilla, lacrimal, ethmoid, and palatine bones. So ethmoid, lacrimal, and cheek/zygomatic all contribute; nasal does not. Seven orbital bones, nasal not among them."}'),
  ('8c47bb6d-1l','{"options": ["maxilla", "ethmoid bone", "frontal bone", "sphenoid bone"], "correct": 0, "explanation": "The maxilla is a PAIRED bone, so it is the one that is NOT unpaired. The single midline bones contributing to the orbit are the ethmoid, frontal, and sphenoid (unpaired). Unpaired = ethmoid/frontal/sphenoid; paired = maxilla (and zygomatic, lacrimal, palatine)."}'),
  ('30c6553d-p','{"options": ["floor", "roof", "lateral wall", "medial wall"], "correct": 3, "explanation": "The medial wall is the weakest orbital wall because of the wafer-thin lamina papyracea of the ethmoid. (The floor is the most commonly fractured in blowouts, but by thinness the medial wall is weakest.) Q87 gives the reason. Thinnest wall = medial (lamina papyracea)."}'),
  ('72c52af8-12','{"options": ["due to many sinuses at this wall", "bones are not firmly connected to each other", "it is not protected zygomatic bone", "due to weak os planum"], "correct": 3, "explanation": "The medial wall is weak because of the paper-thin os planum/lamina papyracea of the ethmoid. The other choices misstate the anatomy. Os planum = lamina papyracea, literally ''flat plate'', which is why the medial wall and the ethmoid sinuses behind it give way easily."}'),
  ('7beaf112-s','{"options": ["EOM", "optic nerve", "ophthalmic artery", "facial nerve"], "correct": 3, "explanation": "The facial nerve (CN VII) is NOT a content of the orbit; it runs to the face and supplies orbicularis oculi from outside. The orbit contains the EOMs, optic nerve, and ophthalmic artery (plus veins, fat, and CN III/IV/VI/V1). VII stays outside the orbit."}'),
  ('23504d79-2f','{"options": ["sella turcica", "os planum", "lateral tubercle", "trochlea"], "correct": 0, "explanation": "The sella turcica (''Turkish saddle'') is the saddle-shaped depression of the sphenoid that holds the pituitary gland. Os planum is the thin ethmoid plate, the trochlea is the superior oblique pulley (Q90), and the lateral tubercle anchors the lateral check ligament. Sella turcica = pituitary seat."}'),
  ('bb40347d-2b','{"options": ["sella turcica", "os planum", "lateral tubercle", "trochlea"], "correct": 3, "explanation": "The trochlea is the cartilaginous/fibrous pulley on the upper medial orbit through which the superior oblique tendon turns before inserting. Sella turcica holds the pituitary, os planum is ethmoid, the lateral tubercle is a fascial anchor. Trochlea = pulley for the superior oblique (the muscle even gets CN IV, the ''trochlear'' nerve)."}'),
  ('ee837473-k','{"options": ["10-25 mm after 5 mins", "15-34 seconds", "more than 25 mm after 2 minutes", "presence of dye at nose in 5 minutes"], "correct": 1, "explanation": "Normal tear break-up time (TBUT) is on the order of 15-34 seconds (any value above ~10 seconds is considered stable). The 10-25 mm/5 min option is Schirmer''s, the dye-at-nose option is Jones I, and >25 mm/2 min is a distractor. TBUT is measured in SECONDS, which rules out the millimeter choices."}'),
  ('03a73ca2-s','{"options": ["10-25 mm after 5 mins", "15-34 seconds", ">25 mm after 2 minutes", "presence of dye at nose in 15 minutes"], "correct": 3, "explanation": "Jones test I is positive when fluorescein dye reaches the nose/inferior meatus within the allotted time, here ''dye at nose in 15 minutes'', confirming a patent, functioning drainage system. The millimeter/second options describe Schirmer''s and TBUT. Jones = dye recovery at the nose."}'),
  ('cb320ae5-x','{"options": ["10-25 mm after 5 mins", "15-34 seconds", ">25 mm after 2 minutes", "presence of dye at nose in 15 minutes"], "correct": 0, "explanation": "Schirmer''s test I normal is roughly 10-25 mm of wetting after 5 minutes (>=15 mm is comfortably normal; <5-10 mm suggests dry eye). The seconds option is TBUT and the dye-at-nose option is Jones. Schirmer is measured in millimeters over 5 minutes."}'),
  ('e0e9a811-2e','{"options": ["lacrimal papilla", "lacrimal puncta", "lacrimal canaliculi", "lacrimal lake"], "correct": 1, "explanation": "The lacrimal puncta are the small openings at the medial lid margins where tears first enter the drainage (excretory) system. The lacrimal papilla is the elevation bearing the punctum, the canaliculi come next, and the lacrimal lake is the tear pool. Drainage begins at the puncta."}'),
  ('3b39adb8-l','{"options": ["lissamine green", "Rose Bengal dye", "methylene blue", "fluorescein dye"], "correct": 3, "explanation": "TBUT uses fluorescein dye, which fluoresces under cobalt-blue light so you can time the first dry spot. Lissamine green and Rose Bengal stain devitalized cells, and methylene blue is not used for TBUT. Fluorescein + cobalt blue = TBUT."}'),
  ('cb7ffdc8-1d','{"options": ["Schirmer’s test", "TBUT", "fluorescein dye test", "none of the above"], "correct": 2, "explanation": "Patency of the lacrimal drainage passage is checked with the fluorescein dye test (dye disappearance / Jones-type testing). Schirmer''s measures tear quantity and TBUT measures stability, neither tests drainage. Dye test = is the pipe open?"}'),
  ('d69d3653-13','{"options": ["Schirmer’s test", "TBUT", "fluorescein dye test", "dark room test"], "correct": 0, "explanation": "SCHIRMER''S test measures tear QUANTITY (aqueous production, mm wetting/5 min). TBUT = quality/stability; fluorescein = surface/patency. Quantity = Schirmer."}'),
  ('60984b27-12','{"options": ["Schirmer’s test", "TBUT", "fluorescein dye test", "swinging flashlight test"], "correct": 1, "explanation": "TBUT (tear break-up time) measures tear QUALITY/stability (how long the film stays intact). Schirmer = quantity; fluorescein dye = patency/defects. Quality/stability = TBUT."}'),
  ('76ede7e1-1t','{"options": ["Stimulation of non-identical points, will still result to single vision as long as it falls on the panum’s area; with the same clarity as stimulation of identical points falling on the horopter", "The image seen by the fovea, if disparate points are stimulated, will always be clearer", "Stimulation of corresponding retinal points falling on the horopter will result to single and clear image", "Both b and c"], "correct": 0, "explanation": "FALSE statement = the answer. Disparate (non-corresponding) points inside Panum''s area DO fuse into single vision, but NOT with the same clarity as true corresponding-point stimulation on the horopter — slight disparity is the very basis of stereopsis, so option A overstates it. B and C are both true (foveal image is clearer; corresponding points give single clear vision), so ''both b and c'' is true. Pearl: horopter = zero disparity (sharpest single vision); Panum''s area = small disparity still fused (depth)."}'),
  ('7804056c-29','{"options": ["Inferior Rectus.", "Superior Oblique.", "Inferior Oblique.", "Lateral Rectus."], "correct": 0, "explanation": "Right eye moving OUT (abduction) and DOWN = the muscle that depresses in abduction is the INFERIOR RECTUS (the recti act maximally in abduction; obliques in adduction). SO depresses in adduction; IO elevates in adduction; LR only abducts. Framework: ''RAD-LAB'' — Recti ADduct... no: recti are primary depressors/elevators when the eye is ABducted, obliques when ADducted. So out+down → IR."}'),
  ('10d5615d-1n','{"options": ["Diplopia for objects nearer than the point of binocular fixation", "Right and left fovea are stimulated at distance fixation", "Common on exophoric conditions", "None of the above"], "correct": 3, "explanation": "EXCEPT question. Crossed physiologic diplopia = images of objects NEARER than fixation fall on temporal retinas and are projected crossed (common in exo conditions) — so A and C are true features. B (both foveas stimulated at distance fixation) is also a true setup. Since A, B, C are all true descriptions, ''None of the above'' (D) is the correct EXCEPT answer. Cross-link: uncrossed physiologic diplopia (Q22) = objects beyond fixation."}'),
  ('f6dac5f9-29','{"options": ["Right", "Left", "Center", "No projection"], "correct": 0, "explanation": "Image on the LEFT (nasal/temporal) retina is projected to the OPPOSITE side of space — the retina inverts and reverses, so a LEFT temporal retinal image is localized to the RIGHT. Mnemonic: the retina maps space oppositely (temporal retina sees the nasal field, etc.); ''image left → seen right.''"}'),
  ('f44aff6c-3z','{"options": ["Baseline", "Primary sagittal line", "Plane of regard", "Line of sight"], "correct": 1, "explanation": "The primary sagittal (mid-sagittal) line bisects the interocular axis in the primary position of the plane of regard. The plane of regard is the plane containing both lines of sight; the line of sight runs from fixation to the eye''s center of rotation (Q12). Distractors confuse the reference line with the plane or the visual line."}'),
  ('9ba7cb23-3e','{"options": ["Angle alpha", "Angle lambda", "Angle gamma", "Angle beta"], "correct": 2, "explanation": "Angle gamma is between the line of sight and the optic axis, taken at the center of rotation (about 13.5 mm behind the cornea). Angle alpha uses the visual axis at the nodal point; lambda uses the pupillary axis. Center-of-rotation angle = gamma."}'),
  ('fadb1bb2-3d','{"options": ["Iso-oxyopia", "Aniso-oxyopia", "Aniseikonia", "Iseikonia"], "correct": 3, "explanation": "ISEIKONIA = equal retinal image SIZE in the two eyes, a prerequisite for fusion. ANISEIKONIA is unequal image size (a fusion obstacle, e.g., in anisometropia/aphakia). ''Iso/aniso-oxyopia'' are distractors about acuity, not image size. Cross-link: aniseikonia >5% breaks fusion — why high anisometropia is often fit with contact lenses."}'),
  ('a6413a55-2w','{"options": ["Dextroinfraversion", "Dextrosupraversion", "Levoinfraversion", "Levosupraversion"], "correct": 1, "explanation": "Yoke (conjugate) muscles RSR + LIO both ELEVATE; their combined version takes the eyes up-and-to-the-RIGHT = dextrosupraversion. Framework: yoke pairs move the eyes together into the 9 diagnostic positions (Hering''s law, Q28). RSR/LIO = up-right; RIR/LSO = down-right, etc. ''Dextro'' = to the right, ''supra'' = up."}'),
  ('d4516673-32','{"options": ["Dextroinfraversion", "Dextrosupraversion", "Levoinfraversion", "Levosupraversion"], "correct": 2, "explanation": "Right superior oblique (depresses the right eye in adduction) with left inferior rectus (depresses the abducted left eye) gives gaze down and to the left: levoinfraversion. RSO + LIR = down-left gaze."}'),
  ('c5c18173-29','{"options": ["Visual axis", "Line of sight", "Optic axis", "Pupillary axis"], "correct": 1, "explanation": "The LINE OF SIGHT runs from the object of regard to the eye''s center of rotation (~13.5 mm behind the cornea) — the reference for prism and Hirschberg. The VISUAL AXIS passes through the nodal points to the fovea; the OPTIC AXIS is the best-fit symmetry axis; the PUPILLARY axis is normal to the cornea through the pupil center. Cross-link: angle gamma (Q7) is line-of-sight vs optic axis."}'),
  ('d6b8df6b-2y','{"options": ["Levosupraversion", "Levoinfraversion", "Dextrosupraversion", "Dextroinfraversion"], "correct": 3, "explanation": "Right inferior rectus (depresses right eye in abduction) plus left superior oblique (depresses left eye in adduction) gives gaze down and to the right: dextroinfraversion. RIR + LSO = down-right gaze."}'),
  ('21ac54fd-22','{"options": ["Most extra ocular muscle is innervated by the oculomotor nerve", "All extraocular muscles except inferior rectus originate from the annulus of Zinn", "Medial rectus is the strongest and broadest muscle and has the closest insertion from limbus", "Superior rectus is the longest extraocular muscle if the tendon is excluded"], "correct": 1, "explanation": "The false statement is that all extraocular muscles EXCEPT the inferior rectus arise from the annulus of Zinn; the true exception is the inferior OBLIQUE (it arises from the orbital floor/maxilla). All others, including the inferior rectus, start at the annulus of Zinn."}'),
  ('71eebca3-39','{"options": ["Presence of spot or streak of light", "Spot of light to the right of the streak of light", "Streak of light to the right of the spot of light", "Streak of light to the left of the spot of light"], "correct": 2, "explanation": "Maddox rod before the RIGHT eye in an esophore: with a horizontal-bar rod producing a VERTICAL streak, esophoria gives uncrossed diplopia, so the streak (right eye''s image) appears to the RIGHT of the spot (the streak is on the same side as the eye it''s before in eso). Esophoria = uncrossed = streak ipsilateral. Cross-link: exophoria = crossed = streak on the opposite side (Q49)."}'),
  ('e54c4c28-26','{"options": ["Fovea has acquired a common visual direction with an extra foveal area of the other eye", "Adaptation results from an alternate fixation and deviation of both eyes", "It results to single vision because of the re orientation", "Requires a long standing constant and unilateral deviation"], "correct": 1, "explanation": "EXCEPT question. ARC is an adaptation in LONG-STANDING, CONSTANT, UNILATERAL strabismus where the fovea of the fixing eye gains a common visual direction with an extrafoveal point of the deviating eye (A, C, D true). B is false because ARC develops in CONSTANT unilateral deviation, NOT alternating fixation (alternation tends to preserve normal correspondence). Pearl: ARC needs a constant turn; alternation protects against it."}'),
  ('b3f602b7-20','{"options": ["Incycloduction", "Incycloversion", "Conclination", "Sursumversion"], "correct": 2, "explanation": "Both eyes'' vertical corneal meridians rotating inward (tops toward the nose) = intorsion of both eyes simultaneously = CONCLINATION (incyclovergence). ''Incycloduction'' is the monocular term; conclination is the binocular disjunctive torsion. Mnemonic: con-clination = the tops ''come'' together toward the nose."}'),
  ('2b37e1d7-3i','{"options": ["Two or three dots", "Four dots", "5 dots uncrossed projection", "5 dots crossed projection"], "correct": 3, "explanation": "Acquired exotropia with NORMAL retinal correspondence on Worth 4-dot: the eyes are diverged but project normally, giving DIPLOPIA. Exo deviation → CROSSED diplopia → 5 dots in crossed projection (the 2 red and 3 green separate, crossed). Cross-link: eso would give uncrossed 5-dot; ARC or suppression gives fused 4 or 2/3 dots (Q44)."}'),
  ('e3a4e02d-2n','{"options": ["Pathological", "Physiological", "Crossed", "Uncrossed"], "correct": 3, "explanation": "Diplopia for objects BEYOND the fixation point = UNCROSSED (homonymous) physiologic diplopia — far objects fall on nasal retinas, projected uncrossed. It is PHYSIOLOGIC (normal), but the precise term asked is ''uncrossed.'' Cross-link: nearer-than-fixation objects → crossed diplopia (Q4). Demo: hold two fingers in line; the far one doubles uncrossed."}'),
  ('f9431dc7-1k','{"options": ["The extent of common binocular visual field is 120 degrees", "Non-decussation of optic nerve fibers is required so that part of the image seen by the right is also seen by the left eye", "There should be equal size of retinal images for fusion to happen"], "correct": 1, "explanation": "[Source-review: one option didn''t extract.] FALSE statement = answer. Non-DECUSSATION isn''t what binocular single vision requires — fusion needs the PARTIAL decussation at the chiasm so each hemisphere receives both eyes'' view of one hemifield; saying ''non-decussation is required'' (B) is false. True: common binocular field ~120° (A) and equal image size for fusion (C). Cross-link: partial decussation underlies homonymous field defects (Q97)."}'),
  ('463184d6-1d','{"options": ["Horizontal Maddox rod is used for lateral phoria assessment", "Presence of only a streak or spot of light indicates suppression", "Vertical Maddox rod is used for lateral phoria assessment", "Vertical streak of light is used for lateral phoria assessment"], "correct": 2, "explanation": "EXCEPT question. The Maddox rod streak is PERPENDICULAR to the rod axis; a HORIZONTAL rod gives a vertical streak for LATERAL (horizontal) phorias and a vertical rod gives a horizontal streak for VERTICAL phorias. So C (''vertical Maddox rod for lateral phoria'') is FALSE = answer. A is true, B is true (single image = suppression). Mnemonic: streak runs 90° to the rod grooves."}'),
  ('5bd92c9d-1b','{"options": ["RSR, LIO", "RIR, LSR", "RSO, LIO", "RIO, LSO"], "correct": 3, "explanation": "Dextrocycloversion (both eyes rotate their vertical meridians clockwise toward the patient''s right) uses RIO + LSO. Torsion muscles are the obliques (primary) plus SR/IR (secondary): for a rightward cyclo-version you pair the right intortor pattern with the left — RIO (extorts OD) and LSO (intorts OS) give the clockwise-from-patient torsion. Use the torsion grid; obliques dominate cyclo movements."}'),
  ('1d560d0e-1z','{"options": ["Vertical axis", "Transverse axis", "X-axis", "Both b and c"], "correct": 0, "explanation": "Horizontal (side-to-side) eye movement occurs about the VERTICAL (Z) axis of Fick — rotation around a vertical axis swings the eye left/right. Vertical movement is about the transverse (X) axis; torsion is about the anteroposterior (Y) axis. Axes of Fick: X (transverse) = up/down, Z (vertical) = left/right, Y (sagittal) = torsion."}'),
  ('5ba61f9f-2c','{"options": ["Horizontal plane", "Median plane", "Equatorial plane", "Plane of regard"], "correct": 2, "explanation": "The EQUATORIAL plane is formed by the vertical (Z) and transverse (X) axes intersecting at the center of rotation — it divides the globe into front and back halves. The other listmerian planes (horizontal, median/sagittal) pair different axes. Cross-link: Listing''s plane (the equatorial plane in primary position) governs torsion-free eye movements (Listing''s law)."}'),
  ('43d752bc-3g','{"options": ["Herring’s Law of Equal Innervation", "Sherrington’s Law of Reciprocal Innervation", "Doctrine of Corresponding Points", "Sheard’s Criterion"], "correct": 1, "explanation": "Reciprocal innervation of a muscle and its direct antagonist in the SAME eye (right MR contracts while right LR relaxes) is SHERRINGTON''S law. HERING''S law governs EQUAL innervation to YOKE muscles of the TWO eyes. Don''t confuse: Sherrington = within one eye (agonist/antagonist); Hering = between the two eyes (yokes). The Doctrine of Corresponding Points and Sheard''s criterion are unrelated."}'),
  ('356a1140-3o','{"options": ["Four dots", "2 dots", "3 dots", "Diplopia response"], "correct": 0, "explanation": "Long-standing strabismus WITH ARC on Worth 4-dot: the anomalous correspondence allows ''fusion,'' so the patient reports FOUR dots despite a manifest deviation (harmonious ARC mimics normal fusion). Contrast: strabismus with NRC gives diplopia (5 dots); suppression gives 2 or 3. Pearl: ARC = ''4 dots with a turn.''"}'),
  ('06db26f8-8b','{"options": ["Recommend vision therapy to improve reading skills and reduce eye strain.", "Prescribe corrective lenses to address the hyperopia and alleviate the eye strain and headaches.", "Advise the parents to monitor the child’s symptoms and return if they persist.", "Perform additional testing to evaluate for any binocular vision disorders.", "Suggest increasing the child''s outdoor activity to reduce eye strain."], "correct": 1, "explanation": "A hyperopic child with eyestrain and headaches on reading but good acuity needs corrective lenses to relieve the accommodative demand. Glasses, not therapy or watchful waiting, address the uncorrected hyperopia. Symptomatic hyperope = prescribe the correction."}'),
  ('02ab7250-75','{"options": ["Increase the duration of occlusion therapy to further enhance visual acuity.", "Initiate vision therapy focused on improving binocular vision and depth perception.", "Schedule a follow-up visit to monitor for any new visual issues.", "Consider surgical intervention if there are signs of residual strabismus.", "Reassess the child’s refractive error and update the prescription if needed."], "correct": 1, "explanation": "Once alignment and acuity have improved but depth perception lags, vision therapy aimed at binocular vision and stereopsis is the right next step. Build the binocularity now that the eye sees. Residual depth deficit = binocular vision therapy."}'),
  ('5ad2259a-9e','{"options": ["Re-evaluate the child’s visual acuity to confirm that it is within normal limits.", "Perform a color vision test to ensure there are no underlying color perception issues.", "Suggest the use of reading glasses to reduce eye strain.", "Recommend a comprehensive eye exam to rule out any ocular diseases.", "Assess for possible accommodative dysfunction or binocular vision problems that could be affecting near vision."], "correct": 4, "explanation": "Near difficulty and eye rubbing that worsen with reading, with normal acuity and no strabismus, point to accommodative or binocular vision dysfunction, which should be assessed. Look beyond acuity to the focusing/teaming system. Near strain, normal VA = test accommodation/BV."}'),
  ('986e97d7-7b','{"options": ["Prescribe corrective lenses to manage any refractive errors contributing to the esotropia.", "Refer the child for a full assessment of binocular vision and potential strabismus treatment options.", "Increase the frequency of follow-up visits to monitor changes in eye alignment.", "Recommend vision therapy to address coordination issues and improve eye alignment.", "Suggest occupational therapy to help with hand-eye coordination difficulties."], "correct": 1, "explanation": "A measured 10 prism diopter esotropia (Krimsky) with poor coordination warrants referral for a full binocular vision and strabismus assessment. A manifest tropia needs proper work-up, not just monitoring. Manifest esotropia = refer for strabismus assessment."}'),
  ('b3a57235-16','{"options": ["To prescribe corrective lenses for refractive errors.", "To perform surgical procedures to correct visual impairments.", "To provide medication for eye diseases.", "To improve visual skills and abilities, including binocular vision, eye movement control, and perception.", "To treat visual impairments solely through pharmacological means."], "correct": 3, "explanation": "The primary goal of vision therapy is to improve visual skills and abilities (binocular vision, eye-movement control, perception). It is not surgery, drugs, or simply prescribing lenses. VT builds visual skills."}'),
  ('aa06adde-21','{"options": ["Cataracts", "Glaucoma", "Retinal detachment", "Strabismus", "Macular degeneration"], "correct": 3, "explanation": "Strabismus is the classic condition addressed by vision therapy; cataract, glaucoma, retinal detachment, and AMD are medical/surgical. VT target = strabismus (and related functional disorders)."}'),
  ('b9a145b8-28','{"options": ["Saccadic tracking exercises", "Accommodative rock", "Pencil push-ups", "Peripheral vision exercises", "Visual scanning tasks"], "correct": 2, "explanation": "Pencil push-ups are the standard exercise to build convergence. Saccadic and scanning tasks train eye movements, not convergence. Convergence training = pencil push-ups."}'),
  ('ac4aff2b-43','{"options": ["Prism adaptation", "Visual acuity enhancement", "Color vision training", "Contrast sensitivity training", "Tracking exercises"], "correct": 4, "explanation": "Skipping lines while reading is a tracking (ocular motor) problem, so tracking exercises help. Tracking deficit = tracking exercises."}'),
  ('08106496-1s','{"options": ["To strengthen the eye muscles to reduce strabismus.", "To enhance peripheral vision.", "To correct color vision deficiencies.", "To increase visual acuity.", "To improve the eye’s ability to focus on near and distant objects."], "correct": 4, "explanation": "Accommodative exercises improve the eye''s ability to focus across near and distant targets. They train the focusing system, not the muscles for alignment or color. Accommodation training = focus flexibility."}'),
  ('a5e55644-32','{"options": ["Binocular fusion", "Convergence", "Accommodation", "Depth perception", "Saccadic eye movement"], "correct": 4, "explanation": "Quickly shifting fixation from one object to another trains saccadic eye movements. Rapid refixation = saccades."}'),
  ('81989aff-2i','{"options": ["Prism lenses", "Visual field training", "Color vision tests", "Depth perception drills", "Patch therapy"], "correct": 4, "explanation": "Amblyopia is classically treated with patch (occlusion) therapy to force use of the weaker eye. Amblyopia = patching."}'),
  ('49d75336-1r','{"options": ["To correct alignment issues by shifting the image to improve binocular vision.", "To increase the visual acuity.", "To treat dry eye symptoms.", "To reduce glare sensitivity", "To enhance color perception."], "correct": 0, "explanation": "Prisms in vision therapy shift the image to correct alignment and stimulate binocular vision/fusion. Prisms move the image to build binocularity."}'),
  ('3a40f5af-1v','{"options": ["To correct refractive errors.", "To strengthen the eye muscles for better focusing.", "To increase visual acuity in low-light conditions.", "To train the eye to see in color.", "To improve the coordination and alignment of the eyes to work together effectively."], "correct": 4, "explanation": "Binocular fusion exercises improve the coordination and alignment of the two eyes so they work together effectively. Fusion training = teaming the eyes."}'),
  ('df2d3af3-2q','{"options": ["Increased sensitivity to light.", "Blurred vision only at a distance.", "Persistent double vision without binocular issues.", "Frequent difficulty in tracking moving objects smoothly.", "Difficulty distinguishing between red and green colors."], "correct": 3, "explanation": "Frequent difficulty tracking moving objects smoothly signals an eye-movement (pursuit) disorder needing therapy. Poor smooth tracking = ocular motor therapy."}'),
  ('0d6263b4-2f','{"options": ["Prism adaptation", "Visual field expansion exercises", "Peripheral vision training", "Contrast sensitivity training", "Eye-hand coordination exercises"], "correct": 4, "explanation": "Eye-hand coordination exercises address visual-motor integration. Visual-motor integration = eye-hand coordination drills."}'),
  ('250246ed-2m','{"options": ["Far vision acuity testing", "Peripheral vision drills", "Convergence exercises with a near target, such as Brock string or convergence cards.", "Color vision exercises", "Contrast sensitivity training"], "correct": 2, "explanation": "Convergence insufficiency is treated with near convergence exercises such as the Brock string or convergence cards. CI = near convergence training."}'),
  ('452e58ea-31','{"options": ["To improve overall cognitive function", "To increase the child’s IQ", "To correct anatomical issues in the eyes", "To enhance social skills and interaction", "To enhance visual processing skills and reduce visual stress during reading and other academic tasks."], "correct": 4, "explanation": "For learning-related visual problems, vision therapy mainly enhances visual processing and reduces visual stress during reading and schoolwork. It does not raise IQ or fix anatomy. Learning-related VT = better visual processing, less reading stress."}'),
  ('f4ace4b8-2o','{"options": ["Cataracts", "Nystagmus", "Glaucoma", "Retinitis pigmentosa", "Age-Related Macular Degeneration"], "correct": 1, "explanation": "Nystagmus is an eye-movement disorder that vision therapy can help address. Cataract, glaucoma, RP, and AMD are medical. Eye-movement disorder = nystagmus."}'),
  ('7533802c-4l','{"options": ["Prism adaptation to correct misalignment.", "Binocular fusion exercises to enhance eye coordination.", "Peripheral vision exercises to broaden the field of view.", "Color vision training to address potential color deficiencies.", "Accommodative exercises to improve the eye''s focusing ability."], "correct": 4, "explanation": "Difficulty sustaining near focus with blur and discomfort calls for accommodative exercises to improve focusing stamina. Sustained-focus problem = accommodative therapy."}'),
  ('857188a2-1i','{"options": ["Fixation", "Depth perception", "Saccadic eye movements", "Binocular coordination", "Visual acuity"], "correct": 0, "explanation": "Fixation is the first visual skill to develop in infants (the foundation for tracking and other skills). First milestone = fixation."}'),
  ('fae7de5c-1j','{"options": ["By 3 to 4 months of age", "By 6 months of age", "By 9 months of age", "By 12 months of age", "By 18 months of age"], "correct": 0, "explanation": "Color vision generally emerges by about 3 to 4 months of age. Color vision onset = 3 to 4 months."}'),
  ('c57712d9-28','{"options": ["3 to 6 months", "6 to 9 months", "9 to 12 months", "12 to 18 months", "18 to 24 months"], "correct": 0, "explanation": "Binocular vision (including emerging stereopsis) develops in roughly the 3 to 6 month window. Binocularity = about 3 to 6 months."}'),
  ('cf56d1f7-2i','{"options": ["Lack of response to visual stimuli", "Frequent blinking", "Consistent tracking of moving objects", "Ability to reach for objects", "Smooth eye movements"], "correct": 0, "explanation": "A lack of response to visual stimuli is an early red flag for visual developmental problems. Consistent tracking and reaching are normal. No response to stimuli = warning sign."}'),
  ('e8081cac-1x','{"options": ["Development of stereopsis", "Development of full color vision", "Ability to identify and name colors", "Improvement in visual acuity to adult levels", "Ability to reach for and grasp objects using visual guidance"], "correct": 4, "explanation": "By about 6 months the key milestone is reaching for and grasping objects using visual guidance. 6 months = visually guided reach/grasp."}'),
  ('6c013f1e-1z','{"options": ["1 year", "3 years", "6 to 7 years", "9 years", "12 years"], "correct": 2, "explanation": "Near-adult visual acuity is typically reached around 6 to 7 years of age. Adult-level acuity = about 6 to 7 years."}'),
  ('74e2a4eb-27','{"options": ["Tracking objects with both eyes", "Using both eyes together effectively", "Recognizing familiar faces from a distance", "Reading small print accurately", "Detecting peripheral motion"], "correct": 0, "explanation": "Around 3 months, infants begin tracking objects with both eyes together. 3 months = binocular tracking begins."}'),
  ('260f295f-2m','{"options": ["Ability to track moving objects smoothly", "Ability to recognize primary colors", "Ability to reach accurately for objects at varying distances", "Ability to detect motion at the edge of their visual field", "Ability to name familiar objects"], "correct": 2, "explanation": "Reaching accurately for objects at varying distances signals the developing ability to see in 3D (stereopsis). Accurate reaching across distances = emerging 3D vision."}'),
  ('642d5a56-2d','{"options": ["Visual tracking and scanning", "Near vision acuity at adult levels", "Advanced depth perception", "Ability to discriminate between complex shapes and patterns", "Full binocular vision coordination"], "correct": 0, "explanation": "Visual tracking and scanning are typically well established by about 2 to 3 years of age. Tracking/scanning = developed by 2 to 3 years."}'),
  ('082c5764-35','{"options": ["Moro reflex", "Grasp reflex", "Rooting reflex", "Babinski reflex", "Tonic neck reflex"], "correct": 1, "explanation": "The grasp (palmar) reflex is the automatic closing of the hand around an object placed in the palm. Grasp object in palm = grasp reflex."}'),
  ('244441b8-3j','{"options": ["1 month", "3 to 4 months", "6 months", "9 months", "12 months"], "correct": 1, "explanation": "The rooting reflex typically fades by about 3 to 4 months. Rooting disappears = 3 to 4 months."}'),
  ('4b47a90b-2u','{"options": ["Moro reflex", "Rooting reflex", "Stepping reflex", "Grasp reflex", "Tonic neck reflex"], "correct": 0, "explanation": "The Moro (startle) reflex makes the infant fling out the arms and legs in response to a sudden drop or loud noise. Startle/extend limbs = Moro."}'),
  ('cd3aa939-3y','{"options": ["Grasp reflex", "Tonic neck reflex", "Moro reflex", "Stepping reflex", "Rooting reflex"], "correct": 1, "explanation": "The tonic neck reflex (fencer''s posture): when the head turns to one side, that side''s limbs extend while the opposite side flexes. Head-turn fencing posture = tonic neck reflex."}'),
  ('4cb66ca2-3g','{"options": ["Moro reflex", "Grasp reflex", "Stepping reflex", "Babinski reflex", "Tonic neck reflex"], "correct": 2, "explanation": "The stepping reflex appears when an infant held upright on a surface makes stepping movements. Upright stepping = stepping reflex."}'),
  ('26931f72-2n','{"options": ["1 month", "6 months", "9 months", "12 months", "18 months"], "correct": 1, "explanation": "The asymmetric tonic neck reflex (ATNR) usually fades by about 6 months. ATNR gone = about 6 months."}'),
  ('ca4b9970-37','{"options": ["Moro reflex", "Grasp reflex", "Rooting reflex", "Stepping reflex", "Babinski reflex"], "correct": 2, "explanation": "Stroking the cheek so the infant turns the head and opens the mouth tests the rooting reflex. Cheek-turn-to-feed = rooting reflex."}'),
  ('6dbf3c66-31','{"options": ["Moro reflex", "Grasp reflex", "Tonic neck reflex", "Rooting reflex", "Stepping reflex"], "correct": 1, "explanation": "Toes curling in response to pressure on the sole is the plantar grasp reflex (toes curl IN, versus Babinski where they fan OUT). Toes curl in = grasp reflex."}'),
  ('583b45bd-2h','{"options": ["1 month", "4 to 6 months", "9 months", "12 months", "18 months"], "correct": 1, "explanation": "The Moro (startle) reflex typically disappears by about 4 to 6 months. Moro gone = 4 to 6 months."}'),
  ('9d545399-23','{"options": ["To enhance peripheral vision through dynamic field exercises", "To improve binocular vision and depth perception through controlled visual tasks", "To measure intraocular pressure for glaucoma diagnosis", "To assess and treat color vision deficiencies", "To prescribe corrective lenses for refractive errors"], "correct": 1, "explanation": "The Vodnoy trainer is used to improve binocular vision and depth perception through controlled visual tasks. Vodnoy = binocular/depth training."}'),
  ('e258bea9-2n','{"options": ["Island/Hill of Vision", "Visual Field", "Isopters", "Plane"], "correct": 1, "explanation": "The VISUAL FIELD is the portion of space seen during STEADY fixation in one gaze direction — the functional definition. The ''hill/island of vision'' is the 3-D sensitivity map (Q78); isopters are the boundary contours (Q77); a plane is geometric. Distinguish the SPACE (field) from its sensitivity REPRESENTATION (island)."}'),
  ('e3c62a36-20','{"options": ["Island/Hill of Vision", "Visual Field", "Isopters", "Plane"], "correct": 2, "explanation": "ISOPTERS are the contour lines bounding zones of EQUAL retinal sensitivity on the field (like elevation contours on the island of vision) — drawn in kinetic perimetry by plotting where a given target is just seen. The island/hill is the whole 3-D surface; the field is the space. Isopter = a single sensitivity boundary line."}'),
  ('f901d76c-1q','{"options": ["Island/Hill of Vision", "Visual Field", "Isopters", "Plane"], "correct": 0, "explanation": "The ISLAND/HILL OF VISION (Traquair) is the 3-D representation of MONOCULAR field SENSITIVITY and extent — peak at the fovea, sea level at the absolute periphery, with the blind-spot ''well.'' The visual field is the 2-D space; isopters are its contours. Mnemonic: ''island of vision = mountain of sensitivity in a sea of blindness.''"}'),
  ('85cc3659-2e','{"options": ["Island/Hill of Vision", "Visual Field", "Isopters", "Plane"], "correct": 3, "explanation": "The PLANE (sea level) around the island represents the outermost margins where nothing is seen — the limit of the field beyond the island''s base. (Within the listed terms, ''plane'' denotes the non-seeing surround.) The island is the seeing surface; isopters are its rings. Conceptual anchor for the hill-of-vision model."}'),
  ('a03e66b7-1x','{"options": ["Relative", "Absolute", "Negative", "Positive"], "correct": 0, "explanation": "A RELATIVE scotoma = an area of DECREASED (but not absent) sensitivity — larger/brighter targets are still seen there. An ABSOLUTE scotoma = NO perception of any target (Q81). ''Positive/negative'' describe whether the patient is aware of it. Glaucomatous early defects are typically relative before becoming absolute."}'),
  ('7ca13c80-21','{"options": ["Relative", "Absolute", "Negative", "Positive"], "correct": 1, "explanation": "An ABSOLUTE scotoma = total ABSENCE of sensitivity — no target of any size/brightness is seen (e.g., the physiologic blind spot, Q82). Relative = reduced sensitivity. Severity ladder: relative (depressed) → absolute (no perception)."}'),
  ('07e81a0a-11','{"options": ["Relative Negative", "Absolute Negative", "Relative Positive", "Absolute Positive"], "correct": 1, "explanation": "The blind spot (optic disc) is an absolute scotoma (no photoreceptors, no sensitivity) and negative (the patient is unaware of it). Blind spot = absolute, negative scotoma."}'),
  ('228c1905-3v','{"options": ["Optic disc", "Retina", "Optic Nerve", "LGB"], "correct": 1, "explanation": "The retina, the thin transparent inner membrane where images fall on photoreceptors and nerve impulses begin. Hint: the eye''s ''film'' where light becomes signal = retina."}'),
  ('4cf9e7ad-1a','{"options": ["Rods", "Cones", "Rhodopsin", "Iodopsin"], "correct": 0, "explanation": "RODS mediate SCOTOPIC (dim-light/night) vision — high sensitivity, no color, peripheral predominance, containing RHODOPSIN. Cones (with iodopsin/photopsins) handle photopic/color vision (Q85). Duplicity theory: rods = dim/peripheral, cones = bright/central/color. Cross-link: Vitamin A regenerates rhodopsin (night blindness)."}'),
  ('1acefe3f-1a','{"options": ["Rods", "Cones", "Rhodopsin", "Iodopsin"], "correct": 1, "explanation": "CONES mediate PHOTOPIC (bright-light) and COLOR vision, concentrated at the fovea, containing iodopsin/photopsins. Rods (rhodopsin) serve night vision (Q84). ''Rhodopsin/iodopsin'' are the pigments, not the cells — the question asks for the cell type (cones)."}'),
  ('5ad7bd47-13','{"options": ["60", "75", "80", "90"], "correct": 0, "explanation": "Normal SUPERIOR visual field extent ≈ 60° (limited by the brow). Standard monocular extents: superior 60°, inferior 75° (Q87), nasal 60°, temporal 90-100°. Memorize the asymmetric box: brow limits up (60), cheek less so down (75), nose limits in (60), temple widest out (90+)."}'),
  ('165441a4-13','{"options": ["60", "75", "80", "90"], "correct": 1, "explanation": "Normal INFERIOR field ≈ 75° (cheek limits it less than the brow limits superior). With superior 60° (Q86), nasal 60°, temporal ~90°, the full monocular field is the asymmetric extent. Inferior > superior because of facial anatomy."}'),
  ('362c37d0-14','{"options": ["120", "150", "180", "30"], "correct": 1, "explanation": "MONOCULAR field extent (full horizontal+) is taken as ~150° (temporal ~90 + nasal ~60). The binocular overlap is ~120° (Q89), with ~30-35° temporal crescents seen by only one eye. Numbers: one eye ~150° horizontally; both eyes overlap ~120°."}'),
  ('8caee258-1a','{"options": ["120", "150", "180", "30"], "correct": 0, "explanation": "The BINOCULAR OVERLAP (region seen by BOTH eyes, where stereopsis is possible) ≈ 120°. Each eye alone spans ~150° (Q88); the non-overlapping ~30° temporal crescents are monocular. Stereopsis lives in the 120° overlap. Cross-link: common binocular field ~120° also appears in Q23."}'),
  ('96f6fb78-2h','{"options": ["Optic Nerve", "Optic Radiations", "Optic Tract", "LGB"], "correct": 2, "explanation": "The OPTIC TRACT is the continuation just past the chiasm where CROSSED (nasal) and UNCROSSED (temporal) fibers merge to carry the contralateral hemifield to the LGB. Optic nerve is pre-chiasm; optic radiations are post-LGB; LGB is the relay (Q91). Pathway order: nerve → chiasm → TRACT → LGB → radiations → cortex."}'),
  ('79319dee-1k','{"options": ["Optic Nerve", "Optic Radiations", "Optic Tract", "LGB"], "correct": 3, "explanation": "The LATERAL GENICULATE BODY (LGB/LGN) of the thalamus is the RELAY STATION between retina (via optic tract) and the visual cortex (via optic radiations) — 6 layers, magno/parvo organization. Tract delivers to it; radiations leave it. Mnemonic: LGB = the thalamic ''switchboard'' of vision."}'),
  ('7ffe6e0e-2i','{"options": ["Homonymous", "Heteronymous", "Congruous", "Incongruous"], "correct": 0, "explanation": "Homonymous, both field defects on the SAME side (e.g., both left). Hint: HOMOnymous = same side in both eyes."}'),
  ('9c8edfe9-2a','{"options": ["Homonymous", "Heteronymous", "Congruous", "Incongruous"], "correct": 2, "explanation": "When the two homonymous defects are EQUAL in extent/shape = CONGRUOUS — implying a more POSTERIOR lesion (occipital cortex/posterior radiations). INCONGRUOUS (unequal) defects suggest a more anterior lesion (optic tract). Rule: ''the more congruous, the more posterior.''"}'),
  ('8d761232-2n','{"options": ["Left Optic Tract", "Right Optic Tract", "Left Optic Radiations", "Right Optic Radiations"], "correct": 1, "explanation": "LEFT homonymous hemianopsia WITH a Wernicke''s hemianopic pupil reflex (pupil won''t react to light on the blind hemiretina) localizes to the RIGHT OPTIC TRACT — the tract carries pupillomotor fibers, so a tract lesion can give the hemianopic pupil; once past the LGB (radiations/cortex) the pupil reflex is spared. Wernicke''s pupil = tract-level lesion clue."}'),
  ('74e6f56b-1h','{"options": ["Superior Hemianopsia", "Inferior Hemianopsia", "Superior Quadrantanopsia", "Inferior Quadrantanopsia"], "correct": 2, "explanation": "A ''PIE IN THE SKY'' defect = SUPERIOR homonymous QUADRANTANOPSIA, from a lesion of the TEMPORAL-lobe (Meyer''s) loop of the optic radiation (inferior fibers carry the superior field). ''Pie on the floor'' = inferior quadrant = parietal radiation. Mnemonic: Temporal lesion → pie in the sky (superior)."}'),
  ('0924b7a7-29','{"options": ["Left homonymous hemianopsia", "Right homonymous hemianopsia", "Left homonymous hemianopsia w/ pupil defect", "Right homonymous hemianopsia w/ pupil defect"], "correct": 0, "explanation": "A RIGHT optic radiation lesion causes a LEFT homonymous hemianopsia (contralateral field), and because it''s POST-LGB the PUPIL reflex is SPARED (no Wernicke''s pupil). Contrast Q95 (tract lesion = pupil involved). Rule: lesion side opposite to field loss; pupil spared once past the LGB."}'),
  ('d1255359-4y','{"options": ["Presence of RAPD", "Presence of TAPD", "Presence of EPD", "No Pupillary Defect"], "correct": 3, "explanation": "Swinging flashlight: OD constricts directly, and when light swings to OS, OD MAINTAINS constriction (consensual response intact, no escape) = NO pupillary defect (normal). An RAPD would show OD re-dilating when the light reaches the worse eye. Here both direct and consensual are equal/maintained → normal. Baseline normal case for the series Q99/Q100."}'),
  ('0f0085bc-6l','{"options": ["Presence of RAPD at OD", "Presence of TAPD at OD", "Presence of TAPD at OS", "Presence of RAPD at OS"], "correct": 3, "explanation": "When the light swings to OS and OD then redilates, the eye being lit (OS) has the relative afferent defect: RAPD at OS. Dilation when light reaches an eye = that eye''s RAPD."}'),
  ('22fb18d1-3q','{"options": ["Optics", "Chemistry", "Biology", "Meteorology"], "correct": 0, "explanation": "Optics is the branch of physics dealing with the propagation and behavior of light and its interaction with matter. Study of light behavior = optics."}'),
  ('d0ae2f44-32','{"options": ["Physics", "Physiology", "Organic chemistry", "Microbiology"], "correct": 1, "explanation": "Physiology is the science of the normal functions of organisms and their parts. Normal function of living parts = physiology."}'),
  ('f6b9b933-1t','{"options": ["Refraction", "Reflection", "Dispersion", "Absorption"], "correct": 3, "explanation": "Absorption is the transformation of light into other forms of energy (e.g., heat). Light turned into other energy = absorption."}'),
  ('5433e209-4r','{"options": ["Refraction", "Interference", "Dispersion", "Diffraction"], "correct": 3, "explanation": "Diffraction is the bending/spreading of light around edges and into the geometric shadow. Bending around corners = diffraction."}'),
  ('8427aaf7-2r','{"options": ["Neuropodium", "Synapse", "Receptors", "Effectors"], "correct": 2, "explanation": "Receptors are the specialized end organs of sensory afferent neurons that respond to stimuli. Sensory end organs = receptors."}'),
  ('6a550c48-3b','{"options": ["Physical process", "Photochemical process", "Sensory transduction", "Neuromuscular process"], "correct": 0, "explanation": "The physical process is the impinging of light on the eye and its transmission through the ocular refractive media (before any chemistry). Light entering and passing through the media = physical process."}'),
  ('3d160773-3w','{"options": ["Transmutation", "Photosynthesis", "Photo transduction", "Image interpretation"], "correct": 2, "explanation": "In the photoreceptor layer light is absorbed and converted into electrical impulses: phototransduction. Light to electrical signal = phototransduction."}'),
  ('5b1735ba-4j','{"options": ["Physical process", "Photochemical process", "Sensory transduction", "Neuromuscular process"], "correct": 2, "explanation": "Sensory transduction is the conversion of a physical stimulus into an action potential carried along axons to the CNS. Stimulus to nerve signal = sensory transduction."}'),
  ('f6014a6e-1s','{"options": ["Heminaopia", "Altitude hemianopia", "Quadrantanopia", "Anopia"], "correct": 0, "explanation": "Blindness of the lateral half of the visual field is hemianopia (hemi = half, anopia = no vision). Half-field blindness = hemianopia."}'),
  ('2e008bd0-1k','{"options": ["Sattlers", "Hallers", "Choriocapillaries", "Ophthalmic artery"], "correct": 2, "explanation": "The choriocapillaris (choroidal capillary bed) supplies roughly the outer two-thirds (up to about 80%) of the retina''s blood, nourishing the photoreceptors. Outer retina blood = choriocapillaris."}'),
  ('a274cbd5-1q','{"options": ["Escherichia coli", "treponema pallidum", "streptococcus pneumoniae", "staphylococcus aureus"], "correct": 1, "explanation": "Treponema pallidum (the syphilis spirochete) is the organism behind the Argyll Robertson pupil. Syphilis = Treponema pallidum."}'),
  ('48e8815d-1m','{"options": ["Baum’s loop", "Meyer’s loop", "Loop of Henle", "Papillary loop"], "correct": 1, "explanation": "Meyer''s loop is the temporal (external) portion of the optic radiation that dips into the temporal lobe (its damage gives superior quadrantanopia). Temporal radiation = Meyer''s loop."}'),
  ('87908545-24','{"options": ["goblet cells of conjunctiva", "lacrimal gland", "meibomian gland", "salivary gland"], "correct": 0, "explanation": "The conjunctival goblet cells supply the mucin (inner) layer of the tear film. Mucin = goblet cells."}'),
  ('c6ad48d1-22','{"options": ["goblet cells of conjunctiva", "lacrimal gland", "meibomian gland", "salivary gland"], "correct": 2, "explanation": "The meibomian glands supply the oily (lipid, outer) layer of the tear film. Oil layer = meibomian glands."}'),
  ('e082ecd3-z','{"options": ["macula", "fovea", "optic disc", "peripheral retina"], "correct": 1, "explanation": "The fovea (centralis) is the area of keenest vision (highest cone density). Sharpest vision = fovea."}'),
  ('245571f2-14','{"options": ["Anterior corneal epithelium", "bowman’s membrane", "corneal stroma", "endothelium"], "correct": 2, "explanation": "The corneal stroma is the thickest corneal layer (about 90% of corneal thickness). Bulk of the cornea = stroma."}'),
  ('58c6df08-11','{"options": ["Iris", "choroid", "ciliary body", "ora serrate"], "correct": 3, "explanation": "The uveal coat is the iris, ciliary body, and choroid; the ora serrata is a retinal landmark, not uvea. Ora serrata is the exception."}'),
  ('85a5889b-1n','{"options": ["RPE (retinal pigment epithelium)", "Photoreceptor cell layer", "Inner plexiform layer", "ganglion cell layer"], "correct": 1, "explanation": "Phototransduction occurs in the photoreceptor cell layer (where light becomes an electrical signal). RPE supports it but the conversion is in the photoreceptors. Light-to-signal layer = photoreceptors."}'),
  ('965ad5cf-1z','{"options": ["Oculomotor", "Oscillatory", "Vestibulo-ocular", "Fluctuating"], "correct": 2, "explanation": "The VESTIBULO-OCULAR reflex (VOR) generates compensatory eye movements OPPOSITE to head motion to keep the image stable on the retina during head movement — driven by the semicircular canals. Fast, reflexive, short-latency. Distractors are non-specific. Cross-link: VOR gain is tested clinically (head impulse test)."}'),
  ('c2353bf6-3m','{"options": ["Fixation", "Absolute", "Sensitivity", "Threshold"], "correct": 2, "explanation": "SENSITIVITY (in perimetry) = the most subtle/faint stimulus detectable at a given point — the inverse of threshold expressed as the dimmest target seen (often in dB). Threshold is the stimulus intensity at the seeing/not-seeing boundary; sensitivity is how faint a target the point can detect. High sensitivity = sees very dim targets (low threshold)."}'),
  ('e59ee4e6-3y','{"options": ["Convergence reflex test", "Accommodation and convergence", "Accommodation pupillary response", "Positive vertical convergence"], "correct": 2, "explanation": "Measuring the pupil-size change as the eye focuses from distance to near tests the accommodative (near) pupillary response. Pupil change on near focus = accommodative pupillary response."}'),
  ('97265e43-3g','{"options": ["Visual Cortex", "Pupillary Pathway", "Visual Pathway", "Higher order of Visual system"], "correct": 0, "explanation": "The VISUAL CORTEX (V1, occipital) is where visual processing is signaled/integrated from the light stimulus relayed via the LGB and radiations — the cortical endpoint that builds perception. The pupillary pathway is a reflex arc; ''visual pathway/higher-order system'' are broader terms. V1 = primary integration site (Brodmann 17, calcarine)."}'),
  ('62ffa7c5-7u','{"options": ["Argyll Robertson pupil", "Hutchinson’s pupil", "Adies Pupil", "Horner’s syndrome pupil"], "correct": 2, "explanation": "A dilated pupil with no light reaction but a (slow) near response, with anisocoria greater in dim light, is a tonic (Adie''s) pupil. Argyll Robertson is small/constricted. Dilated, light-near dissociation = Adie''s pupil."}'),
  ('01eddb2d-21','{"options": ["Color vision problem", "Depth Perception", "Glaring", "Tear film"], "correct": 1, "explanation": "The PULFRICH phenomenon is a DEPTH-PERCEPTION illusion: a pendulum swinging in a plane appears to move in an ellipse because reduced luminance to one eye (e.g., optic neuritis, a filter) delays its signal, creating artificial stereo disparity. The reported symptom is altered depth perception. Mechanism: interocular latency difference → false binocular disparity."}'),
  ('5f0d5aca-21','{"options": ["Keyhole", "Oval", "Tadpole", "Scallop"], "correct": 3, "explanation": "SCALLOPED pupil margin (notched/wavy) from iris stromal atrophy is seen in AMYLOIDOSIS (familial amyloid polyneuropathy) infiltrating the iris. Tadpole = transient (benign episodic mydriasis); oval = e.g., acute angle closure; keyhole = iris coloboma/surgical. Pattern recognition: ''scalloped iris + amyloid.''"}'),
  ('6f780ebf-p','{"options": ["Minute of an arc", "Seconds of an arc", "Degrees of an arc", "Prism diopter"], "correct": 1, "explanation": "STEREOPSIS (stereoacuity) is measured in SECONDS of arc (arcsec) — finer than minutes; normal ≈ 40 arcsec or better (TNO, Titmus, Randot). Minutes of arc measure visual ACUITY (Snellen); prism diopters measure deviation. Smaller arcsec = better depth resolution. Mnemonic: stereo is SO fine it needs SECONDS."}'),
  ('eacf4666-1b','{"options": ["Blue", "Green", "Brown", "Parasympathetic"], "correct": 0, "explanation": "With only a small amount of melanin the iris appears blue (less pigment scatters short wavelengths). Little melanin = blue iris."}'),
  ('f606b155-2j','{"options": ["Glaucoma", "Narrow angle", "Angle-closure glaucoma", "Open Angle Glaucoma"], "correct": 3, "explanation": "Raised IOP from particles clogging an OPEN trabecular meshwork is open-angle glaucoma (secondary open-angle mechanism). Open angle, clogged meshwork = open-angle glaucoma."}'),
  ('4980b30e-22','{"options": ["Delayed development of gross and motor skills", "Decreased coordination, balance, and ball-playing skills", "Confusion of red and blue color", "Letter reversal errors when writing or reading"], "correct": 2, "explanation": "Confusion of red and blue color is a color-vision issue, NOT a visual-spatial skill problem, so it is the exception. Delayed motor skills, poor coordination, and letter reversals are visual-spatial. Color confusion is the odd one out."}'),
  ('7b26c4cc-4a','{"options": ["Positive fusional reserve should be at least 8 prism", "Negative fusional reserve should be at least 8 prism", "Positive fusional reserve should be at least 16 prism", "Negative Fusional reserve should be at least 16 prism"], "correct": 3, "explanation": "Sheard''s criterion: the compensating fusional reserve must be at least TWICE the phoria. For 8Δ ESOphoria the compensating reserve is the NEGATIVE (divergence) reserve, so it must be ≥ 16Δ. (Esophoria is relieved by divergence = negative fusional reserve; exophoria by positive/convergence reserve.) Formula: reserve ≥ 2×phoria."}'),
  ('0187da51-30','{"options": ["Decompensated esophoria.", "Compensated esophoria.", "Decompensated exophoria.", "Compensated exophoria ."], "correct": 3, "explanation": "On alternate cover, a SLOW recovery (the eye drifts back lazily to fixation) suggests the deviation is poorly compensated, while the direction (inward recovery of the just-exposed eye = the eye was out = exo) names it. The keyed answer reads it as a compensated EXOphoria recovering inward; the recovery quality (prompt vs slow) grades compensation. Cover-test logic: refixation IN = exo; recovery speed = compensation."}'),
  ('6e401077-1u','{"options": ["Power drum..", "Protractor..", "Reticle..", "Prism axis indicator.."], "correct": 2, "explanation": "The RETICLE is the cross-line graticule in the lensmeter eyepiece that, with the prism-compensating scale/rings, reads induced PRISM (and centration). The power drum changes sphere/cyl; the protractor reads axis. Reticle = the measuring graticule for prism."}'),
  ('cfbda4ab-2n','{"options": ["100%", "75%", "50%", "0%"], "correct": 3, "explanation": "A cylinder has ZERO power along its own axis and full power 90 degrees away. Formally the power at an angle t from the axis is F sin^2(t), so on the axis t = 0 and F sin^2(0) = 0. The Rx is +1.00S = +1.00C x 090, so 090 IS the cyl axis. Asking how much cyl acts at 090 is asking how much acts on its own axis: none of it. Answer: 0%. The full +1.00 acts at 180, and at 45 you would get sin^2(45) = 0.5, so half. The old key read 100%, which is what you get by treating ''axis 090'' as the power meridian. The ''x 090'' notation always names the axis, never the meridian where the power lands."}'),
  ('4944e096-2u','{"options": ["Isopter", "Hill of Vision", "Visual Field", "Scotoma"], "correct": 0, "explanation": "An isopter is the boundary between the seeing (visible) and non-seeing (non-visible) areas for a given stimulus on the visual field. Boundary of visibility = isopter."}'),
  ('834a82fc-1n','{"options": ["Optic neuropathy.", "Retinal Detachment.", "Macular Hole.", "Band Keratopathy."], "correct": 3, "explanation": "NOT a common cause = answer. Optic neuropathy, retinal detachment, and macular hole all produce field defects (neural/retinal). BAND KERATOPATHY is a CORNEAL calcium deposit causing media opacity/blur, not a true neural field defect. Distinguish corneal media problems from retinal/neural field loss."}'),
  ('e8e1b85e-2o','{"options": ["Threshold", "Suprathresold", "Mesopic", "Light-Dark Adaptation"], "correct": 0, "explanation": "Threshold is the ability to detect a stimulus at a given location under specified conditions (the just-detectable level). Detect at a point = threshold."}'),
  ('5959325d-1e','{"options": ["WTR (With-the-Rule),,", "ATR (Against-the-Rule),,", "Oblique,,", "Irregular,,"], "correct": 1, "explanation": "K''s show the steeper power in the HORIZONTAL meridian (e.g., 46.50 @176 vs 45.75 @086 — more power near 180) and the correcting minus-cyl axis is near 090 → AGAINST-THE-RULE (ATR) astigmatism. WTR has the steep meridian vertical; ATR has it horizontal. Rule: minus-cyl axis near 90 (or steep horizontal) = ATR."}'),
  ('271a2df8-1i','{"options": ["High value of IOP", "Shallow depth of anterior chamber", "Narrow angle glaucoma", "Anisometropia"], "correct": 3, "explanation": "Anisometropia is the exception: it is an INDICATION for cycloplegic refraction, not a contraindication. High IOP, shallow anterior chamber, and narrow-angle glaucoma are the true contraindications. Anisometropia = reason to do it, not avoid it."}'),
  ('ececb5b5-2y','{"options": ["Depth of focus’", "Depth of field’", "Depth perception’", "Depth of anterior chamber’"], "correct": 0, "explanation": "DEPTH OF FOCUS = the dioptric range over which the IMAGE can sit in front of/behind the retina and still look sharp (image-space tolerance). Depth of FIELD is the corresponding object-space range. Depth perception is stereopsis; AC depth is anatomy. Focus = image side, field = object side."}'),
  ('e8f28188-1l','{"options": ["Aphakic;", "Early presbyope;", "Reading glasses wearer;", "Satisfied trifocals wearer;"], "correct": 3, "explanation": "The best PAL candidate is a SATISFIED TRIFOCAL wearer — already adapted to multiple zones and motivated, they transition smoothly to the seamless progressive. Aphakes (huge add/field issues), early presbyopes (low add, may not need it), and pure reading-glass wearers are weaker candidates. Prior multifocal success predicts PAL success."}'),
  ('4e9e83f3-2a','{"options": ["‘;a. Presbyopia", "‘;b. Aphakic", "‘;c. Macular edema", "‘;d. Anisometropia"], "correct": 3, "explanation": "EXCEPT (not a reason to avoid cycloplegic retinoscopy). You''d avoid it where dilation is risky/unneeded; among these, ANISOMETROPIA is actually an INDICATION (you want an accurate cycloplegic refraction), so it''s the exception. (Pairs with Q14 — anisometropia favors, not forbids, cycloplegia.)"}'),
  ('68f29432-66','{"options": ["2-3 hours.", "8-24hours.", "More than 30hours.", "5hours."], "correct": 1, "explanation": "Cyclopentolate 1% gives cycloplegia for refraction with accommodation typically returning in ~8-24 hours (full recovery up to ~24 h). Tropicamide is shorter (~6 h); atropine far longer (days). Cyclopentolate recovery ≈ within a day — the practical choice for pediatric cycloplegic refraction."}'),
  ('4e3be380-2e','{"options": ["Krimsky’s method", "Hirschberg method", "Von Graefe method", "Prism bar cover test"], "correct": 1, "explanation": "The Hirschberg method crudely estimates the deviation from the position of the corneal light reflex. Light-reflex estimate = Hirschberg."}'),
  ('03bc0733-1j','{"options": ["Same amount of prism towards the base-out direction", "Same amount of prism towards the base-in direction", "One prism for measuring and the other for dissociation", "One prism ready to turn down and the other ready to turn in"], "correct": 2, "explanation": "Von Graefe technique uses two prisms: one (measuring) prism plus a dissociating prism to split the images. One measures, one dissociates = Von Graefe."}'),
  ('91e0fc81-5h','{"options": ["esophoria", "exophoria", "right esotropia", "left exotropia"], "correct": 0, "explanation": "On alternate cover, an eye that moves inward when covered and returns on uncovering is esophoric (it turns in under cover, then recovers). Inward move under cover, recovers = esophoria."}'),
  ('3be22f5b-55','{"options": ["left esotropia", "right exotropia", "left exotropia", "right esotropia"], "correct": 0, "explanation": "When covering OD makes OS move out to fixate, the left eye was turned in (esotropic). With OD steady when OS is covered, the tropia is a left esotropia. Fellow eye moves out to fixate = that eye is esotropic."}'),
  ('b5990c05-4d','{"options": ["-6:1", "2:1", "-2:1", "6:1"], "correct": 3, "explanation": "Gradient ACA = change in phoria / change in lens. Going from 2 eso to 4 exo is a 6 prism shift for the +1.00 D add, giving a 6:1 gradient ACA. Phoria shift over lens change = ACA."}'),
  ('e71d819d-22','{"options": ["better magnification", "provides real image", "less time for pre-focusing"], "correct": 1, "explanation": "Direct ophthalmoscopy gives a VIRTUAL erect image, so ''provides a real image'' is the false statement (not an advantage). Its true advantages are high magnification and quick use. Direct scope = virtual image."}'),
  ('cddac66b-1k','{"options": ["headache", "burning sensation", "foreign body sensation", "tearing"], "correct": 3, "explanation": "Tearing is the non-painful exception; headache, burning, and foreign-body sensation are the painful (non-visual) symptoms. Tearing = a sign, not a painful symptom."}'),
  ('dc4bcecf-17','{"options": ["balance the visual acuity of the two eyes", "balance the state of accommodation of the two eyes", "determine the type of heterophoria"], "correct": 1, "explanation": "Binocular equalization balances the state of accommodation of the two eyes (equal fogging/relaxation), not their acuity. Equalize accommodation between eyes."}'),
  ('0278a114-13','{"options": ["6/15", "6/12", "6/9"], "correct": 1, "explanation": "20/40 equals 6/12 in the metric (6 m) system (both reduce to half acuity). 20/40 = 6/12."}'),
  ('40764458-2k','{"options": ["increase (-)/decrease (+) sphere", "increase (+)/decrease (-) sphere", "decrease (+) sphere/decrease (-)"], "correct": 0, "explanation": "On duochrome, letters clearer on RED mean the focus is in front of where it should be, so add minus (increase minus / decrease plus). Red Add Minus. Red clearer = more minus."}'),
  ('af304cc1-37','{"options": ["Pinhole disc", "Schiener’s disc", "Stenopaic slit"], "correct": 1, "explanation": "Scheiner''s disc uses a double aperture so the patient judges refractive error by the parallax (relative motion) of the two images. Parallax-based estimate = Scheiner''s disc."}'),
  ('9c5a8438-3o','{"options": ["Pinhole disc", "Schiener’s disc", "Stenopaic slit"], "correct": 2, "explanation": "A stenopaic slit is rotated until the patient reports clearest vision, locating the astigmatic axis/power. Rotate-to-clearest slit = stenopaic slit."}'),
  ('5365260a-20','{"options": ["sinus", "tension", "migraine", "cluster"], "correct": 1, "explanation": "A bilateral, stress-related headache is a tension headache. Migraine is usually unilateral/throbbing; cluster is severe and periorbital. Both sides, stress = tension headache."}'),
  ('197b9236-2n','{"options": ["Detection", "Identification", "Recognition"], "correct": 2, "explanation": "Recognition acuity is the level where the patient must name/identify the target (as on a Snellen chart). Detection is just seeing it is there. Name the target = recognition acuity."}'),
  ('d8fd8d71-2x','{"options": ["Neutral", "Against", "With"], "correct": 1, "explanation": "A concave mirror reverses retinoscopic motion, so a hyperope (who shows ''with'' motion in plane-mirror scoping) shows AGAINST motion with a concave mirror. Concave mirror flips the motion."}'),
  ('2215f050-1y','{"options": ["accommodation", "convergence", "inhibition", "stimulation"], "correct": 1, "explanation": "Phoria measurement tests the convergence (vergence) portion of the visual pattern. Phoria = convergence side."}'),
  ('cf302d71-12','{"options": ["normal", "flat", "steep"], "correct": 2, "explanation": "A K reading of 47.00 D is a STEEP cornea (more power than the roughly 42 to 44 D normal range). High K = steep cornea."}'),
  ('311435f1-1f','{"options": ["normal", "flat", "steep"], "correct": 1, "explanation": "A K reading of 42.00 D is a FLAT cornea (below the normal range). Low K = flat cornea."}'),
  ('b0564285-2k','{"options": ["yellow", "Blue", "red-free", "no filter/white"], "correct": 2, "explanation": "A red-free (green) filter gives the best contrast on ophthalmoscopy (it highlights vessels and nerve-fiber layer). Better contrast = red-free filter."}'),
  ('d59b5db6-1z','{"options": ["14.00D", "20.00D", "30.00D", "d 40.00D"], "correct": 1, "explanation": "The 20.00 D condensing lens is the common choice for binocular indirect ophthalmoscopy. Standard BIO lens = 20 D."}'),
  ('1cb75c32-21','{"options": ["13.00D", "13.75D", "15.00D", "17.75D"], "correct": 0, "explanation": "Hofstetter average amplitude = 18.5 - 0.30 x age = 18.5 - 0.30(18) = about 13.1 D, so about 13.00 D for an 18-year-old. Average amplitude = 18.5 - 0.30(age)."}'),
  ('2ae1c843-2r','{"options": ["5o", "10o", "15o", "30o"], "correct": 2, "explanation": "Hirschberg: roughly 15 prism diopters per millimeter (about 7 degrees per mm). A 30-prism correction corresponds to about a 15-degree deviation. 30 prism = about 15 degrees."}'),
  ('5015ce4f-1v','{"options": ["green", "red", "blue", "yellow"], "correct": 1, "explanation": "Protanopia is the red-blind defect (loss of long-wavelength/red cones). Prot = red. Protanopia = difficulty with red."}'),
  ('34be5b13-21','{"options": ["Tritanomaly", "Deuteranomaly", "Protanomaly"], "correct": 0, "explanation": "Reduced sensitivity to blue is tritanomaly (trit = blue, weak form). Trit = blue. Reduced blue = tritanomaly."}'),
  ('fe9969c5-46','{"options": ["Amsler test", "Swinging flashlight test", "Projection test", "Perception test"], "correct": 1, "explanation": "The swinging flashlight test is the objective test of pupil function that detects unilateral optic nerve disease (a relative afferent defect). Detect one-sided optic nerve disease = swinging flashlight."}'),
  ('a532bdc3-2u','{"options": ["-1.00C X 45", "-1.00C X 135", "-0.50C X 45", "-0.50C X 135"], "correct": 1, "explanation": "Corneal astigmatism is the difference between the meridians with the minus-cyl axis along the flatter meridian: 45.50 @ 45 and 44.50 @ 135 give -1.00 C x 135. Minus cyl axis = flatter meridian (135)."}'),
  ('f114e42d-28','{"options": ["65mm", "66mm", "67mm"], "correct": 1, "explanation": "Distance PD is larger than near PD by a few millimeters; a 63 mm near PD corresponds to about 66 mm distance PD. Distance PD > near PD (by about 3 mm)."}'),
  ('6b935f86-41','{"options": ["0.00=-0.50 X 180", "+0.50=-0.50 X 180", "0.00= -0.50 X 90", "-0.50 = -0.50 X 90"], "correct": 0, "explanation": "Net retinoscopy subtracts the working-distance dioptric value: a 67 cm working distance is 1.50 D, so +1.50 - 1.50 = 0.00 sphere, cylinder unchanged: 0.00 = -0.50 x 180. Net = gross minus 1/working distance."}'),
  ('0035a711-2o','{"options": ["Preliminary test", "Case history", "Visual acuity test", "External eye exam"], "correct": 1, "explanation": "The first procedure when a patient arrives is taking the case history (chief complaint, ocular/medical/family history). History comes first."}'),
  ('de6ff972-a3','{"options": ["+1.25 D", "+1.75D", "+2.00 D", "+2.25D"], "correct": 0, "explanation": "Keeping the total near power constant: old near = +1.00 + 1.75 = +2.75; with the new +1.50 distance, the add becomes +2.75 - 1.50 = +1.25 D. More distance plus means a smaller add."}'),
  ('0d7c89cd-4t','{"options": ["15cm", "20cm", "25cm", "30cm"], "correct": 2, "explanation": "NPA at 19 cm with a +1.25 add means total near power = 100/19 = 5.26 D, of which 1.25 is the add, leaving about 4.0 D of accommodation; without the add NPA = 100/4.0 = about 25 cm. Remove the add, the near point recedes."}'),
  ('8d0f400f-4f','{"options": ["lags behind the accommodative stimulus by 1.50 D", "lags behind the accommodative stimulus by 3.00 D", "leads the accommodative stimulus by 0.50 D", "leads the accommodative stimulus by 1.50 D"], "correct": 0, "explanation": "An emmetrope fixating at 33 cm faces a 3.00 D stimulus, but retinoscopic neutrality at 67 cm (1.50 D) shows the eye is only accommodating 1.50 D, so the response LAGS the stimulus by 1.50 D. Lag = stimulus minus response (3.00 - 1.50)."}'),
  ('ac62ebd6-57','{"options": ["Bacterial conjunctivitis", "Allergic conjunctivitis", "Viral conjunctivitis"], "correct": 1, "explanation": "Clear (watery) discharge with redness and a long allergy history points to allergic conjunctivitis. Itchy, watery, atopic = allergic conjunctivitis."}'),
  ('cf06181b-7y','{"options": ["cataract", "nuclear cataract", "posterior cataract"], "correct": 1, "explanation": "Gradual central vision loss with yellowing of the central lens is a nuclear cataract (nuclear sclerosis). Central yellow lens = nuclear cataract."}'),
  ('5c0a1ed5-1w','{"options": ["prism base-out", "+0.25S", "prism base-in", "none"], "correct": 0, "explanation": "True adduction at distance is measured with base-OUT prism (it stimulates convergence). Adduction testing = base-out prism."}'),
  ('20997120-33','{"options": ["Confrontation test", "Amsler grid test", "Color vision test", "Swinging flashlight test"], "correct": 1, "explanation": "The Amsler grid is the simple test that detects early macular changes (metamorphopsia/scotoma), useful in hereditary macular concerns. Early macular check = Amsler grid."}'),
  ('645e0947-2p','{"options": ["Myopia/", "Hyperopia/", "Presbyopia/", "Astigmatism/"], "correct": 2, "explanation": "A 45-year-old with new NEAR reading difficulty = PRESBYOPIA (age-related loss of accommodative amplitude, onset ~40-45). Myopia blurs distance; hyperopia/astigmatism give other patterns. Age ~40-45 + near blur = presbyopia."}'),
  ('95be4ef0-42','{"options": ["Prescribe glasses for the worse-seeing eye", "Perform a detailed refraction test", "Refer the patient to a specialist immediately", "Ask the patient if they have had recent trauma"], "correct": 1, "explanation": "A large interocular vision difference → first PERFORM a DETAILED REFRACTION to characterize the anisometropia before prescribing or referring. Don''t prescribe blindly, refer reflexively, or assume trauma. Work up the refraction first."}'),
  ('8e9ba946-37','{"options": ["Glaucoma", "Retinal Detachment", "Cataract", "Dry Eye Syndrome"], "correct": 1, "explanation": "Sudden PAINLESS monocular vision loss with this framing points to RETINAL DETACHMENT (curtain/shadow) among the options (also consider vascular occlusion). Glaucoma/cataract are gradual; dry eye doesn''t cause sudden loss. Sudden mono loss → think retinal/ vascular emergency."}'),
  ('9927d944-2q','{"options": ["Intraocular pressure", "Visual acuity and retinal changes", "Lens opacity", "Corneal curvature"], "correct": 1, "explanation": "A DIABETIC with FLUCTUATING vision needs assessment of VISUAL ACUITY and RETINAL changes (diabetic retinopathy/macular edema; glucose-driven lens index shifts cause the fluctuation). Check the retina and acuity. Diabetes + fluctuating vision = retinopathy/glycemic refractive shift."}'),
  ('3f8dfec8-1h','{"options": ["Gradual vision loss", "Severe headache and nausea", "Painless vision changes", "Red eye without pain"], "correct": 1, "explanation": "Acute angle-closure glaucoma presents with severe headache and nausea (plus a painful red eye, halos, and a mid-dilated pupil). AACG = severe pain, headache, nausea."}'),
  ('1f306d89-30','{"options": ["Astigmatism=", "Cataract=", "Retinal Detachment=", "Conjunctivitis="], "correct": 1, "explanation": "A 60-year-old with night GLARE and HALOS most likely has CATARACT (lens opacity scatters light). Astigmatism gives steady blur; detachment gives field loss; conjunctivitis gives redness/discharge. Age + glare/halos at night = cataract (cf. acute glaucoma''s rainbow halos, Q45)."}'),
  ('a7eb1b30-2j','{"options": ["Perform a visual acuity test", "Prescribe antibiotic eye drops", "Conduct a thorough history and eye examination", "Refer to an ophthalmologist immediately"], "correct": 2, "explanation": "A red eye with discharge: FIRST conduct a thorough HISTORY and EYE EXAMINATION (characterize cause) before prescribing antibiotics, treating, or referring. Diagnose before treating — history/exam guide management. Don''t shotgun antibiotics."}'),
  ('e11cfa01-28','{"options": ["Allergic conjunctivitis", "Mild dry eye", "Central retinal artery occlusion", "Refractive error"], "correct": 2, "explanation": "CENTRAL RETINAL ARTERY OCCLUSION is an ophthalmic EMERGENCY (sudden painless severe loss; minutes-to-hours window) → URGENT referral. Allergic conjunctivitis, mild dry eye, and refractive error are routine. CRAO = emergent referral."}'),
  ('f3136917-1r','{"options": ["Snellen Chart", "Rosenbaum Pocket Vision Screener", "Ishihara Plates", "Amsler Grid"], "correct": 0, "explanation": "The ROSENBAUM pocket card is the handheld NEAR vision screener (reduced Snellen/Jaeger at ~14 in). Snellen is distance; Ishihara is color; Amsler is macular field. Near acuity screen = Rosenbaum (or Jaeger)."}'),
  ('559b43eb-32','{"options": ["Perform a visual field test", "Conduct a complete eye examination and refer for imaging if necessary", "Prescribe pain medication and follow up in a week", "Provide lubricating eye drops and reassess later"], "correct": 1, "explanation": "Sudden monocular loss AFTER HEAD TRAUMA → conduct a COMPLETE eye exam and REFER for IMAGING (rule out traumatic optic neuropathy, retinal/ globe injury, intracranial cause). Don''t just do a field, give pain meds, or lubricate. Trauma + sudden loss = exam + neuroimaging."}'),
  ('397ae488-1r','{"options": ["Slit Lamp.", "Pachymeter.", "Retinoscope.", "Fundus Camera."], "correct": 1, "explanation": "A PACHYMETER measures corneal THICKNESS (ultrasound or optical) — essential before refractive surgery and for IOP interpretation/keratoconus. Slit lamp views; retinoscope refracts; fundus camera images retina. Corneal thickness = pachymetry."}'),
  ('9333e6be-2n','{"options": ["Immediate referral for surgery", "Removal of the foreign body and irrigation of the eye", "Application of an antibiotic ointment", "Providing pain relief and follow-up"], "correct": 1, "explanation": "A superficial corneal/conjunctival FOREIGN BODY sensation → REMOVE the foreign body and IRRIGATE the eye (first-line). Surgery/ointment/just-pain-relief are not the initial step. Remove and irrigate first, then treat/follow."}'),
  ('c0c0766a-4o','{"options": ["Prescribe corrective lenses and monitor for adaptation", "Refer for orthoptic therapy", "Suggest vision therapy exercises at home", "Recommend surgical intervention"], "correct": 0, "explanation": "A 25-year-old anisometrope with depth/strain symptoms → PRESCRIBE corrective lenses and MONITOR adaptation as the effective initial step (correct the error first; many adapt). Orthoptics/VT/surgery aren''t first-line. Correct and monitor first."}'),
  ('0fe88ea0-4b','{"options": ["Achieve equal refractive error in both eyes", "Improve overall visual acuity in the better-seeing eye", "Manage any associated strabismus", "Prevent the development of amblyopia"], "correct": 3, "explanation": "In a 6-year-old, the PRIMARY treatment goal for anisometropia is to PREVENT AMBLYOPIA (the blurred eye risks deprivation amblyopia during the critical period). Equalizing refraction or managing strabismus are secondary to amblyopia prevention. Pediatric anisometropia = prevent amblyopia first."}'),
  ('4c039208-4a','{"options": ["Incorrect lens prescription", "Incorrect fitting of the glasses", "Binocular vision issues", "All of the above"], "correct": 3, "explanation": "Adapted anisometrope still with headaches → likely ALL OF THE ABOVE: residual Rx error, fitting/centration (induced prism), and binocular-vision issues can each cause persistent asthenopia. Check every contributor. Multifactorial asthenopia in corrected anisometropia."}'),
  ('b88e4077-47','{"options": ["Immediate referral for surgery", "Glasses correction and patching therapy for the amblyopic eye", "Vision therapy alone", "Continued observation without treatment"], "correct": 1, "explanation": "A 15-year-old anisometrope WITH amblyopia → GLASSES correction PLUS PATCHING of the amblyopic eye (optical correction + occlusion). Surgery/observation/VT-alone don''t treat the amblyopia. Anisometropic amblyopia = correct + patch (even into the teens, with reduced efficacy)."}'),
  ('046f597c-47','{"options": ["Referral for a binocular vision assessment", "Increasing the lens power in the dominant eye", "Adjusting the glasses prescription to make the eyes equal", "Recommending an increase in the wearing time of glasses"], "correct": 0, "explanation": "Improved vision but lingering binocular-task trouble → REFER for a BINOCULAR VISION ASSESSMENT (the residual problem is sensory/motor fusion, not lens power). Don''t just raise power or equalize. Persistent binocular symptoms = formal BV work-up."}'),
  ('da997a8c-3o','{"options": ["Increase the prescription strength for the affected eye", "Evaluate for any associated accommodative or binocular vision problems Evaluate for any associated", "Recommend alternative lens options", "Suggest over-the-counter pain relief medication accommodative or binocular vision problems"], "correct": 1, "explanation": "Anisometropia with chronic headaches → EVALUATE for associated ACCOMMODATIVE or BINOCULAR VISION problems in the management plan (the headache source is often the binocular/accommodative strain, not the refraction alone). Look beyond the Rx to the BV/accommodative system."}'),
  ('29684613-4r','{"options": ["Incorrect lens alignment", "Persistent anisometropia despite correction", "Undiagnosed binocular vision problems", "All of the above"], "correct": 3, "explanation": "Corrected anisometrope without expected improvement → possible reasons are ALL OF THE ABOVE: lens misalignment/centration, persistent uncorrected anisometropia, and undiagnosed binocular vision problems. Systematically check each. Multiple coexisting causes."}'),
  ('0363dba2-4t','{"options": ["The degree of anisometropia and its impact on visual function", "The patient’s preference for glasses versus surgery", "The presence of any binocular vision or accommodative issues", "Both A and C"], "correct": 3, "explanation": "Evaluating an anisometrope for refractive surgery: consider BOTH the DEGREE of anisometropia/its visual impact AND any BINOCULAR/ACCOMMODATIVE issues (A and C) — surgery to equalize must account for fusion potential. Patient preference alone isn''t the clinical criterion. Assess anisometropia magnitude + binocular function."}'),
  ('87116449-3j','{"options": ["Increase the lens prescription strength", "Explain the importance of correction and involve the child in choosing their glasses", "Recommend frequent lens changes", "Decrease the wearing time gradually"], "correct": 1, "explanation": "For a non-compliant CHILD with anisometropia, improve adherence by EXPLAINING the importance and INVOLVING the child in choosing frames (engagement/ownership) — not by changing power, frequent swaps, or cutting wear time. Compliance = education + child buy-in."}'),
  ('68d7c0cb-49','{"options": ["Use glasses with a smaller prescription difference", "Prescribe contact lenses to better equalize vision", "Recommend vision therapy to address adaptation issues", "Increase the prescription in the weaker eye"], "correct": 1, "explanation": "Trouble adapting to a LARGE spectacle Rx difference (aniseikonia/anisophoria) → prescribe CONTACT LENSES to better equalize the retinal images and reduce induced differences. Reducing the spectacle difference under-corrects; VT/extra power don''t fix the optics. Large anisometropia adaptation problem = contacts."}'),
  ('cfff695f-1c','{"options": ["The steeper the curvature, the greater the refractive power", "The shorter the radius of curvature, the flatter the surface", "The flatter the curvature, the lesser the bending of light", "None of the above"], "correct": 1, "explanation": "NOT TRUE = answer. A SHORTER radius of curvature makes a surface STEEPER (more curved, more power), NOT flatter — so option B is false. True: steeper curvature = more power; flatter = less bending. Relationship: power ∝ 1/radius (shorter radius = steeper = stronger)."}'),
  ('0d7270f0-24','{"options": ["‘Blur", "‘Near target", "‘Light", "‘None of the above"], "correct": 0, "explanation": "BLUR is the PRIMARY stimulus to accommodation (retinal defocus drives the accommodative response); proximal (near target awareness) and disparity (convergence-driven) are secondary contributors. Light is not the trigger. Accommodation''s main cue = retinal blur."}'),
  ('e2039176-4e','{"options": ["..Emmetropia", "..Myopia", "..Hyperopia", "..Astigmatism"], "correct": 2, "explanation": "If, with accommodation relaxed, light from a finite object focuses BEHIND the retina, the eye is under-powered for that vergence = HYPEROPIA (needs plus to pull the focus forward onto the retina). Focus behind retina (relaxed) = hyperopic. Cross-link: myopia focuses in front."}'),
  ('fa6c1a89-1x','{"options": ["‘Shallow depth of anterior chamber", "‘Flatter corneal curvature", "‘Shorter radius of curvature", "‘old age"], "correct": 2, "explanation": "EXCEPT (won''t cause hyperopia). Hyperopia comes from LESS converging power / shorter eye: flatter cornea, shallow AC, ageing (lens changes), short axial length. A SHORTER radius of curvature makes the cornea STEEPER → MORE power → MYOPIA, not hyperopia — the exception. Shorter radius = steeper = myopic."}'),
  ('ae9e9d27-2d','{"options": ["Amplitude of accommodation’’;", "Range of accommodation;;", "Lead of accommodation’;;’", "Lag of accommodation’;’"], "correct": 2, "explanation": "OVER-accommodating for a given stimulus (accommodative response exceeds demand, focus in front) = LEAD of accommodation. Under-accommodating = LAG. Amplitude/range are extents, not the over/under posture. Over = lead, under = lag."}'),
  ('5dbdc3ba-25','{"options": ["Complete blindness of the right eye;’", "Normal direct and consensual light reflex if light is presented on the left eye;", "Sluggish pupillary response if light is presented on the left eye;", "No direct and consensual light reflex if light is presented on the affected eye;"], "correct": 2, "explanation": "NOT TRUE = answer. With a RIGHT optic nerve lesion, light in the LEFT (good) eye gives NORMAL direct and consensual responses (intact afferent + both efferents). A ''SLUGGISH'' response to left-eye light (option C) is FALSE — the left afferent path is intact, so the response is normal, not sluggish. Afferent right-nerve lesion doesn''t impair left-eye-driven responses."}'),
  ('fb4096f8-19','{"options": ["flatter refractive surface result to lower refractive power;", "shorter radius of curvature result to a flatter refracting sur;face", "higher refractive power makes light more convergent;", "shallow depth of anterior chamber results to less convergence of light;;"], "correct": 1, "explanation": "NOT TRUE = answer. A SHORTER radius of curvature → STEEPER (not flatter) refracting surface, so option B is false (same trap as Q104). True: flatter surface = lower power; higher power = more convergent; shallow AC = less convergence. Power ∝ 1/radius."}'),
  ('a237a259-2s','{"options": ["Simple myopic astigmatism;’;;", "Compound myopic astigmatism;’", "Simple hyperopic astigmatism’", "Compound myopic astigmatism;’;"], "correct": 1, "explanation": "Both foci IN FRONT of the retina = COMPOUND MYOPIC astigmatism — wait: the classification with BOTH focal lines in front is COMPOUND MYOPIC astigmatism. [The keyed ''simple myopic'' has ONE line on the retina; if BOTH are in front it is compound myopic. Verify the intended stem — ''both foci in front'' = compound myopic astigmatism.] Simple = one line on retina; compound myopic = both in front; mixed = straddling."}'),
  ('9b29ab29-2v','{"options": ["With-the-rule astigmatism,", "Against-the-rule astigmatis,m", "Oblique astigmatism,", "Physiologic astigmatism,"], "correct": 0, "explanation": "WITH-THE-RULE astigmatism has its GREATEST refracting power at/near the VERTICAL meridian (steep cornea vertical), corrected with minus-cyl axis ~180. ATR is steepest horizontally. Mnemonic: WTR = vertical steep (''standing rule''). Common in youth."}'),
  ('a0695704-19','{"options": ["-0.50 cyl x 90", "-0.50 WTR", "-0.50 cyl X 180", "Both b and c"], "correct": 3, "explanation": "Physiologic astigmatism is about 0.50 D WITH-THE-RULE, because the average young cornea is slightly steeper vertically. Correcting a steeper vertical meridian in minus-cyl form puts the axis at 180. So ''-0.50 WTR'' and ''-0.50 cyl x 180'' are two names for the same thing, and both b and c are correct. Answer: Both b and c. Option a, -0.50 cyl x 90, is against-the-rule, the opposite orientation."}'),
  ('56e34c90-45','{"options": ["Emmetropia;’/", "Myopia;’;/", "Hyperopia;’;/;", "Astigmatism’/"], "correct": 1, "explanation": "If, with accommodation RELAXED, the posterior principal focus from a NEAR object lands exactly on the retina, the eye is MYOPIC — only a myope''s far point is at a finite near distance, so near rays focus on the retina without accommodation. Myope''s far point is near → near object clear when relaxed."}'),
  ('d1293263-16','{"options": ["Longer eyeball, greater refractive power;", "Shorter eyeball, normal refractive power;", "Normal axial length, greater refractive power;", "Shorter radius of curvature;"], "correct": 3, "explanation": "EXCEPT (won''t cause myopia). Myopia = too much power for the eye''s length: longer eyeball, or normal length with greater power, or steeper cornea (shorter radius of curvature). A SHORTER RADIUS of curvature actually INCREASES power → it DOES cause myopia, so it''s NOT the exception... [the keyed ''shorter radius'' as the exception conflicts — shorter radius is myopic; re-read the stem options]. Concept: longer axial length and/or steeper cornea = myopia."}'),
  ('9528391d-21','{"options": ["Cornea;’;", "Sclera’", "Ciliary body;’;", "Choroid’"], "correct": 1, "explanation": "The CHOROID — wait: the structure covering ~5/6 of the eyeball''s interior is the CHOROID/UVEAL coat? The SCLERA forms the outer 5/6 externally; internally the RETINA/uvea line it. [Keyed: ciliary body — verify; classically the SCLERA is the outer 5/6 of the fibrous coat and the CORNEA the anterior 1/6.] Anchor: sclera = posterior 5/6 of the outer coat, cornea = anterior 1/6."}'),
  ('4a74bbd5-1k','{"options": ["Miosis’;", "Contraction of ciliary muscles.", "Convergence of eye ball.", "None of the above."], "correct": 3, "explanation": "EXCEPT (does occur). During the accommodative near triad: ciliary muscle CONTRACTS, the eyes CONVERGE, and the pupil MIOSES (constricts) — all three occur, so ''none of the above'' is the EXCEPT answer (nothing in the list is excluded). Near triad: accommodation + convergence + miosis."}'),
  ('65d44d0e-2h','{"options": ["With-the-rule, Mixed Astigmatism///", "With-the-rule, Simple Myopic Astigmatism/", "Against-the-rule, Mixed Astigmatism//", "Against-the-rule, Simple Myopic Astigmatism//"], "correct": 3, "explanation": "−1.00 sph = +1.00 cyl × 180. Powers: 180 meridian = −1.00 (myopic), 90 meridian = −1.00 + 1.00 = 0.00 (on retina). One focal line ON the retina, one IN FRONT = SIMPLE MYOPIC astigmatism; transposed to plano −1.00 × 090 → minus-cyl axis 90 = AGAINST-THE-RULE. So by the math this is ATR SIMPLE MYOPIC (option D), whereas the source keys WTR mixed — flag/verify. Method: find both meridional powers, then classify by where the focal lines sit."}'),
  ('4831a145-1n','{"options": ["WTR astigmatism has the greatest power along the horizontal meridian;", "symmetric astigmatism exists when the axis meridians of both eyes is equal to ;180", "heteronymous astigmatism occurs if both eyes are asymmetric, having one eye WTR and the other ATR;", "none of the above;"], "correct": 1, "explanation": "NOT TRUE = answer. True statements: WTR has greatest power along the VERTICAL (option A says horizontal — already suspect), symmetric astigmatism = mirror axes, heteronymous = one eye WTR + other ATR. The keyed false option is the one mis-stating symmetry/axis equality. [Identify the statement that contradicts the WTR/symmetry definitions.] Use the definitions to find the false claim."}'),
  ('8b6035f6-v','{"options": ["simple myopic astigmatism’’’’", "simple hyperopic astigmatism’’", "compound myopic astigmatism’’", "compound hyperopic astigmatism’’’", "mixed astigmatism"], "correct": 2, "explanation": "−1.75 sph = +1.50 cyl × 180 → meridian 180 = −1.75 (myopic), meridian 90 = −1.75 + 1.50 = −0.25 (myopic). BOTH meridians myopic (both foci in front) = COMPOUND MYOPIC astigmatism. Method: compute both powers; both minus = compound myopic."}'),
  ('5f5e0148-v','{"options": ["simple myopic astigmatism’", "simple hyperopic astigmatism’", "compound myopic astigmatism’", "compound hyperopic astigmatism’", "mixed astigmatism’’"], "correct": 3, "explanation": "+1.50 sph = −0.50 cyl × 180 → meridian 180 = +1.50 (hyperopic), meridian 90 = +1.50 − 0.50 = +1.00 (hyperopic). BOTH meridians hyperopic = COMPOUND HYPEROPIC astigmatism. Both plus = compound hyperopic."}'),
  ('baeff770-44','{"options": ["Vitreous Humor.", "Tear Film.", "Aqueous Humor.", "Cornea."], "correct": 2, "explanation": "AQUEOUS HUMOR nourishes the avascular CORNEA and LENS (the two key refractive elements) while contributing only minor refractive power itself. Vitreous supports the globe; tear film smooths the cornea; cornea is a major refractor. Aqueous = nutrition to cornea/lens, minor refraction."}'),
  ('18ba42de-2o','{"options": ["10.00D", "12.50D", "17.00D", "20.00D"], "correct": 1, "explanation": "Hofstetter average amplitude = 18.5 - 0.30 x age = 18.5 - 0.30(20) = 12.5 D for a 20-year-old. Average amplitude formula gives 12.50 D."}'),
  ('8b913363-3j','{"options": ["Hyperopia", "Myopia", "Emmetropia", "Any ammetropia"], "correct": 0, "explanation": "If refractive power decreases (here from a shallower anterior chamber lowering effective power), the eye becomes hyperopic. Less power = hyperopia."}'),
  ('92837123-3i','{"options": ["Keratoconus", "Microcoria", "Aphakia", "Microphthalmos"], "correct": 3, "explanation": "A rare developmental disorder with a pathologically short axial length is microphthalmos (a small eye). Short, maldeveloped eye = microphthalmos."}'),
  ('3f24f8bb-4e','{"options": ["Emmetropization", "Accommodation", "Dynamic Refraction", "Phototransduction"], "correct": 0, "explanation": "Emmetropization is the process by which the refractive components and axial length come into balance for clear distance vision during development. Growth toward emmetropia = emmetropization."}'),
  ('4715f076-31','{"options": ["Loss of elasticity in the lens", "Overproduction of aqueous humor", "Degeneration of the retinal photoreceptors", "Increased intraocular pressure"], "correct": 0, "explanation": "Presbyopia is primarily due to loss of elasticity of the crystalline lens (with ciliary/zonular changes), reducing accommodative ability. Stiffening lens = presbyopia."}'),
  ('01fb4aec-1t','{"options": ["Hyperopia requires additional accommodation to focus on near objects", "Hyperopia requires less accommodation to focus on near objects", "Hyperopia does not affect the need for accommodation", "Hyperopia leads to excessive accommodation for distant vision"], "correct": 0, "explanation": "A hyperope must use EXTRA accommodation even for distance, and more still for near, so hyperopia increases the accommodative demand for near objects. Hyperopia = needs more accommodation."}'),
  ('9d60cc2f-3y','{"options": ["Direct contraction of the lens capsule fibers increasing the radius of curvature", "Alterations in the vitreous humor pressure pushes the crystalline lens forward", "Changes in the tension of the zonular fibers due to ciliary muscle contraction", "Expansion and contraction of the retina due to elongation of the axial length"], "correct": 2, "explanation": "In Helmholtz''s theory, ciliary muscle contraction RELAXES the zonular fibers, letting the lens round up (steepen) to focus near. Accommodation = ciliary contraction loosens zonules."}'),
  ('d042aa94-2k','{"options": ["A larger amplitude of accommodation results in a closer near point", "A larger amplitude of accommodation results in a farther near point", "The amplitude of accommodation does not affect the near point of vision", "The near point of vision is independent of accommodation amplitude but depends on pupil size"], "correct": 0, "explanation": "A larger amplitude of accommodation brings the near point CLOSER (you can focus on nearer objects). More amplitude = nearer near point."}'),
  ('13e6594f-2s','{"options": ["Hyperopia measurements are generally reduced during cycloplegic refraction due to temporary paralysis of the ciliary muscle", "Hyperopia measurements remain unchanged during cycloplegic refraction as the eye''s accommodative response is suppressed", "Hyperopia measurements are increased during cycloplegic refraction because the eye cannot accommodate to reduce the error", "Cycloplegic refraction often results in more accurate measurements of hyperopia without significant change"], "correct": 2, "explanation": "Under cycloplegia the eye cannot accommodate to mask its hyperopia, so the measured hyperopia INCREASES (the full, including latent, hyperopia shows). Cycloplegia reveals more hyperopia."}'),
  ('9765bde8-3i','{"options": ["Cycloplegic retinoscopy", "Auto-refraction", "Static retinoscopy", "Corneal topography"], "correct": 0, "explanation": "To measure the TOTAL hyperopia including the latent component, perform cycloplegic retinoscopy (it relaxes accommodation that otherwise hides latent hyperopia). Total/latent hyperopia = cycloplegic retinoscopy."}'),
  ('6054b7e2-4w','{"options": ["It will enhance their ability to focus on close objects", "It will exacerbate the difficulty of focusing on near objects and increase visual discomfort", "It will have no effect on near tasks", "It will only affect distance vision"], "correct": 1, "explanation": "Accommodative insufficiency in a hyperope worsens near focusing and increases visual discomfort (the patient already needs extra accommodation). Hyperope plus accommodative insufficiency = harder, more uncomfortable near work."}'),
  ('cfa34e78-29','{"options": ["Myopia", "Hyperopia", "Emmetropia", "Either A or B"], "correct": 1, "explanation": "Cornea plana (an abnormally flat cornea) has low refractive power, producing hyperopia. Flat cornea = hyperopia."}'),
  ('04c8b2da-2g','{"options": ["To correct myopia temporarily during the day", "To provide a permanent cure for myopia", "To reshape the cornea overnight to reduce myopia and manage progression", "To increase the degree of myopia to counteract axial elongation"], "correct": 2, "explanation": "Orthokeratology reshapes the cornea overnight to temporarily reduce myopia and help control its progression. Ortho-K = overnight corneal reshaping for myopia control."}'),
  ('e91c29e1-2x','{"options": ["0.01%", "0.025%", "0.05%", "0.10%"], "correct": 0, "explanation": "Low-dose atropine 0.01% is the concentration most commonly used for myopia-progression control (good effect, minimal side effects/rebound). Myopia control = atropine 0.01%."}'),
  ('9dafa931-2f','{"options": ["Nocturnal myopia;", "Pseudomyopia;", "Simple myopia;;", "Induced myopia"], "correct": 0, "explanation": "Myopia that WORSENS in LOW LIGHT = NOCTURNAL (night) myopia — in dim light the pupil dilates (more spherical aberration) and accommodation rests at a nearer dark-focus, shifting the eye myopic. Pseudomyopia is spasm; simple/induced differ. Night-worse myopia = nocturnal myopia."}'),
  ('e0d47933-23','{"options": ["Lacrimal", "Zeis", "Meibomian", "Moll"], "correct": 2, "explanation": "In distichiasis the aberrant second row of lashes arises from the meibomian gland orifices (metaplastic). Zeis and Moll serve the normal anterior lashes. Extra lashes = from meibomian openings."}'),
  ('3f645bc0-1j','{"options": ["CN2", "CN3", "CN7", "SNS"], "correct": 1, "explanation": "The levator palpebrae superioris is innervated by cranial nerve III (oculomotor), so CN III palsy causes complete ptosis. Muller''s muscle is sympathetic. Levator = CN III; Muller''s = sympathetic."}'),
  ('a338ef90-5a','{"options": ["Bi-Nasal Heteronymous Hemianopsia", "Bi-Temporal Heteronymous Hemianopsia", "Left Homonymous Hemianopsia", "Right Homonymous Hemianopsia"], "correct": 1, "explanation": "Bumping into objects in the periphery on both sides points to loss of both temporal (peripheral) fields, a bitemporal heteronymous hemianopsia (a chiasmal pattern, as from a pituitary/parasellar mass). The temporal-field loss takes out peripheral awareness on both sides. Bilateral peripheral bumping = bitemporal hemianopsia."}'),
  ('6dcfa6b8-1f','{"options": ["Optic Nerve", "Optic Chiasm", "Optic Tract", "Area Striata"], "correct": 1, "explanation": "A bitemporal field loss localizes to the optic chiasm, where the crossing nasal fibers (serving the temporal fields) are compressed. Bitemporal defect = chiasm."}'),
  ('4dbda04f-12','{"options": ["Visual Disorder", "Visual Impairment", "Visual Handicap", "Visual Disability"], "correct": 1, "explanation": "A restricted visual field is a VISUAL IMPAIRMENT — a measurable loss of visual function (WHO ICF terms). ''Disorder'' is the underlying pathology; ''disability/handicap'' describe the functional/social consequence (Q6). Ladder: disorder (disease) → impairment (function lost) → disability (activity limited) → handicap (participation limited)."}'),
  ('3961c1f6-20','{"options": ["Relative Size", "Optical", "Electronic", "Approach"], "correct": 3, "explanation": "APPROACH magnification = moving the target CLOSER to the eye, increasing its angular (retinal-image) size — the simplest low-vision magnification (relative distance magnification). Relative SIZE magnification enlarges the object itself; optical uses lenses; electronic uses a screen. Four low-vision magnifications: relative size, relative distance (approach), angular (telescope), electronic."}'),
  ('e5bac157-2m','{"options": ["Hemianopsia", "Central Scotoma", "Field Restriction", "Quadrantanopsia"], "correct": 3, "explanation": "Leaving out PARTS of letters (E read as F, R as P) implies a defect cutting across the letter''s field — a QUADRANTANOPSIA (a quadrant of each letter''s image is missing). A central scotoma blanks the whole center; field restriction shrinks the periphery. Pattern: partial-letter errors = localized quadrant field loss overlying reading."}'),
  ('69d876bb-1c','{"options": ["Ipsilateral blindness with present direct light reflex", "Ipsilateral blindness with absent direct light reflex", "Contralateral blindness with present direct light reflex", "Contralateral blindness with absent direct light reflex"], "correct": 1, "explanation": "A left optic nerve lesion causes ipsilateral (left eye) blindness with an ABSENT direct light reflex (no afferent signal), though the consensual reflex from the other eye is preserved. Optic nerve lesion = same-side blindness, no direct response."}'),
  ('c3027c66-2k','{"options": ["1.2in", "3in", "7.7in", "10in"], "correct": 1, "explanation": "Focal length of a +13 D lens = 100/13 = 7.7 cm, which is about 3 inches. Hold reading material at the lens focal length: about 3 inches. Reading distance = 1/F."}'),
  ('a4d1c5e8-19','{"options": ["Anterior Synechia", "Posterior Synechia", "Pupillary Synechia", "Corneal Synechia"], "correct": 1, "explanation": "POSTERIOR synechia = adhesion of the IRIS to the LENS (behind the iris), classically from iritis/uveitis, risking iris bombé and secondary glaucoma. ANTERIOR synechia = iris to cornea/angle. Mnemonic: posterior synechia = iris stuck to the lens BEHIND it."}'),
  ('5e6ea7e5-2a','{"options": ["Color deficiency", "Hazy vision", "Jumping of lines when reading", "Orientation and mobility"], "correct": 3, "explanation": "Peripheral field constriction (e.g., advanced glaucoma, RP) most impairs ORIENTATION and MOBILITY — patients keep central acuity but lose the peripheral ''where am I'' field, so they bump into things and navigate poorly. Color/hazy vision/line-jumping relate to other deficits. Tunnel vision = mobility problem."}'),
  ('d407837b-x','{"options": ["Cone Dystrophy.", "Rod Dystrophy.", "Rod-Cone Dystrophy .", "Cone-Rod Dystrophy."], "correct": 2, "explanation": "Retinitis pigmentosa is a ROD-CONE dystrophy — rods degenerate FIRST (night blindness, then peripheral/ring scotoma, tunnel vision), cones later. Cone-rod dystrophy is the reverse (central loss first, Q15). RP mnemonic: ''Rods die first → night blindness + peripheral loss.''"}'),
  ('78f3d699-2o','{"options": ["Cone Dystrophy", "Rod Dystrophy", "Rod-Cone Dystrophy", "Cone-Rod Dystrophy"], "correct": 3, "explanation": "Field loss starting CENTRALLY and spreading outward = CONE-ROD dystrophy (cones, concentrated centrally, degenerate first → early central acuity/color loss and photophobia, then peripheral). Rod-cone (RP) is the opposite (Q14). Direction of loss tells you which photoreceptor leads: central-out = cones first."}'),
  ('a6481869-1l','{"options": ["Left TAPD", "Right TAPD", "Right EPD", "Left EPD"], "correct": 2, "explanation": "OD: no direct AND no consensual constriction; OS: both present. OD never constricts regardless of which eye is lit, but OS reacts normally = an EFFERENT (motor) pupillary defect of OD (Right EPD) — the OD sphincter/CN III output is out, while afferent input is intact (it still drives OS). Afferent defect would instead spare OD''s ability to constrict. Direct AND consensual absent in one eye = efferent."}'),
  ('33534e6a-1m','{"options": ["Glaucoma ..", "ARMD..", "Hemianopsia ..", "Retinitis Pigmentosa.."], "correct": 1, "explanation": "ARMD (macular degeneration) — a CENTRAL field loss with preserved peripheral field — benefits MOST from magnification (enlarge the image onto healthy surrounding retina/eccentric viewing). Glaucoma/RP (peripheral loss) and hemianopsia gain little from magnification (it just pushes more image into the blind area). Rule: central-loss conditions love magnifiers."}'),
  ('2c4df79d-2i','{"options": ["+5.75D", "+14.25D", "+17.50D", "+28.00D"], "correct": 2, "explanation": "Magnification referenced to a distance other than 25 cm: M = F / F_ref, where F_ref = 100/40 cm = 2.5 D. For 7X: F = 7 × 2.5 = +17.50 D. The reference distance sets the baseline dioptric demand. Cross-link: standard 25 cm reference gives M = F/4; here 40 cm gives M = F/2.5."}'),
  ('4f18470b-1y','{"options": ["Trochlear", "Abducens", "Oculomotor", "Optic"], "correct": 2, "explanation": "The oculomotor nerve (CN III) carries the parasympathetic fibers that drive pupil constriction. Trochlear/abducens are pure motor to eye muscles; optic is afferent. Pupil constriction efferent = CN III."}'),
  ('1cf53f91-y','{"options": ["Positive Relative Scotoma", "Negative Relative Scotoma", "Positive Absolute Scotoma", "Negative Absolute Scotoma"], "correct": 3, "explanation": "The physiologic blind spot is a NEGATIVE ABSOLUTE scotoma: absolute (no perception — the disc has no photoreceptors) and negative (the patient is unaware; it''s perceptually filled in). Positive scotomas are noticed by the patient. Cross-link: same concept tested in the physio subject."}'),
  ('af7cb040-3u','{"options": ["Presence of Absolute Scotoma", "Presence of Relative Scotoma", "Presence of Negative Scotoma", "Presence of Positive Scotoma"], "correct": 1, "explanation": "Missing the first (dimmer) stimulus but seeing the second (brighter) one indicates a RELATIVE scotoma (reduced, not absent, sensitivity). Sees the stronger stimulus = relative scotoma."}'),
  ('4cd1c6d6-2d','{"options": ["Presence of Absolute Scotoma.", "Presence of Relative Scotoma.", "Presence of Negative Scotoma.", "Presence of Positive Scotoma."], "correct": 0, "explanation": "Missing BOTH presentations (even the brighter/repeat stimulus is not seen) = ABSOLUTE scotoma — no perception at that locus regardless of stimulus. Contrast Q22 (relative = stronger stimulus seen). Absolute = total local loss."}'),
  ('180f12ae-2c','{"options": ["Left Superior Homonymous Quadrantanopsia", "Right Superior Homonymous Quadrantanopsia", "Left Inferior Homonymous Quadrantanopsia", "Right Inferior Homonymous Quadrantanopsia"], "correct": 0, "explanation": "RIGHT MEYER''S LOOP (temporal-lobe radiation) carries the INFERIOR retinal/ SUPERIOR field fibers, so a right-side lesion gives a LEFT SUPERIOR homonymous quadrantanopsia (''pie in the sky''). Temporal loop = superior field; right lesion = left field. Mnemonic: Meyer''s loop, temporal → ''pie in the sky.''"}'),
  ('5b12cebd-2c','{"options": ["Left Superior Homonymous Quadrantanopsia.", "Right Superior Homonymous Quadrantanopsia.", "Left Inferior Homonymous Quadrantanopsia.", "Right Inferior Homonymous Quadrantanopsia."], "correct": 2, "explanation": "RIGHT BAUM''S LOOP (parietal/superior radiation) carries SUPERIOR retinal/ INFERIOR field fibers → a right lesion gives a LEFT INFERIOR homonymous quadrantanopsia (''pie on the floor''). Parietal = inferior field. Pair with Q24: temporal=superior, parietal=inferior quadrant."}'),
  ('d3c96a5e-1w','{"options": ["Bi-Nasal Heteronymous Hemianopsia", "Bi-Temporal Heteronymous Hemianopsia", "Bi-Nasal Heteronymous Hemianopsia w/ Hemianopic Pupils", "Bi-Temporal Heteronymous Hemianopsia w/ Hemianopic Pupils"], "correct": 1, "explanation": "A pituitary adenoma compresses the CENTER of the chiasm (crossing nasal fibers) → BITEMPORAL heteronymous hemianopsia (loss of both temporal fields). No hemianopic pupil because it''s a chiasmal (not tract) lesion. Classic neuro pearl: ''pituitary → bitemporal.'' Binasal would need bilateral lateral chiasm compression."}'),
  ('a6d0e5f4-24','{"options": ["Left Homonymous Hemianopsia", "Right Homonymous Hemianopsia", "Left Homonymous Hemianopsia w/ Wernicke’s Pupil", "Right Homonymous Hemianopsia w/ Wernicke''s Pupil"], "correct": 0, "explanation": "A right LGB lesion gives a LEFT homonymous hemianopsia, and because the LGB is past the tract, the PUPIL reflex is SPARED (no Wernicke''s pupil — that''s a tract-level sign). Localization: post-LGB lesions spare the pupil. Cross-link: tract lesion would add Wernicke''s hemianopic pupil."}'),
  ('92461760-2d','{"options": ["Right A17", "Left A17", "Right LGB", "Left LGB"], "correct": 0, "explanation": "Left homonymous hemianopsia WITH MACULAR SPARING localizes to the right OCCIPITAL cortex (area 17, A17) — the macula''s large cortical representation has dual (MCA+PCA) blood supply, so it is spared in occipital (often PCA) infarcts. Macular sparing = occipital lesion hallmark. LGB lesions don''t spare the macula."}'),
  ('e551cad6-2j','{"options": ["Left Superior Homonymous Quadrantanopsia.", "Right Superior Homonymous Quadrantanopsia.", "Left Inferior Homonymous Quadrantanopsia.", "Right Inferior Homonymous Quadrantanopsia."], "correct": 0, "explanation": "Right TEMPORAL radiation (Meyer''s loop) lesion → LEFT SUPERIOR homonymous quadrantanopsia (same as Q24). Temporal loop carries superior-field fibers; right side = left field. Reinforced pattern: temporal = superior quadrant defect."}'),
  ('e1be502e-2j','{"options": ["Left Superior Homonymous Quadrantanopsia", "Right Superior Homonymous Quadrantanopsia", "Left Inferior Homonymous Quadrantanopsia", "Right Inferior Homonymous Quadrantanopsia"], "correct": 2, "explanation": "Right PARIETAL radiation lesion → LEFT INFERIOR homonymous quadrantanopsia (same as Q25). Parietal carries inferior-field fibers. Pair: temporal=superior ''sky'', parietal=inferior ''floor.''"}'),
  ('1bdf3e73-2x','{"options": ["OD – DLR +", "OD – CLR +", "OS – DLR +", "OS – CLR –"], "correct": 2, "explanation": "A left postganglionic (efferent) lesion stops the left pupil from constricting, so OS direct (OS-DLR) would be ABSENT; the listed ''OS-DLR +'' is therefore the exception (it would not be observed). The bad eye cannot constrict to its own light."}'),
  ('3d9ab922-2u','{"options": ["OD – DLR +", "OD – CLR +", "OS – DLR +", "OS – CLR –"], "correct": 0, "explanation": "A complete left optic nerve lesion abolishes responses driven by light into OS, but light into OD still gives a normal OD direct response, so ''OD-DLR +'' is the one reflex that is NOT absent. The intact eye''s own direct reflex persists."}'),
  ('bed5f419-1t','{"options": ["Magnifying the image", "Allowing visual information to fit into a restricted area", "Improving visual acuity", "Brief orientation, such as object localization"], "correct": 2, "explanation": "Reverse (Galilean) telescopes minify to fit more into a restricted field and aid brief localization, but they do NOT improve visual acuity (they make things smaller). Reverse telescope = field expansion, not acuity."}'),
  ('b534718a-3h','{"options": ["Relative size magnification", "Relative distance magnification", "Angular magnification", "Projection magnification"], "correct": 2, "explanation": "Angular magnification makes an object appear larger without changing its actual position or size (as with telescopes/optical systems). Apparent size increase via optics = angular magnification."}'),
  ('1716f2f0-29','{"options": ["66 cm", "6.6 cm", "0.6 cm", "660 cm"], "correct": 1, "explanation": "Focal length of a +15 D lens = 100/15 = 6.7 cm. Hold the material at about 6.6 cm. Reading distance = 1/F."}'),
  ('c4665139-2k','{"options": ["+28.00D", "+24.00D", "+15.00D", "+10.00D"], "correct": 1, "explanation": "Hand magnifier power for 6X (M = F/4) = 4 x 6 = 24 D. 6X = +24.00 D."}'),
  ('d761b13d-1n','{"options": ["Prescription lenses", "Telescope", "Reduction of glare and improved contrast", "Field enhancers"], "correct": 2, "explanation": "Absorptive lenses reduce glare and improve contrast (and block UV). That glare/contrast benefit is their main advantage. Absorptive = glare control and contrast."}'),
  ('8f46b21a-5e','{"options": ["12X", "10X", "8X", "6X"], "correct": 1, "explanation": "Telescope magnification = objective diameter / exit pupil diameter = 20/2 = 10X. Mag = entrance/exit pupil ratio."}'),
  ('f1ca918a-3o','{"options": ["+20.00D", "+10.00D", "+5.00D", "+2.50D"], "correct": 0, "explanation": "Kestenbaum''s rule predicts the add as the reciprocal of the best-corrected acuity: 10/200 (= 20/400) gives 400/20 = +20 D. Kestenbaum add = 1/(best VA)."}'),
  ('fb4ed3aa-2z','{"options": ["+7.50D", "+4.25D", "+10.00D", "+14.50D"], "correct": 0, "explanation": "With a 40 cm reference, M = F x 0.4, so F = 3/0.4 = 7.5 D. 3X at 40 cm = +7.50 D."}'),
  ('688a2200-3h','{"options": ["Microscopic glasses", "Hand-held magnifier", "Prism glasses", "Telescopic lens"], "correct": 1, "explanation": "For an AMD patient with reading difficulty, a hand-held magnifier is an appropriate, flexible low-vision aid for spot reading. AMD reading = hand magnifier (often with light)."}'),
  ('5ea94f09-25','{"options": ["Correct refractive errors", "Improve visual acuity", "Enhance the ability to perform daily living activities", "Provide optical aids"], "correct": 2, "explanation": "Occupational therapy in low-vision rehab aims to enhance the ability to perform daily living activities (function), not to correct refraction or restore acuity. OT goal = functional independence in ADLs."}'),
  ('2781aff6-2z','{"options": ["Peripheral vision training", "Color vision enhancement", "Central vision magnification", "Use of field expanders"], "correct": 3, "explanation": "A glaucomatous (peripheral field) loss is helped by field expanders (prisms/minifiers) that bring peripheral information into the remaining field. Peripheral field loss = field expansion aids."}'),
  ('5d35d4a1-1z','{"options": ["Specially designed reading glasses", "Voice-controlled computer software", "High-contrast paint for walls", "Protective eyewear"], "correct": 1, "explanation": "Adaptive technology in low-vision rehab includes voice-controlled (speech) computer software (assistive tech). High-tech assistance = voice/speech software."}'),
  ('37afbe0f-2p','{"options": ["Restoration of lost vision", "Maximization of remaining vision and independence", "Prevention of further vision loss", "Correction of refractive errors"], "correct": 1, "explanation": "For severe visual impairment, the primary focus is maximizing remaining vision and independence (rehabilitation), not restoring lost vision. Severe low vision = maximize function and independence."}'),
  ('a326730b-2x','{"options": ["Magnifying reading glasses", "High-powered magnifier", "Telescope", "Near vision goggles"], "correct": 2, "explanation": "A telescope is the common aid for distance vision enhancement in low vision. Distance aid = telescope; near aids = magnifiers."}'),
  ('e6e530e0-1e','{"options": ["A low vision aid for central vision", "Training in head and eye scanning techniques", "A hand-held magnifier", "Bifocal lenses"], "correct": 1, "explanation": "A patient with hemianopsia benefits most from training in head and eye scanning to compensate for the missing half-field. Hemianopsia = scanning training."}'),
  ('c51e0ead-2z','{"options": ["Difficulty seeing peripheral objects", "Difficulty reading or recognizing faces", "Complete blindness in one eye", "Loss of depth perception"], "correct": 1, "explanation": "Central vision loss in AMD chiefly causes difficulty reading and recognizing faces (central detail), with peripheral mobility relatively preserved. AMD = central detail loss (reading/faces)."}'),
  ('0bb04ddb-2m','{"options": ["Use of low vision aids and orientation training", "Prescription of high-powered glasses", "Surgery to repair the retina", "Use of anti-VEGF injections"], "correct": 0, "explanation": "Retinitis pigmentosa is managed with low-vision aids plus orientation and mobility training (for the constricted field). There is no curative surgery or anti-VEGF for RP itself. RP = aids + O and M training."}'),
  ('94ca326c-21','{"options": ["Ability to distinguish between different colors", "Ability to perceive fine details", "Ability to distinguish objects from their background", "Ability to focus on near and distant objects"], "correct": 2, "explanation": "Contrast sensitivity is the ability to distinguish an object from its background (not fine detail or color). Object-from-background = contrast sensitivity."}'),
  ('342758e1-31','{"options": ["Night vision goggles", "Hand-held magnifier with a built-in light", "Colored filters", "Field enhancement lenses"], "correct": 1, "explanation": "For difficulty in low light, a hand-held magnifier with a built-in light adds both magnification and illumination. Low-light reading = illuminated magnifier."}'),
  ('09712da8-2i','{"options": ["Optical aids", "Non-optical aids", "Orientation and mobility training", "Surgery"], "correct": 3, "explanation": "Surgery is generally NOT a rehabilitation method for severe low vision (rehab uses optical/non-optical aids and O and M training). Rehab is non-surgical."}'),
  ('19638aa9-22','{"options": ["Using the peripheral retina to compensate for central vision loss", "Adjusting the position of the head to view objects more clearly", "Focusing on distant objects while using near vision aids", "Scanning the visual field to locate objects"], "correct": 0, "explanation": "Eccentric viewing uses the peripheral (non-foveal) retina to compensate for central vision loss (looking slightly off-target). Use the side of the retina = eccentric viewing."}'),
  ('d4e98048-24','{"options": ["Amsler Grid", "Snellen Chart", "Pelli-Robson Contrast Sensitivity Chart", "Humphrey Visual Field Analyzer"], "correct": 2, "explanation": "The Pelli-Robson chart is the standard clinical test of contrast sensitivity. Contrast sensitivity = Pelli-Robson."}'),
  ('45c7e26c-29','{"options": ["Glaucoma", "Myopia", "Hyperopia", "Presbyopia"], "correct": 0, "explanation": "Glaucoma is commonly associated with reduced contrast sensitivity (beyond the field loss). Glaucoma = decreased contrast sensitivity."}'),
  ('82d6f9de-2l','{"options": ["Radical retinoscopy and bracketing method", "Automated refraction and fogging", "Off axis retinoscopy and fogging", "Automated refraction and bracketing method"], "correct": 0, "explanation": "Low-vision refraction uses radical (close) retinoscopy and the bracketing (just-noticeable-difference) method, because standard techniques are unreliable at low acuity. Low-vision refraction = radical retinoscopy + bracketing."}'),
  ('ec7d0a3a-4j','{"options": ["+7.50D", "+10.00D", "+12.50D", "+15.00D"], "correct": 3, "explanation": "Starting-acuity technique: reading 6M but needing 1M means 6X magnification, so the add scales 6x the 40 cm base (2.5 D x 6 = +15 D). Required-over-achieved size = magnification, then scale the add."}'),
  ('a474d47a-2c','{"options": ["1.5 X", "4 X", "5.5 X", "7 X"], "correct": 1, "explanation": "Magnification = final size / initial size = 6M / 1.5M = 4X. Enlargement ratio = 4X."}'),
  ('c36aec97-4a','{"options": ["1.5 X", "2 X", "4.5 X", "6 X"], "correct": 1, "explanation": "Telescope magnification = eyepiece power / objective power = 30/15 = 2X. Mag = Fe/Fo."}'),
  ('11c5f2da-44','{"options": ["1.7 cm", "3.33 cm", "5.68 cm", "8.33 cm"], "correct": 3, "explanation": "Keplerian telescope length = focal length of objective + eyepiece = 1/20 + 1/30 = 0.05 + 0.033 = 0.083 m = 8.33 cm. Length = fo + fe."}'),
  ('3b47ef61-4s','{"options": ["8 X", "10 X", "12 X", "14 X"], "correct": 2, "explanation": "Moving the head halfway between its original position and the screen halves the distance, doubling relative-distance magnification: 6X x 2 = 12X total. Halve the distance = double the magnification."}'),
  ('cbcd033e-40','{"options": ["Electronic magnifier", "Microscopic glasses", "Hand-held magnifier", "Stand magnifier"], "correct": 2, "explanation": "To read price tags while shopping (portable, near, spot use), a hand-held magnifier is the most practical optical aid. Portable spot near task = hand magnifier."}'),
  ('0fbc9d9c-55','{"options": ["Recommend over-the-counter reading glasses", "Refer the patient for a comprehensive eye examination to assess for aniseikonia", "Advise the patient to use magnifying glasses for reading", "Suggest the patient try various reading positions to find one that is comfortable"], "correct": 1, "explanation": "Words appearing larger in one eye suggests aniseikonia, so refer for a comprehensive exam to assess it. Unequal image size = work up aniseikonia."}'),
  ('1a136814-47','{"options": ["Incorrect prescription of corrective lenses", "Ocular alignment issues due to binocular vision problems", "Normal age-related changes in vision", "A recent increase in screen time without adequate breaks"], "correct": 1, "explanation": "Diplopia in aniseikonia usually reflects associated ocular alignment/binocular vision problems. Aniseikonia plus diplopia = binocular alignment issue."}'),
  ('cbc6c48c-5i','{"options": ["Using high-definition contact lenses", "Prescribing specialized aniseikonia- correcting lenses", "Implementing a vision therapy program", "Recommending regular eye exercises and eye rest breaks"], "correct": 1, "explanation": "The perceptual size difference is addressed with specialized aniseikonia-correcting (iseikonic) lenses. Size mismatch = iseikonic lenses."}'),
  ('a34c2349-3v','{"options": ["A significant difference in the degree of refractive error between the two eyes", "Presence of a cataract in one eye", "Recent eye surgery affecting visual acuity", "Development of strabismus in one eye"], "correct": 0, "explanation": "A significant difference in refractive error between the eyes (anisometropia) is what most necessitates magnification/reduction (size-correcting) lenses. Large anisometropia = size-correcting lenses."}'),
  ('d09e8c3e-4j','{"options": ["Increasing the contrast on their computer screen", "Taking regular breaks and adjusting screen distance and angle", "Using an anti-glare screen protector", "Switching to a different type of computer monitor"], "correct": 1, "explanation": "Computer-related worsening of aniseikonia symptoms is eased by taking regular breaks and adjusting screen distance/angle (ergonomics). Screen strain = breaks and ergonomics."}'),
  ('c6965295-4p','{"options": ["Amsler grid", "Aniseikonia test lenses", "Visual acuity chart", "Binocular vision assessment"], "correct": 1, "explanation": "Aniseikonia test lenses (size lenses) quantify the magnitude of the interocular image-size difference. Measure aniseikonia = aniseikonia test lenses."}'),
  ('8c7aaafa-3e','{"options": ["Persistent headaches", "Blurred vision in low light conditions", "Difficulty with color perception", "Occasional eye strain after reading"], "correct": 0, "explanation": "Persistent headaches signal a need for intervention beyond a routine lens correction in aniseikonia. Ongoing headache = needs more than basic lenses."}'),
  ('137863f0-4n','{"options": ["Customizing the lens power based on visual acuity measurements", "Ensuring proper alignment and fitting of the lenses", "Regularly updating the prescription as the patient''s vision changes", "Using the lenses only during specific activities such as reading or driving"], "correct": 1, "explanation": "Proper alignment and fitting of the specialized lenses is crucial to their effectiveness in aniseikonia (decentration ruins the size correction). Size lenses = precise fit/alignment."}'),
  ('150f7aaa-4q','{"options": ["The impact of trauma on the refractive error", "Ensuring proper alignment and fitting of the lenses", "Regularly updating the prescription as the patient''s vision changes", "Using the lenses only during specific activities such as reading or driving"], "correct": 0, "explanation": "With recent trauma, evaluate the impact of the trauma on the refractive error first (it may explain the new aniseikonia). Post-trauma aniseikonia = reassess the refraction."}'),
  ('b4fd2290-71','{"options": ["Perform the Maddox rod test to assess the degree of exodeviation", "Refer the patient for color vision testing", "Conduct a visual acuity test to rule out refractive errors", "Administer the Amsler grid to check for macular degeneration"], "correct": 0, "explanation": "An exodeviation on cover test with reading diplopia is next quantified with the Maddox rod to measure the deviation. Measure the phoria/tropia = Maddox rod."}'),
  ('1598c73f-6s','{"options": ["Convergence insufficiency", "Stereopsis loss", "Color vision deficiency", "Ocular alignment issue"], "correct": 0, "explanation": "A receded near point of convergence (10 cm) with near headaches indicates convergence insufficiency. Remote NPC + near strain = convergence insufficiency."}'),
  ('11f01ec7-44','{"options": ["Suppression in one eye", "Normal binocular vision", "Presence of a significant phoria", "Visual acuity discrepancy"], "correct": 0, "explanation": "Seeing three dots on the Worth four-dot test indicates suppression of one eye (the two-light eye is suppressed). Three dots = suppression."}'),
  ('a4816734-7b','{"options": ["Use the Maddox rod test to evaluate for potential latent strabismus", "Perform a color vision test to rule out color deficiencies", "Administer the Farnsworth-Munsell 100 Hue test for color vision issues", "Conduct dynamic retinoscopy to assess for refractive errors"], "correct": 0, "explanation": "New diplopia with a normal cover-uncover test is investigated with the Maddox rod to reveal a latent deviation/phoria. Hidden deviation = Maddox rod."}'),
  ('f76be52b-51','{"options": ["Convergence insufficiency", "Refractive error", "Stereopsis loss", "Color vision deficiency"], "correct": 0, "explanation": "A large difference in vergence facility points to convergence insufficiency as the cause of the binocular symptoms. Poor vergence facility = convergence insufficiency."}'),
  ('ba533b74-3j','{"options": ["Refer the patient for a comprehensive strabismus evaluation", "Conduct a stereoacuity test to assess depth perception", "Perform an Amsler grid test for macular health", "Administer the Worth 4-Dot test to check for suppression"], "correct": 0, "explanation": "An asymmetric Hirschberg reflex after trauma warrants referral for a comprehensive strabismus evaluation. Traumatic misalignment = strabismus work-up."}'),
  ('aec04a41-74','{"options": ["Dynamic retinoscopy", "Stereoacuity test", "Color vision test", "Visual field test"], "correct": 1, "explanation": "Depth-perception difficulty with normal acuity is best investigated with a stereoacuity test. Assess depth = stereoacuity test."}'),
  ('0015c297-3o','{"options": ["Visual acuity test", "Dynamic retinoscopy", "Near point of convergence test", "Worth 4-Dot test"], "correct": 1, "explanation": "Dynamic retinoscopy best quantifies the accommodative response in suspected accommodative spasm. Measure accommodation = dynamic retinoscopy."}'),
  ('b3235a9f-5v','{"options": ["Cover test", "Aniseikonia test lenses", "Stereoacuity test", "Amsler grid"], "correct": 1, "explanation": "Aniseikonia test lenses give the most insight into the perceptual size distortions the patient reports. Perceptual size distortion = aniseikonia test lenses."}'),
  ('846d2586-6n','{"options": ["Correcting the refractive error with appropriate spectacles or contact lenses", "Implementing patching therapy immediately", "Starting visual exercises to improve eye coordination", "Monitoring the child for strabismus development"], "correct": 0, "explanation": "In a young child with amblyopia and significant refractive error, correcting the refractive error with spectacles comes first (refractive adaptation), before or alongside patching. Treat the refraction first."}'),
  ('2078a852-7p','{"options": ["Assess the integrity of the retina and optic nerve for possible underlying pathology", "Check for adherence to the occlusion schedule", "Reassess the initial diagnosis of amblyopia", "Evaluate the patient’s overall visual perceptual skills"], "correct": 0, "explanation": "When amblyopia fails to improve despite good occlusion, assess the retina and optic nerve for underlying organic pathology (rule out a structural cause). No improvement = look for organic disease."}'),
  ('410b7bb6-66','{"options": ["Evaluate and correct any residual refractive error or changes in the prescription", "Increase the duration of occlusion therapy", "Initiate visual therapy to address any latent strabismus", "Assess for any neurological issues affecting visual processing"], "correct": 0, "explanation": "Anisometropic amblyopia with poor response despite glasses → first RE-CHECK and CORRECT any residual refractive error / prescription change before escalating occlusion or chasing neurological causes. Optimize the optical correction FIRST — uncorrected residual blur stalls amblyopia therapy. Refraction before intensification."}'),
  ('6a81a0cc-58','{"options": ["Reassess the child’s binocular vision and consider intervention for the strabismus, which may be affecting amblyopia treatment", "Increase the occlusion therapy duration", "Switch to a different amblyopia treatment method", "Focus on improving depth perception through vision therapy"], "correct": 0, "explanation": "A treated amblyope who DEVELOPS a new esotropia → reassess BINOCULAR vision and address the STRABISMUS, since the new misalignment can derail amblyopia therapy (suppression). Don''t just lengthen occlusion or switch methods blindly — manage the emerging strabismus. New strabismus changes the treatment plan."}'),
  ('899ac59d-6f','{"options": ["The amblyopia treatment may have improved central visual acuity, but residual issues with binocular vision or depth perception may still be present", "The child is not using their prescribed corrective lenses properly", "The child may have developed a new visual or neurological condition", "The amblyopia treatment needs to be intensified further"], "correct": 0, "explanation": "Improved acuity but persistent poor DEPTH PERCEPTION after amblyopia treatment is most likely because therapy restored CENTRAL ACUITY while RESIDUAL BINOCULAR/stereo deficits remain — acuity and binocularity recover separately. Not lens misuse or new disease by default. Acuity ≠ stereopsis; binocular deficits can persist."}'),
  ('a9525665-7r','{"options": ["Perform a thorough evaluation to assess for any latent or underlying accommodative issues contributing to the exotropia", "Increase the frequency of occlusion therapy to full-time", "Refer the child for surgical correction immediately", "Recommend increased visual tasks and activities to strengthen eye muscles"], "correct": 0, "explanation": "Intermittent exotropia worse with fatigue/stress not improving on part-time occlusion → perform a thorough evaluation for LATENT/underlying ACCOMMODATIVE contributors before escalating occlusion or rushing to surgery. Find the accommodative-vergence driver first. Work-up before treatment escalation."}'),
  ('ae46eee3-75','{"options": ["Reevaluate the child''s ocular alignment and consider additional surgical intervention if necessary", "Increase the use of corrective lenses to manage the residual deviation", "Initiate a comprehensive vision therapy program to improve eye coordination", "Monitor the patient’s visual development and postpone further intervention"], "correct": 0, "explanation": "Residual esotropia after congenital eso surgery (still on glasses) → RE-EVALUATE alignment and consider ADDITIONAL surgical intervention if warranted; residual large-angle deviation often needs further surgery, not just more lenses or postponement. Reassess and re-operate if indicated."}'),
  ('db8ebd7c-7j','{"options": ["The development of a constant strabismus from previously intermittent strabismus", "The child''s refractive error has changed significantly", "The onset of a new neurological condition affecting ocular control", "Inadequate compliance with previously prescribed occlusion therapy"], "correct": 0, "explanation": "An intermittent strabismus becoming CONSTANT with new diplopia and a constant left esotropia = decompensation of a previously intermittent deviation into a CONSTANT one (loss of fusional control). Less likely a sudden refractive shift or new neuro disease as the first explanation, though red flags warrant work-up. Intermittent → constant = decompensation."}'),
  ('e8072ed2-6n','{"options": ["Evaluate the patient for any residual binocular vision disorders or anomalies", "Assess for changes in visual acuity", "Perform a color vision test to rule out color deficiencies", "Conduct a peripheral vision test to check for visual field deficits"], "correct": 0, "explanation": "Persistent binocular/depth difficulty AFTER successful alignment surgery → evaluate for RESIDUAL BINOCULAR VISION DISORDERS/anomalies (sensory fusion, suppression, stereo deficits) — motor alignment alone doesn''t guarantee sensory binocularity. Assess the SENSORY status post-op, not acuity/color/field first."}'),
  ('0990a900-6h','{"options": ["Assess for any trauma-related changes or complications affecting ocular alignment", "Recheck the patient''s refractive error and update the prescription", "Increase the use of prism glasses to manage the deviation", "Perform a visual field test to assess for any new visual deficits"], "correct": 0, "explanation": "Increased deviation AFTER recent eye TRAUMA in a post-strabismus patient → first ASSESS for trauma-related changes/complications affecting alignment (muscle/orbital injury, restriction). The history points to a mechanical/trauma cause before refraction, prism, or field testing. Trauma + new deviation = rule out injury-related restriction."}'),
  ('b404ad3e-67','{"options": ["The prisms may no longer be adequately compensating for the deviation; reassess the alignment and consider other treatment options", "The patient is not using the glasses consistently", "The child’s visual acuity has deteriorated, requiring a new prescription", "The prisms are causing visual discomfort, requiring a switch to contact lenses"], "correct": 0, "explanation": "Worsening symptoms on long-standing prism glasses → the PRISMS likely no longer fully compensate the (changed) deviation; REASSESS alignment and consider other options. Not just compliance, acuity, or comfort first — re-measure the deviation. Prisms need updating as the angle changes."}'),
  ('b492cb3e-6e','{"options": ["Evaluate for possible neurological or systemic causes of diplopia", "Reassess the strabismus surgery for potential complications", "Conduct a thorough review of the patient’s visual acuity changes", "Perform a test for visual field loss"], "correct": 0, "explanation": "New diplopia AFTER stable alignment and normal acuity post-surgery → evaluate for NEUROLOGICAL/SYSTEMIC causes of diplopia (the eyes are straight and see well, so the cause is likely elsewhere — decompensation, cranial nerve, systemic). Stable alignment + new diplopia → look beyond the muscles."}'),
  ('41746843-6r','{"options": ["Reevaluate the accommodative component and consider adjusting the refractive correction or increasing the intensity of vision therapy", "Increase the frequency of occlusion therapy", "Consider surgical intervention to address the persistent strabismus", "Recommend a new type of vision therapy focused on eye exercises"], "correct": 0, "explanation": "Accommodative esotropia persisting WITH glasses on despite VT → RE-EVALUATE the accommodative component and ADJUST the refractive correction (full plus / add) or intensify VT; residual eso through correction means the optical/accommodative management needs tuning (often a bifocal for high AC/A). Optimize plus before surgery."}'),
  ('94d819fe-6m','{"options": ["Implement vision therapy to improve accommodative convergence and reading comfort", "Increase the use of corrective lenses to manage the deviation", "Refer the patient for strabismus surgery to correct the alignment", "Focus on managing the patient’s visual acuity through specialized reading glasses"], "correct": 0, "explanation": "Constant exotropia with reading/near difficulty and normal acuity → VISION THERAPY to improve accommodative CONVERGENCE and reading comfort is the appropriate management (build convergence/fusion for near). Lenses/surgery aren''t first-line for a symptomatic but functional exo at near. Near-exo symptoms → convergence-focused VT."}'),
  ('fb66425b-3t','{"options": ["The patient has normal binocular vision with no significant suppression or anomalous retinal correspondence.", "The patient is experiencing a suppression in one eye, causing a reduction in the perceived number of dots.", "The patient has a significant strabismus, leading to diplopia with an abnormal fusion response.", "The patient may have an issue with depth perception, leading to an inaccurate count of the dots.", "The patient’s visual acuity is compromised, affecting the perception of the number of dots."], "correct": 0, "explanation": "Worth 4-Dot showing FOUR dots = NORMAL binocular fusion with no suppression or ARC issue (both eyes'' images fused). Seeing 2 or 3 = suppression; 5 = diplopia. Count rule: 4 = fusion (normal). Cross-link: physio Q44."}'),
  ('b6b272f6-56','{"options": ["The patient is exhibiting suppression in one eye, likely due to amblyopia or strabismus.", "The patient has a refractive error affecting the perception of the dots.", "The patient’s depth perception is compromised, affecting the fusion of the dots.", "The patient is misinterpreting the test due to inadequate lighting conditions.", "The patient’s visual acuity is not significantly affecting the test results."], "correct": 0, "explanation": "THREE dots on Worth 4-Dot = SUPPRESSION of one eye (the patient sees only the green set + fused light, dropping the red) — common with amblyopia/strabismus. 4 = fusion; 2 = suppression of the other eye; 5 = diplopia. 3 (or 2) dots = suppression."}'),
  ('03c4bb58-3z','{"options": ["Evaluate for possible suppression and assess the need for further strabismus or amblyopia treatment.", "Increase the occlusion therapy duration to address the suppression.", "Reassess the patient’s visual acuity to determine if it is affecting the results.", "Conduct a visual field test to check for any peripheral vision loss.", "Refer the patient for neuro-optometric rehabilitation to address potential neurological issues."], "correct": 0, "explanation": "Consistently TWO dots = suppression of one eye → EVALUATE for suppression and the need for further strabismus/amblyopia treatment (anti-suppression therapy). Don''t just lengthen occlusion or chase acuity/field/neuro first. 2 dots = active suppression to address."}'),
  ('2c091d3b-5n','{"options": ["Assess for the presence of any residual strabismus or binocular vision disorders and consider adjusting treatment.", "Increase the use of prism glasses to manage the misalignment.", "Focus on improving visual acuity through corrective lenses.", "Refer the patient for immediate strabismus surgery to correct the alignment.", "Implement additional vision therapy to improve binocular fusion."], "correct": 0, "explanation": "Intermittent exotropia with normal acuity but a CONSTANT misalignment on Worth 4-Dot → ASSESS for residual strabismus/binocular disorder and adjust treatment (the test reveals a manifest sensory problem). Reassess binocularity rather than defaulting to prisms, lenses, or immediate surgery. Test finding drives re-evaluation."}'),
  ('2bf3c807-55','{"options": ["Improved binocular fusion and resolution of suppression due to successful treatment or therapy.", "The patient may be experiencing temporary changes in visual acuity affecting their perception.", "The test conditions or equipment may have changed, affecting the result.", "The patient’s strabismus may have worsened, leading to a change in how the dots are perceived.", "There may be a new onset of neurological issues affecting binocular vision."], "correct": 0, "explanation": "A previously suppressing patient now seeing FOUR dots = improved binocular FUSION / resolution of suppression from successful therapy — a positive treatment response. Less likely a transient acuity change or equipment artifact. 2/3 → 4 dots = suppression resolving (good outcome)."}'),
  ('11c03205-6f','{"options": ["The patient has a left esotropia, as the light reflex displacement indicates an inward deviation of the left eye.", "The patient has a right exotropia, as the light reflex indicates an outward deviation.", "The patient’s eyes are aligned, and the reflex displacement is due to a refractive error.", "The patient has a left exotropia, with the light reflex displaced temporally.", "The Krimsky test is inconclusive and requires further diagnostic testing for accurate interpretation."], "correct": 0, "explanation": "Krimsky: a corneal reflex displaced TEMPORALLY in the left eye indicates the left eye is turned INWARD (nasally) = LEFT ESOTROPIA — an in-turned globe throws the reflex temporally. Direction rule: temporal reflex = esotropia; nasal reflex = exotropia. (Note this is the opposite convention to one physio item — temporal=eso is the standard.)"}'),
  ('87310d7f-5x','{"options": ["The presence of right esotropia, which should be evaluated for potential underlying causes and managed accordingly.", "The need to assess for possible refractive error correction.", "The requirement for immediate surgical intervention to correct the alignment.", "The potential development of amblyopia due to the misalignment.", "The necessity for increased occlusion therapy to improve binocular vision."], "correct": 0, "explanation": "Krimsky 15 PD with the reflex displaced TEMPORALLY in the right eye = RIGHT ESOTROPIA, which should be evaluated for underlying cause and managed (amblyopia risk, etc.). Temporal reflex = eso (Q111). The magnitude (Krimsky prism that centers the reflex) quantifies the deviation."}'),
  ('451af950-6n','{"options": ["Successful alignment correction, possibly due to recent strabismus surgery or therapy.", "Development of a new refractive error affecting the position of the corneal light reflex.", "Worsening of the strabismus, leading to altered light reflex positioning.", "The patient’s strabismus has become intermittent rather than constant.", "A change in the Krimsky test setup or procedure affecting the results."], "correct": 0, "explanation": "A reflex moving from NASAL to CENTRAL in the affected eye = the deviation has been CORRECTED/aligned (e.g., after surgery or therapy) — centered reflex = straight eye. Worsening would shift it further off-center; a refractive change wouldn''t center a strabismic reflex. Centering = successful alignment."}'),
  ('9d24996d-6j','{"options": ["The patient’s strabismus may be well- managed or resolved; however, continuous monitoring is necessary to ensure no recurrence.", "The patient’s visual acuity needs to be reassessed to confirm the absence of other visual issues.", "The patient may still be experiencing latent strabismus, requiring additional testing.", "The patient should be evaluated for other potential binocular vision disorders.", "Consider increasing the frequency of vision therapy to prevent future misalignment"], "correct": 0, "explanation": "Centered reflexes in BOTH eyes in a known intermittent exotrope = the deviation is currently WELL-CONTROLLED/aligned, but CONTINUE MONITORING for recurrence (intermittent deviations can decompensate). A straight Krimsky now doesn''t exclude future breaks. Manage with ongoing surveillance."}'),
  ('fdc561b0-56','{"options": ["The patient may have a bilateral esotropia or a convergent strabismus; a comprehensive evaluation of ocular alignment and potential treatment options is necessary.", "The patient’s visual acuity should be tested to rule out refractive errors.", "The Krimsky test may be inconclusive, requiring additional diagnostic tests to confirm the type of strabismus.", "The patient should be monitored for changes in strabismus over time before deciding on treatment.", "The corneal light reflex displacement indicates a need for immediate corrective lenses."], "correct": 0, "explanation": "Reflexes displaced TEMPORALLY in BOTH eyes = bilateral ESOTROPIA / convergent strabismus → comprehensive alignment evaluation and treatment planning. Temporal-both = both eyes turned in. Bilateral temporal reflex = bilateral eso."}'),
  ('e7312572-62','{"options": ["The child is not familiar with the test and needs more practice.", "The child may have significant binocular vision issues, such as strabismus or severe amblyopia, which affect depth perception.", "The child has a refractive error that needs to be corrected for accurate stereopsis.", "The test conditions were not optimal, affecting the child''s ability to perceive depth.", "The child may be experiencing temporary visual fatigue or discomfort"], "correct": 1, "explanation": "Inability to perceive the Stereo (butterfly) in 3D (seen as flat) most likely reflects significant BINOCULAR vision problems — strabismus or severe amblyopia disrupting stereopsis — rather than unfamiliarity, refractive error alone, or test conditions. No stereopsis on a gross stereo test points to a binocular/suppression deficit."}'),
  ('aec979d2-53','{"options": ["Re-administer the Stereobutterfly test under different lighting conditions.", "Perform a visual acuity test to check for any significant refractive errors.", "Increase the distance at which the Stereobutterfly test is administered.", "Assess for possible deficiencies in binocular vision or stereopsis and consider a comprehensive evaluation for strabismus or amblyopia.", "Conduct a color vision test to rule out any issues affecting depth perception."], "correct": 3, "explanation": "Seeing the butterfly but unable to judge which wing is CLOSER = reduced fine stereopsis → ASSESS for binocular vision/stereopsis deficiencies and consider a comprehensive strabismus/amblyopia evaluation. The relative-depth failure signals a stereo deficit needing work-up, not lighting/distance/color adjustments. Gross seen, fine stereo absent → evaluate binocularity."}'),
  ('3c30b6c1-4x','{"options": ["The Stereobutterfly test might be malfunctioning or incorrectly administered.", "The result indicates that the patient’s visual acuity is below normal levels.", "The patient has developed a color vision deficiency impacting stereopsis.", "The intermittent strabismus may be affecting the patient’s depth perception, leading to difficulties with stereopsis.", "The patient might be experiencing a new visual issue unrelated to their strabismus."], "correct": 3, "explanation": "An intermittent strabismic seeing the Stereobutterfly FLAT = the intermittent deviation is intermittently DISRUPTING stereopsis/depth perception. Not a malfunctioning test, low acuity, or color deficiency by default. Intermittent strabismus → variable/absent stereo."}'),
  ('a3376dd2-7k','{"options": ["The child might be over-relying on monocular cues rather than binocular depth perception.", "The Stereobutterfly test is not sensitive enough to detect subtle depth perception issues.", "The child’s stereopsis is functioning well in a controlled test environment but may not fully translate to functional depth perception in more complex or dynamic real-world scenarios.", "The child is not applying their stereopsis skills effectively in real-world tasks.", "The child might have other visual or neurological issues not addressed by the Stereobutterfly test."], "correct": 2, "explanation": "Accurate stereo in the controlled test but poor REAL-WORLD depth = the child''s stereopsis works in the simple test environment but doesn''t fully TRANSLATE to complex, dynamic real-world depth tasks (the test is a limited snapshot). Not necessarily monocular-cue overreliance or new pathology. Lab stereo ≠ functional real-world depth."}'),
  ('4de015f6-5b','{"options": ["Consider performing the test under different lighting or viewing conditions.", "Reassess the patient’s visual acuity to confirm that it remains within normal limits.", "Conduct a color vision test to ensure that there are no issues affecting depth perception.", "Evaluate for possible binocular vision disorders such as strabismus or suppression that might impair stereopsis despite normal visual acuity.", "Check for potential refractive errors that could affect stereopsis."], "correct": 3, "explanation": "Normal acuity but poor stereo (flat butterfly) → primary consideration is a BINOCULAR VISION DISORDER (strabismus/suppression) impairing stereopsis DESPITE good acuity — acuity and binocularity are independent. Evaluate binocular function before blaming lighting/color/refraction. Good VA + no stereo = binocular problem."}'),
  ('8afe53ff-3i','{"options": ["Custom soft toric lenses", "Hybrid lenses", "Scleral lenses", "Multifocal lenses"], "correct": 2, "explanation": "High myopia with corneal ECTASIA failing soft lenses → SCLERAL lenses: they vault the irregular/ectatic cornea on a fluid reservoir, masking irregular astigmatism and giving stable vision where soft/toric/multifocal designs can''t. Ectasia/irregular cornea → scleral. Cross-link: keratoconus/scarring (Q124, Q127)."}'),
  ('3fb3805f-2p','{"options": ["Incorrect lens power", "Lens dehydration", "Pupil size mismatch", "Corneal edema"], "correct": 2, "explanation": "Ortho-K night halos, worse in dim light, are typically from a PUPIL-SIZE/treatment-zone MISMATCH — the pupil dilates beyond the reshaped central optical zone, so light passes through the transition zone (halos/glare). Not lens power, dehydration, or edema per se. Pupil > optic zone at night → halos."}'),
  ('94eefcaf-33','{"options": ["Tear film instability", "Incorrect lens power", "Lens material incompatibility", "Corneal edema"], "correct": 0, "explanation": "FLUCTUATING vision with contact lenses most often reflects TEAR-FILM INSTABILITY (the lens surface dries/destabilizes between blinks, changing the optics). Power error gives steady blur; material incompatibility and edema have other signs. Vision that varies with blinking = tear film."}'),
  ('cf2a1ae4-3e','{"options": ["Corneal topography", "Schirmer’s test", "Tear break-up time (TBUT)", "Visual acuity testing"], "correct": 0, "explanation": "CORNEAL TOPOGRAPHY is crucial to monitor keratoconus progression and guide scleral fitting (maps steepening/cone shape over time). Schirmer/TBUT assess tears; VA is nonspecific. Keratoconus follow-up = topography (and tomography). Cross-link: bow-tie/cone patterns."}'),
  ('909199e5-3b','{"options": ["High water content soft lenses", "Scleral lenses", "Silicone hydrogel lenses", "RGP lenses"], "correct": 1, "explanation": "Chronic dry eye with AUTOIMMUNE disease (e.g., Sjögren) → SCLERAL lenses: the fluid reservoir continuously bathes and protects the ocular surface (also therapeutic for severe dry eye). High-water soft lenses worsen dryness; RGP/silicone don''t bathe the surface. Severe/autoimmune dry eye → scleral."}'),
  ('17fc2a98-2y','{"options": ["Soft toric lenses", "Hybrid lenses", "Scleral lenses", "Orthokeratology lenses"], "correct": 2, "explanation": "Severe corneal SCARRING (irregular surface) → SCLERAL lenses give the best visual rehabilitation by vaulting the scar and creating a smooth refracting tear lens. Soft toric/hybrid/ortho-K can''t neutralize gross irregularity. Irregular/scarred cornea → scleral. Reinforces Q121/Q124."}'),
  ('1e13c2d4-22','{"options": ["High myopia", "Irregular astigmatism", "Large pupils", "Active ocular surface disease"], "correct": 3, "explanation": "ACTIVE OCULAR SURFACE DISEASE is an ABSOLUTE contraindication to orthokeratology (overnight lens wear on a diseased/compromised surface risks infection/ulcer). High myopia, irregular astigmatism, and large pupils are relative considerations, not absolute bars. Active surface disease = no ortho-K."}'),
  ('caa9b676-1t','{"options": ["Increased oxygen permeability", "Easier removal", "Improved tear exchange", "Better comfort"], "correct": 2, "explanation": "A FENESTRATED scleral lens (small hole/vent) improves TEAR EXCHANGE under the lens, reducing reservoir stagnation/fogging and aiding oxygenation indirectly via fluid movement. The fenestration''s purpose is fluid/air exchange, not comfort or easier removal per se. Fenestration = tear/air exchange."}'),
  ('2300a696-1m','{"options": ["Hazy vision", "Superior lid irritation", "Excessive lens movement", "Central corneal touch"], "correct": 3, "explanation": "Central corneal touch indicates a poorly fitting (too flat) scleral lens, which should vault the cornea with clearance. Scleral lens touching the cornea = bad fit."}'),
  ('a978c643-38','{"options": ["Hydrogen peroxide-based solution", "Saline solution", "Enzymatic cleaner", "Daily disposable lenses"], "correct": 0, "explanation": "For a patient sensitive/allergic to multipurpose solutions, a hydrogen peroxide-based (preservative-free) system is recommended. Solution allergy = hydrogen peroxide care."}'),
  ('1c58b0da-4a','{"options": ["Lens edge design", "Solution toxicity", "Allergic reaction", "Lens material"], "correct": 0, "explanation": "Discomfort/redness with CONJUNCTIVAL staining (mechanical, at the lens edge contact zone) points to the LENS EDGE DESIGN as the cause (edge digging into conjunctiva). Solution toxicity/allergy give more diffuse corneal/conjunctival signs; material is nonspecific. Conjunctival (not corneal) staining → edge/mechanical fit."}'),
  ('ac57fc3f-1k','{"options": ["A patient with mild astigmatism", "A patient with high refractive error and irregular corneal shape", "A patient with presbyopia", "A patient with seasonal allergies"], "correct": 1, "explanation": "HIGH refractive error WITH an IRREGULAR corneal shape benefits most from CUSTOM soft lenses (bespoke parameters/optics). Mild astigmatism, presbyopia, and allergies are handled by standard designs. Custom soft = unusual prescriptions/corneal shapes that stock lenses can''t fit."}'),
  ('01e9809f-23','{"options": ["Lens durability", "Parental involvement in lens care", "High oxygen permeability", "Custom lens designs"], "correct": 1, "explanation": "When fitting young children, parental involvement in lens care and handling is the key consideration (safety and compliance). Pediatric CL = parental involvement."}'),
  ('cdebee4e-1y','{"options": ["Optical zone", "Base curve", "Lens diameter", "Peripheral curve"], "correct": 1, "explanation": "The base curve primarily determines how the lens fits the eye. Fit = base curve."}'),
  ('c7e499ed-1n','{"options": ["To provide refractive power", "To control lens movement and tear exchange", "To increase oxygen permeability", "To improve comfort"], "correct": 1, "explanation": "The peripheral curves of an RGP control lens movement and tear exchange (edge lift). Peripheral curves = movement and tear pumping."}'),
  ('76243a5a-32','{"options": ["Decrease lens diameter", "Steepen the base curve", "Flatten the base curve", "Increase lens thickness"], "correct": 1, "explanation": "EXCESSIVE soft-lens movement = a loose/flat fit → STEEPEN the base curve (smaller radius) to tighten centration and reduce movement. Flattening worsens it; changing diameter/thickness are secondary. Too much movement → steepen BC. (Opposite of a tight lens, which you flatten.)"}'),
  ('ab164a78-1w','{"options": ["Higher water content improves oxygen permeability", "Higher water content reduces lens dehydration", "Lower water content provides better vision stability", "Lower water content increases lens flexibility"], "correct": 0, "explanation": "Higher WATER content improves OXYGEN PERMEABILITY in conventional hydrogels (water carries dissolved O2 through the lens). Trade-offs: high water also dehydrates more and can destabilize the tear film (Q130). The asked significance: water content ↔ oxygen transmission (in hydrogels). Silicone hydrogels broke this water-Dk link."}'),
  ('e0c70e05-3f','{"options": ["Steepen the base curve", "Flatten the base curve", "Increase the lens diameter", "Decrease the optic zone diameter"], "correct": 0, "explanation": "RGP fluorescein showing CENTRAL TOUCH with PERIPHERAL POOLING = the lens is too FLAT centrally (apical bearing) → STEEPEN the base curve to lift the center and align. Pooling center/touch periphery would be the opposite (too steep). SAM-FAP / pattern: central touch = flat → steepen."}'),
  ('7f8bb3a8-3e','{"options": ["Increase add power in the near eye", "Decrease add power in the distance eye", "Use multifocal lenses instead of monovision", "Prescribe reading glasses over contact lenses"], "correct": 2, "explanation": "Monovision patient with poor INTERMEDIATE vision → switch to MULTIFOCAL lenses, which provide a continuous distance-intermediate-near range that monovision''s two single foci can''t. Tweaking add powers or adding readers are partial fixes; multifocal restores the intermediate gap. Monovision intermediate gap → go multifocal."}'),
  ('65634f19-59','{"options": ["7.89", "8.0", "7.76", "7.54"], "correct": 0, "explanation": "Ortho-K target corneal power = K minus (myopia + Jessen factor) = 45.50 - (2.00 + 0.75) = 42.75 D; base-curve radius = 337.5/42.75 = 7.89 mm. BC = 7.89 mm."}'),
  ('044c97ab-2b','{"options": ["Improved comfort", "Enhanced oxygen permeability", "Increased lens movement", "Superior visual acuity"], "correct": 3, "explanation": "Scleral lenses give patients with irregular corneas SUPERIOR VISUAL ACUITY — the rigid front surface plus tear reservoir creates a smooth refracting surface that neutralizes the corneal irregularity (better optics than soft lenses can manage). Comfort/oxygen are secondary; movement is minimal. Irregular cornea + scleral = best optics/VA."}'),
  ('72502a84-1q','{"options": ["To provide a cushioning effect", "To ensure proper lens movement", "To correct refractive errors", "To increase lens stability"], "correct": 2, "explanation": "The OPTICAL ZONE of a contact lens carries the refractive power that CORRECTS the refractive error (the central vision-correcting portion). Other zones handle fit/movement/stability; the optic zone is the optical correcting part. Optic zone = the ''prescription'' part of the lens."}'),
  ('d56ebff8-2o','{"options": ["Increase the base curve radius", "Steepen the base curve", "Check lens rotation", "Use a thicker lens design"], "correct": 2, "explanation": "Blurred vision with a soft TORIC lens → first CHECK LENS ROTATION (mislocated cylinder axis is the classic toric blur cause; assess and compensate with LARS — Left Add, Right Subtract). Changing base curve/thickness doesn''t fix an axis-rotation problem. Toric blur → verify rotation/axis first."}'),
  ('8f9d4d0b-1k','{"options": ["trifluridine", "idoxuridine", "vidarabine", "sorivudine"], "correct": 1, "explanation": "Idoxuridine (1962) was the first antiviral approved by the FDA. Trifluridine and vidarabine came later as herpes-keratitis agents; sorivudine is newer. First antiviral ever approved = idoxuridine."}'),
  ('c856ab23-1a','{"options": ["yellowish tooth discoloration", "epigastric discomfort", "aplastic anemia", "ototoxicity & nephrotoxicity"], "correct": 2, "explanation": "Chloramphenicol''s most feared/characteristic adverse effect is aplastic anemia (dose-independent bone marrow failure), plus gray baby syndrome in neonates. Tooth staining is tetracycline, ototoxicity/nephrotoxicity is aminoglycosides. Chloramphenicol = aplastic anemia."}'),
  ('09b17b3e-z','{"options": ["isoniazid", "rifampicin", "streptomycin", "ethambutol"], "correct": 2, "explanation": "Streptomycin is NOT a first-line oral anti-TB drug. The first-line four are isoniazid, rifampicin, ethambutol, and pyrazinamide (RIPE). Streptomycin is an injectable now grouped as second-line. RIPE = first line; streptomycin is the injectable exception."}'),
  ('592f13df-1q','{"options": ["chloramphenicol", "ofloxacin", "gentamycin", "erythromycin"], "correct": 2, "explanation": "Gentamicin, an aminoglycoside, classically causes nephrotoxicity and ototoxicity. Chloramphenicol gives aplastic anemia, erythromycin GI upset, ofloxacin tendon issues. Aminoglycosides (gentamicin) = kidney + ear toxicity."}'),
  ('0f062e7c-1s','{"options": ["riboflavin", "folic acid", "pyridoxine", "biotin"], "correct": 2, "explanation": "Pyridoxine (vitamin B6) is co-given with isoniazid to prevent the peripheral neuritis INH causes by depleting B6. Riboflavin is B2, folic acid is B9, biotin is B7. INH + B6 = no neuritis."}'),
  ('ddbce08b-1d','{"options": ["clofazimine", "rifampicin", "ethambutol", "amithiozone"], "correct": 0, "explanation": "Clofazimine is used for dapsone-resistant Mycobacterium leprae (and is part of multidrug leprosy therapy with rifampicin and dapsone). Resistant LEPROSY = clofazimine; resistant TB = rifampicin (Q9). Pair these two."}'),
  ('05e7f6b2-1j','{"options": ["clofazimine", "rifampicin", "ethambutol", "amithiozone"], "correct": 1, "explanation": "Rifampicin is the key drug for resistant Mycobacterium tuberculosis (and a cornerstone of all TB regimens). Clofazimine is for leprosy (Q8), ethambutol and amithiozone are weaker. Resistant TB = rifampicin."}'),
  ('f231ed1e-1w','{"options": ["clonidine 75mcg sublingual", "cefuroxime 500mg IV", "amoxicillin 125mg oral suspension", "paracetamol suppository"], "correct": 2, "explanation": "Only the ORAL route undergoes first-pass hepatic metabolism (drug absorbed from gut goes to the liver via the portal vein before reaching the circulation). The amoxicillin oral suspension is the oral one. Sublingual, IV, and rectal/suppository routes largely BYPASS the first pass. Oral = first pass; the rest dodge the liver."}'),
  ('6b97d0a3-1y','{"options": ["naproxen", "morphine", "methadone", "hydrocodone"], "correct": 0, "explanation": "Naproxen is an NSAID, not a narcotic (opioid) analgesic. Morphine, methadone, and hydrocodone are all opioids. NSAID = non-narcotic; the rest act on opioid receptors."}'),
  ('6a391ce7-14','{"options": ["diazepam", "heroin", "phenobarbital", "naloxone"], "correct": 0, "explanation": "Diazepam, a benzodiazepine, is the safer choice for ongoing anti-anxiety maintenance (wide therapeutic margin, reversible with flumazenil). Phenobarbital (a barbiturate) is more dangerous in overdose, heroin is an opioid of abuse, naloxone is an opioid antagonist. Benzodiazepine = safer than barbiturate."}'),
  ('c28f055f-2x','{"options": ["absorption", "elimination", "bioavailability", "biotransformation"], "correct": 2, "explanation": "Bioavailability is the fraction/percentage of an administered dose that reaches the systemic circulation unchanged. Absorption is uptake, elimination is removal, biotransformation is metabolism. IV bioavailability = 100% by definition."}'),
  ('b9cc34a0-1o','{"options": ["cytochrome P-450", "alanine transaminase", "acethylcholinesterase", "gamma glutamyl transferase"], "correct": 0, "explanation": "The cytochrome P-450 family of hepatic microsomal enzymes metabolizes most orally taken drugs. ALT and GGT are liver markers, not drug-metabolizing enzymes; acetylcholinesterase degrades ACh. Drug metabolism = CYP450."}'),
  ('c5087b0c-2e','{"options": ["ask the patient to look upward", "pinch the lower eyelids", "instill only 1 drop of the medication", "ask the patient to blink after instillation"], "correct": 3, "explanation": "You should ask the patient NOT to blink (blinking pumps the drop into the puncta and squeezes it out), so ''ask the patient to blink'' is the wrong step. Looking up, retracting the lower lid, and instilling a single drop are all correct. Blinking right after instillation defeats the drop."}'),
  ('8e39cdea-2w','{"options": ["prevent overflow of medication", "increase the contact time of the anesthesia", "prevent egress of the anesthesia at puncta lacrimalis", "enhances drug absorption"], "correct": 0, "explanation": "The conjunctival cul-de-sac holds only about one drop (roughly 30 microliters), so a single drop prevents overflow and wasteful, potentially systemic, excess. More drops simply spill over the lid. One drop = the sac is already full."}'),
  ('4a5a0937-u','{"options": ["mebendazole", "miconazole", "methisazole", "metronidazole"], "correct": 1, "explanation": "Miconazole is an antifungal (azole) for oral candidiasis (thrush). Mebendazole is for worms (Q20), metronidazole for amoeba (Q19), methisazole is antiviral. Azole = antifungal."}'),
  ('503e233e-o','{"options": ["mebendazole", "miconazole", "methisazole", "metronidazole"], "correct": 3, "explanation": "Metronidazole is the drug for amoebiasis (Entamoeba) and other anaerobes/protozoa. Mebendazole is anthelmintic, miconazole antifungal, methisazole antiviral. Amoeba = metronidazole."}'),
  ('804c5938-o','{"options": ["mebendazole", "miconazole", "methisazole", "metronidazole"], "correct": 0, "explanation": "Mebendazole is the anthelmintic for ascariasis (roundworm) and other intestinal worms. Miconazole is antifungal, metronidazole antiprotozoal, methisazole antiviral. Worms = mebendazole/albendazole."}'),
  ('6e95c805-2t','{"options": ["bactericidal", "narrow spectrum", "bacteriostatic", "broad spectrum"], "correct": 3, "explanation": "A broad-spectrum antibiotic inhibits or kills a wide variety of organisms (gram-positive and gram-negative). Narrow-spectrum hits a limited range; bactericidal vs bacteriostatic describes killing vs inhibiting, not range. Wide variety = broad spectrum."}'),
  ('26b28111-1g','{"options": ["chloramphenicol", "fluoroquinolone", "tetracycline", "erythromycin"], "correct": 0, "explanation": "Chloramphenicol is the classic antibiotic of choice for typhoid fever (Salmonella typhi). Fluoroquinolones and others are modern alternatives, but the traditional board answer is chloramphenicol. Typhoid = chloramphenicol (the boards favorite)."}'),
  ('30772d55-2j','{"options": ["gentamicin", "neomycin", "bacitracin", "polymyxin B"], "correct": 1, "explanation": "Neomycin is too nephrotoxic and ototoxic for systemic use, so it is given only topically or orally (for gut decontamination). Gentamicin is given systemically, while bacitracin and polymyxin B are not aminoglycosides. Neomycin = topical/oral only."}'),
  ('5ef5eb67-2b','{"options": ["yellowish tooth discoloration", "epigastric discomfort", "aplastic anemia", "ototoxicity & nephrotoxicity"], "correct": 3, "explanation": "Aminoglycosides characteristically cause ototoxicity and nephrotoxicity, which is why courses are kept short (under about 7 days) with level monitoring. Tooth staining is tetracycline, aplastic anemia is chloramphenicol. Aminoglycoside = ear + kidney damage."}'),
  ('ceb3d757-2z','{"options": ["yellowish tooth discoloration", "hypersensitivity reaction", "aplastic anemia", "ototoxicity & nephrotoxicity"], "correct": 0, "explanation": "Tetracycline chelates calcium and deposits in growing teeth/bone, causing permanent yellow tooth discoloration, so it is avoided in pregnancy, neonates, and children under 12. Aplastic anemia is chloramphenicol; ototoxicity is aminoglycosides. Tetracycline = stained teeth in the young."}'),
  ('c9dbc9f4-r','{"options": ["Professional Drug Enforcement Agent", "Police Dependent Enforcing Agency", "Philippine Drug Enforcement Agency", "Professional Drug Enforcement Agent"], "correct": 2, "explanation": "PDEA is the Philippine Drug Enforcement Agency, the lead anti-illegal-drug body. The other options are made-up titles (and a and d are duplicate distractors). PDEA = Philippine Drug Enforcement Agency."}'),
  ('3fe7ac03-12','{"options": ["sulfone or dapsone", "mebendazole", "itraconazole", "metronidazole"], "correct": 0, "explanation": "Leprosy (Hansen''s disease) is treated with sulfones, chiefly dapsone, the backbone of multidrug therapy. Mebendazole is anthelmintic, itraconazole antifungal, metronidazole antiprotozoal. Leprosy = dapsone (sulfone)."}'),
  ('5cac8104-1n','{"options": ["palliative drug", "prophylactic drug", "protective drug", "curative medication"], "correct": 0, "explanation": "Mefenamic acid for a headache from uncorrected refractive error only relieves the symptom (pain) without fixing the cause, so it is palliative. The actual fix is correcting the refractive error. Symptom relief only = palliative."}'),
  ('44f3f293-s','{"options": ["inosiplex", "amantadine", "methisoprinol", "acyclovir"], "correct": 3, "explanation": "Acyclovir is the drug of choice for varicella (chickenpox) and other herpes-family viruses. Amantadine is for influenza A; inosiplex/methisoprinol are immunomodulating antivirals. Varicella/herpes = acyclovir."}'),
  ('0336de50-11','{"options": ["optic neuritis", "cataract", "glaucoma", "uveitis"], "correct": 0, "explanation": "Chloramphenicol can cause optic (retrobulbar) neuritis with chronic use, leading to reduced vision and color defects. It does not classically cause cataract, glaucoma, or uveitis. Chloramphenicol eye toxicity = optic neuritis."}'),
  ('c9b4b041-1p','{"options": ["sulfone", "quinine", "chloroquine", "clafazimine"], "correct": 2, "explanation": "Uncomplicated Plasmodium ovale (and vivax) malaria is treated with chloroquine (with primaquine added to clear liver hypnozoites). Quinine is reserved for complicated/resistant falciparum (Q33). Non-falciparum, uncomplicated = chloroquine."}'),
  ('350d2507-1s','{"options": ["sulfone", "quinine", "chloroquine", "clafazimine"], "correct": 1, "explanation": "Complicated or severe Plasmodium falciparum (often chloroquine-resistant) is treated with quinine (or IV artesunate). Chloroquine works for sensitive non-falciparum species (Q32). Severe falciparum = quinine."}'),
  ('61babc39-g','{"options": ["before meals", "when needed", "at bed time", "by mouth"], "correct": 0, "explanation": "Ante cibus (a.c.) means before meals. Hora somni is at bedtime (Q36), pro re nata is when needed (Q37), per os is by mouth (Q38). a.c. = before meals."}'),
  ('0c8ed21b-g','{"options": ["before meals", "when needed", "at bed time", "by mouth"], "correct": 2, "explanation": "Hora somni (h.s.) means at bedtime. Ante cibus is before meals, pro re nata is as needed, per os is by mouth. h.s. = at bedtime."}'),
  ('bab1d7ef-h','{"options": ["as desired", "by mouth", "when needed", "at night"], "correct": 2, "explanation": "Pro re nata (PRN) means when needed/as the occasion arises. Per os is by mouth, nocte is at night. PRN = as needed."}'),
  ('fb77918c-c','{"options": ["as desired", "by mouth", "when needed", "at night"], "correct": 1, "explanation": "Per os (PO) means by mouth/orally. Pro re nata is as needed, nocte is at night. PO = by mouth."}'),
  ('95ad02fe-b','{"options": ["as desired", "by mouth", "when needed", "at night"], "correct": 3, "explanation": "Nocte means at night. As desired is ad libitum, by mouth is per os, when needed is PRN. Nocte = at night."}'),
  ('a30f2de0-19','{"options": ["take care of users of prohibited drugs", "approved newly discovered drugs", "monitor existing drugs on the market", "regulate and control prohibited drugs"], "correct": 0, "explanation": "Taking care of (rehabilitating) users of prohibited drugs is NOT an FDA function; that falls to DOH/rehabilitation programs and DDB/PDEA. The FDA approves new drugs, monitors marketed drugs, and regulates/controls prohibited drugs. FDA regulates products, not addicts."}'),
  ('0e239647-2p','{"options": ["doctrine of respond superior", "doctrine of informed consent", "doctrine of liability", "minors and incompetent"], "correct": 1, "explanation": "The doctrine of informed consent requires the prescriber to educate the patient about the medication before its use. Respondeat superior is employer liability, the others are unrelated. Educate before treatment = informed consent."}'),
  ('6ec02903-1t','{"options": ["frequency of giving the medication", "route of giving the medication", "duration of taking the medication", "dosage/concentration of the medication"], "correct": 3, "explanation": "The transcription (signatura/directions) carries frequency, route, and duration of the medication, but NOT the dosage/concentration, which belongs to the inscription. So dosage/concentration should not appear in the transcription. Signa = how to take it, not the strength."}'),
  ('560d87aa-1o','{"options": ["brand name of medication", "generic name", "dosage of the drug", "preparation of the drug"], "correct": 0, "explanation": "The inscription holds the generic drug name, dose, and preparation, but the brand name should not appear there (generic prescribing is required). So brand name is the one that does not belong. Inscription = generic name + strength + form."}'),
  ('70d61a88-23','{"options": ["regulated medication has expiration", "prescriber will remember when the patient took the medication", "important for senior citizen acquiring 20% discount", "all of the above"], "correct": 3, "explanation": "All of the listed reasons apply: regulated drugs have expiry limits on the order, the date documents when it was issued, and it matters for the senior-citizen discount. So ''all of the above'' is correct. The date anchors the prescription''s validity."}'),
  ('e24936ca-2e','{"options": ["doctrine of respond superior", "doctrine of informed consent", "doctrine of liability", "minors and incompetent"], "correct": 3, "explanation": "Children with ADD are minors, so educating their parents falls under the doctrine of minors and incompetent (consent given through the guardian). Informed consent (Q41) covers competent adult patients themselves. Minor patient = consent via guardian."}'),
  ('f9e0cc4e-e','{"options": ["superscription", "subscription", "inscription", "transcription"], "correct": 2, "explanation": "The inscription is the body of the prescription order, listing the drug and its strength. Superscription is the Rx heading, subscription the dispensing directions, transcription the patient instructions. Body = inscription."}'),
  ('9d477210-1c','{"options": ["superscription", "subscription", "inscription", "transcription"], "correct": 3, "explanation": "The transcription (signatura, ''Sig'') comes from signa, which means ''write/label thou'', i.e. ''you write'' the directions for the patient. Superscription means ''take'' (recipe). ''Write/label'' = signatura = transcription."}'),
  ('79d13099-s','{"options": ["Philippines Tax Reform", "Professional Tax Regulation", "Professional Tax Receipt", "Pharmacy Tariff Receipt"], "correct": 2, "explanation": "PTR is the Professional Tax Receipt, proof a professional paid the local professional tax. The other expansions are made up. PTR = Professional Tax Receipt."}'),
  ('3885c486-1f','{"options": ["cyclopentolate", "fluorescein", "pilocarpine", "tropicamide"], "correct": 2, "explanation": "Pilocarpine is NOT a diagnostic pharmaceutical agent (DPA); it is a therapeutic agent (a miotic used to treat glaucoma). Fluorescein, tropicamide, and cyclopentolate are diagnostic agents. DPA = diagnostic; pilocarpine treats, so it is the exception."}'),
  ('6fec6746-2m','{"options": ["block the internal opening of sodium channels", "incorporate and becomes part of cell membrane", "block the external opening of sodium channels", "compete with calcium guarding Na+ channels"], "correct": 1, "explanation": "''Incorporating into and becoming part of the cell membrane'' is the NON-specific membrane-expansion theory, not the specific receptor (sodium-channel) mechanism. Proparacaine''s specific action is blocking the sodium channel (internal/external opening) and competing with calcium. Receptor theory = Na channel block; membrane expansion is the non-specific idea."}'),
  ('1f6327a6-v','{"options": ["naltrexone", "naloxone", "morphine", "diazepam"], "correct": 0, "explanation": "Naltrexone is used for maintenance treatment of opioid (and alcohol) addiction. Naloxone reverses acute overdose, morphine is the opioid itself, diazepam is a benzodiazepine. Addiction maintenance = naltrexone; acute overdose = naloxone."}'),
  ('68e0acb7-1c','{"options": ["proparacaine", "cocaine", "tetracaine", "prilocaine"], "correct": 3, "explanation": "Prilocaine is an AMIDE local anesthetic, so it is the exception. Proparacaine, cocaine, and tetracaine are ester anesthetics. Tip: amides have two letter i''s in the name (pr-i-loca-i-ne, l-i-doca-i-ne); esters do not."}'),
  ('8b0c40c6-1a','{"options": ["proparacaine", "cocaine", "tetracaine", "prilocaine"], "correct": 1, "explanation": "Cocaine is the only naturally occurring local anesthetic (an alkaloid from the coca plant); all the others are synthetic. Proparacaine, tetracaine, and prilocaine are man-made. Natural anesthetic = cocaine."}'),
  ('285038c2-r','{"options": ["hora somni", "debus alternis", "SOS", "Stat"], "correct": 3, "explanation": "Stat (statim) is the Latin for urgent/immediately. SOS (si opus sit) means if needed, hora somni is at bedtime, de die in diem is day to day. Urgent = stat."}'),
  ('62ebfdce-o','{"options": ["help", "apply", "drop", "every"], "correct": 2, "explanation": "Gutta (gtt) means drop. So one drop is one gutta and gtts are drops. Gutta = drop."}'),
  ('661c1013-11','{"options": ["1 ml", "15 ml", "5 ml", "10 ml"], "correct": 1, "explanation": "One tablespoon equals 15 mL. A teaspoon is 5 mL and a dessertspoon about 10 mL. Tablespoon = 15 mL; teaspoon = 5 mL."}'),
  ('155a3a54-1r','{"options": ["monoamine oxidase", "cathecol-o-methyl transferase", "acethylcholinesterase", "A & B only"], "correct": 3, "explanation": "ADRENERGIC (noradrenaline) neurotransmitter is degraded by MONOAMINE OXIDASE (MAO) and CATECHOL-O-METHYLTRANSFERASE (COMT) — so A & B. Acetylcholinesterase degrades ACh (cholinergic, Q82). Adrenergic enzymes = MAO + COMT."}'),
  ('e888c647-1s','{"options": ["monoamine oxidase", "cathecol-o-methyl transferase", "acethylcholinesterase", "A & B only"], "correct": 2, "explanation": "CHOLINERGIC neurotransmitter (acetylcholine) is degraded by ACETYLCHOLINESTERASE (AChE) in the synaptic cleft. MAO/COMT handle catecholamines (Q81). ACh breakdown = AChE. Cross-link: AChE inhibitors (physostigmine) prolong ACh."}'),
  ('b5b4b3ae-2e','{"options": ["mandelic acid", "adrenalin", "acetate + choline", "amphetamine"], "correct": 0, "explanation": "Norepinephrine acted on by MAO and COMT yields vanillylmandelic acid (mandelic acid), the urinary metabolite measured in pheochromocytoma. Adrenalin is the parent amine, acetate + choline are ACh metabolites. Adrenergic metabolite = (vanillyl)mandelic acid."}'),
  ('f2fb74c6-2b','{"options": ["mandelic acid", "adrenalin", "acetate + choline", "amphetamine"], "correct": 2, "explanation": "Acetylcholine split by acetylcholinesterase yields acetate plus choline (the choline is recycled). Mandelic acid is the adrenergic metabolite. ACh breakdown = acetate + choline."}'),
  ('83239a1d-1q','{"options": ["ciliary spasm", "cataract formation", "allergy", "leukoma"], "correct": 0, "explanation": "Pilocarpine, a muscarinic agonist, stimulates the ciliary muscle and commonly causes ciliary spasm with accommodative myopia and brow ache. It does not cause cataract, allergy, or leukoma as its accommodative effect. Pilocarpine = ciliary spasm/accommodative cramp."}'),
  ('91aff493-2g','{"options": ["physostigmine", "demecarium", "echothiopate", "pyridostigmine"], "correct": 3, "explanation": "Pyridostigmine (an indirect cholinergic) is used for myasthenia gravis, NOT glaucoma, so it is the exception. Physostigmine, demecarium, and echothiophate are anticholinesterases used as anti-glaucoma miotics. Pyridostigmine = myasthenia, not the eye."}'),
  ('bd572c52-10','{"options": ["dilate", "constrict", "no effect", "all of the above"], "correct": 1, "explanation": "Physostigmine, an anticholinesterase, raises ACh and constricts the pupil (miosis). It does not dilate. Anticholinesterase at the iris = miosis."}'),
  ('aff6bc68-w','{"options": ["dilate", "constrict", "no effect", "all of the above"], "correct": 1, "explanation": "Carbachol, a cholinergic agonist, constricts the pupil (miosis), which is why it is used intraoperatively and for glaucoma. Cholinergic = miosis."}'),
  ('ad2fd28f-24','{"options": ["thimerosal", "hyaluronidase", "benzalkonium chloride", "epinephrine"], "correct": 2, "explanation": "Benzalkonium chloride (a surfactant) is added so that topical carbachol, which penetrates the cornea poorly, is better absorbed. Thimerosal and EDTA are preservative/chelator; epinephrine is unrelated here. BAK = penetration enhancer for carbachol."}'),
  ('72033128-i','{"options": ["adrenomimetic agent", "adrenolytic agent", "direct-acting cholinomimetic agent", "indirect-acting cholinomimetic agent"], "correct": 2, "explanation": "CARBACHOL is a DIRECT-ACTING cholinomimetic (binds and activates muscarinic — and nicotinic — receptors directly; resistant to AChE). Physostigmine is indirect (Q98). Carbachol = direct cholinergic agonist."}'),
  ('cd7bf21d-10','{"options": ["dilate", "constrict", "no effect", "both A & B"], "correct": 1, "explanation": "NERVE GASES (organophosphates) are irreversible ACETYLCHOLINESTERASE inhibitors → ACh accumulates → muscarinic overstimulation → pupils CONSTRICT (miosis, the classic ''pinpoint pupils'' of cholinergic crisis). Plus the SLUDGE/DUMBELS toxidrome. Antidote = atropine (Q2). OP poisoning = miosis."}'),
  ('20f47dc1-1h','{"options": ["phenylephrine", "lidocaine", "atropine", "activated charcoal"], "correct": 2, "explanation": "ATROPINE (antimuscarinic) is the antidote for cholinesterase-inhibitor (physostigmine, organophosphate insecticide) poisoning — it blocks the excess-ACh muscarinic effects (pralidoxime reactivates the enzyme). Activated charcoal is general GI decontamination. Cholinergic crisis → atropine."}'),
  ('24e6f1af-10','{"options": ["neostigmine", "physostigmine", "edrophonium", "ambenonium"], "correct": 0, "explanation": "Neostigmine (or pyridostigmine) is the drug of choice for ongoing treatment of myasthenia gravis (longer acting, oral). Edrophonium is too short-acting for treatment and is used to diagnose (Q71). Treat MG = neostigmine; diagnose = edrophonium."}'),
  ('d04c37ba-1d','{"options": ["neostigmine", "physostigmine", "edrophonium", "ambenonium"], "correct": 2, "explanation": "Edrophonium (the Tensilon test) is the short-acting anticholinesterase used to confirm myasthenia gravis (rapid, transient improvement of weakness). Neostigmine and the others are for treatment. Diagnose MG = edrophonium."}'),
  ('d2e3c831-1t','{"options": ["30 minutes", "1.5 hours", "4-6 hours", "none of the above"], "correct": 2, "explanation": "Tropicamide''s mydriasis reverses in about 4 to 6 hours (it is a short-acting cycloplegic/mydriatic). That short recovery is why it is the routine dilating drop. Tropicamide = quick, hours not days."}'),
  ('ea935fca-1f','{"options": ["yohimbine", "metoprolol", "phentolamine", "cyclopentolate"], "correct": 0, "explanation": "Yohimbine is the alpha-2 adrenergic antagonist. Phentolamine blocks alpha-1 and alpha-2 nonselectively, metoprolol is a beta-blocker, cyclopentolate is antimuscarinic. Selective alpha-2 antagonist = yohimbine."}'),
  ('081287b0-15','{"options": ["contract resulting to bronchoconstriction", "relax resulting to bronchodilation", "no effect", "all of the above"], "correct": 0, "explanation": "Acetylcholine acts on muscarinic (M3) receptors of bronchial smooth muscle to contract it, causing bronchoconstriction. This is why anticholinergics (ipratropium) help asthma. ACh in the airway = bronchoconstriction."}'),
  ('337e508b-15','{"options": ["contract resulting to bronchoconstriction", "relax resulting to bronchodilation", "no effect", "all of the above"], "correct": 0, "explanation": "Beta-blockers block the bronchodilating beta-2 receptors, leaving airway smooth muscle to constrict (bronchoconstriction). This is why even topical timolol can trigger bronchospasm in asthmatics. Beta-blockade = bronchoconstriction risk."}'),
  ('8a0518db-1j','{"options": ["intravitreal injection", "topical", "posterior retrobulbar injection", "intracameral injection"], "correct": 3, "explanation": "Trypan blue is delivered by intracameral injection (into the anterior chamber) to stain the capsule during phacoemulsification. Intravitreal and retrobulbar routes are for other purposes. Capsule staining = intracameral."}'),
  ('e912b288-1j','{"options": ["chelating agent", "wetting agent", "preservative", "buffering agent"], "correct": 3, "explanation": "Boric acid in Fluress acts as a buffering agent, holding the solution at a stable pH. EDTA is the chelator, thimerosal the preservative, surfactants the wetting agents. Boric acid = buffer (Q78 to Q80 complete the set)."}'),
  ('59896426-11','{"options": ["chelating agent", "wetting agent", "preservative", "buffering agent"], "correct": 0, "explanation": "EDTA is a chelating agent; combined with thimerosal it binds metal ions and boosts the antimicrobial action. Boric acid buffers, thimerosal preserves, surfactants wet. EDTA = chelator."}'),
  ('6f25bc56-1m','{"options": ["chelating agent", "wetting agent", "preservative", "buffering agent"], "correct": 2, "explanation": "Thimerosal is added to contact-lens solutions as a preservative (antimicrobial). EDTA chelates, boric acid buffers, surfactants wet. Thimerosal = preservative."}'),
  ('d4e2553e-1c','{"options": ["chelating agent", "wetting agent", "preservative", "buffering agent"], "correct": 1, "explanation": "Benzalkonium chloride is a surfactant added to carbachol as a wetting/penetration-enhancing agent (it lowers surface tension to improve corneal uptake, as in Q66). It is also a preservative, but here its role with carbachol is the surfactant/wetting action. BAK with carbachol = wetting/penetration enhancer."}'),
  ('cd00c740-2s','{"options": ["Fluorescein dye", "Lissamine green dye", "Trypan blue dye", "Indocyanine green dye"], "correct": 3, "explanation": "Indocyanine green (ICG) angiography shows both retinal and especially CHOROIDAL vessels (its near-infrared fluorescence penetrates the RPE). Fluorescein mainly images the retinal circulation. Choroid + retina = ICG; retina only = fluorescein."}'),
  ('aa9f4c28-15','{"options": ["Fluorescein dye", "Lissamine green dye", "Trypan blue dye", "Indocyanine green dye"], "correct": 2, "explanation": "Trypan blue is the dye commonly used in phacoemulsification (capsular staining for the capsulorhexis, especially in white/mature cataracts). Fluorescein and ICG are for the ocular surface and angiography. Phaco capsule dye = trypan blue."}'),
  ('e36e6512-1j','{"options": ["stains the anterior lens capsule", "stains the anterior lens capsule", "stains the corneal endothelium", "stains the lens epithelium"], "correct": 0, "explanation": "Trypan blue stains the ANTERIOR LENS CAPSULE so the surgeon can see and tear the capsulorhexis in a poorly visualized (white) cataract. It is not for endothelium or lens epithelium here. Trypan blue in phaco = anterior capsule stain."}'),
  ('0b6d4409-22','{"options": ["fitting of hard contact lens", "TBUT", "angiography", "Jones test I"], "correct": 2, "explanation": "Angiography is the exception: it uses INJECTED (IV) fluorescein, not the fluorescein STRIP. The strip is used for hard contact-lens fitting, TBUT, and Jones dye testing (all surface applications). Strip = surface tests; angiography = IV dye."}'),
  ('0c9047bf-17','{"options": ["determine the patency of lacrimal passage", "determine if there is mucin deficiency that causes dry eye syndrome", "determine pattern of retinal vessels for any obstruction or hemorrhage", "measures intraocular pressure"], "correct": 1, "explanation": "In TBUT, fluorescein reveals tear-film stability, detecting mucin deficiency that causes dry eye (rapid break-up). Patency testing, angiography, and IOP are other uses (Q88, Q87, Q89). TBUT = tear quality/mucin."}'),
  ('f0cf3bf5-1i','{"options": ["determine the patency of lacrimal passage", "determine if there is mucin deficiency that causes dry eye syndrome", "determine pattern of retinal vessels for any obstruction or hemorrhage", "measures intraocular pressure"], "correct": 2, "explanation": "In angiography, fluorescein shows the pattern of retinal vessels and any obstruction or hemorrhage/leakage. Patency, mucin, and IOP are separate indications. Angiography = retinal vascular pattern."}'),
  ('635e9bfc-1p','{"options": ["determine the patency of lacrimal passage", "determine if there is mucin deficiency that causes dry eye syndrome", "determine pattern of retinal vessels for any obstruction or hemorrhage", "measures intraocular pressure"], "correct": 0, "explanation": "The Fluorescein Dye (Jones I) Test checks the patency of the lacrimal drainage passage (does dye reach the nose). TBUT checks mucin, angiography checks vessels, applanation checks IOP. Dye Test I = is the tear drain open."}'),
  ('77b94951-1r','{"options": ["determine the patency of lacrimal passage", "determine if there is mucin deficiency that causes dry eye syndrome", "determine pattern of retinal vessels for any obstruction or hemorrhage", "measures intraocular pressure"], "correct": 3, "explanation": "With an applanation tonometer, fluorescein highlights the tear-film mires so the examiner can measure intraocular pressure. The other choices are different fluorescein uses. Applanation + fluorescein = measure IOP."}'),
  ('d76f7267-1t','{"options": ["determine aqueous leakage post- intraocular operations", "determine epithelial breaks wherein dye is located at A.H chamber", "shows corneal dendritic pattern on cornea", "shows fishnet Mosaic pattern of tear film"], "correct": 0, "explanation": "The Seidel test uses fluorescein to detect aqueous humor leakage after intraocular surgery or perforation (a stream of dilute green appears where aqueous washes the dye). It is not for dendrites or tear mosaic. Seidel = aqueous leak."}'),
  ('83c0f706-16','{"options": ["determine aqueous leakage post- intraocular operations", "determine epithelial breaks wherein dye is located at A.H chamber", "shows corneal dendritic pattern on cornea", "shows fishnet Mosaic pattern of tear film"], "correct": 2, "explanation": "In herpes simplex keratitis, fluorescein stains the classic branching corneal DENDRITE (dendritic ulcer). Aqueous leak is Seidel, mosaic is Fischer-Schweizer. Herpes cornea + fluorescein = dendrite."}'),
  ('a144989c-3y','{"options": ["Seidel test", "Fisher-Schweizer’s corneal mosaic", "Quenching phenomenon", "Pseudoflare"], "correct": 2, "explanation": "Quenching is the loss of fluorescence/luminosity when fluorescein moves outside its optimal range, including very high pH (over about 10). Seidel and the mosaic are unrelated tests, pseudoflare is an artifact. Out-of-range fluorescein = quenching (also occurs at high concentration, Q93)."}'),
  ('38a41c87-3x','{"options": ["Seidel test", "Fisher-Schweizer’s corneal mosaic", "Quenching phenomenon", "Pseudoflare"], "correct": 2, "explanation": "Quenching also occurs at high concentration (above roughly 0.01), where crowded molecules self-absorb and fluorescence drops. So both excess concentration and extreme pH quench fluorescein. Too concentrated or wrong pH = quenching."}'),
  ('191e3f06-2v','{"options": ["has allergy to iodofluorescein", "need to visualized choroidal neovascularization", "patient cannot afford ICG since it is expensive", "can still visualize retinal and choroidal vessels even with media opacities"], "correct": 2, "explanation": "Cost is NOT a clinical indication; in fact ICG is more expensive, so ''patient cannot afford ICG'' is the exception. Real indications are iodofluorescein allergy, the need to see choroidal neovascularization, and imaging through media opacities. ICG is chosen for its imaging advantages, not to save money."}'),
  ('52123020-35','{"options": ["indocyanine green", "methylene blue", "trypan blue", "lissamine green"], "correct": 3, "explanation": "Lissamine green stains devitalized surface cells and is used to assess lid-wiper epitheliopathy under the upper lid (as seen with snug RGP wear in high myopic astigmats). Trypan blue and ICG are intraocular/angiographic; methylene blue is not standard for this. Lid wiper = lissamine green."}'),
  ('5683687e-t','{"options": ["red", "orange", "green", "turquoise"], "correct": 1, "explanation": "Dorzolamide, a carbonic anhydrase inhibitor, has an ORANGE cap in the glaucoma color code. Orange = CAIs."}'),
  ('3abe866a-s','{"options": ["red", "orange", "green", "turquoise"], "correct": 3, "explanation": "Travoprost, a prostaglandin analog, has a TURQUOISE (teal) cap. Turquoise = prostaglandin analogs (latanoprost, travoprost, bimatoprost)."}'),
  ('e71f6418-t','{"options": ["red", "orange", "green", "turquoise"], "correct": 2, "explanation": "Pilocarpine, a miotic/cholinergic, carries a GREEN cap in the glaucoma color code. Green = miotics/cholinergics."}'),
  ('f8071ac6-10','{"options": ["yellow", "orange", "blue", "brown"], "correct": 3, "explanation": "Topical antibiotics/anti-infectives use a TAN/BROWN cap, outside the glaucoma color scheme. The glaucoma codes (yellow/blue beta-blockers, orange CAIs, teal prostaglandins, purple alpha-agonists, green miotics) do not cover antibiotics. Anti-infective = tan/brown."}'),
  ('50f7646d-2b','{"options": ["Cosmetic device", "Medical device", "Management device", "Health-related device"], "correct": 1, "explanation": "The FDA classifies all contact lenses, including plano cosmetic/colored lenses, as MEDICAL DEVICES, not mere cosmetics, because they sit on the cornea and carry infection/hypoxia risk. That is why they require a prescription and dispensing oversight. Colored CL = medical device."}'),
  ('f881d36a-v','{"options": ["3-year regulatory fee paid to the PRC in the form of annual registration fee", "Annual regulatory fee paid to the national government in the form of tax", "Annual regulatory fee paid to the local government in the form of tax", "A quarterly fee paid within 25 days after the end of each taxable quarter"], "correct": 2, "explanation": "The Professional Tax Receipt (PTR) is an ANNUAL professional tax paid to the LOCAL government (city/municipal treasurer) by a practicing professional. It is not a PRC fee and not a quarterly national tax. PTR = yearly local professional tax."}'),
  ('c9e24416-2a','{"options": ["Non-VAT registered business; percentage tax of 12%", "Non-VAT registered business; percentage tax of 3%", "VAT registered business; percentage tax of 20%", "VAT registered business; percentage tax of 12%"], "correct": 1, "explanation": "Annual sales of P2.5M fall below the P3,000,000 VAT threshold, so the business is NON-VAT registered and pays the 3% percentage tax (Sec 116, NIRC). VAT would apply only above P3M. Under 3M = non-VAT, 3% percentage tax."}'),
  ('6c49ed64-5l','{"options": ["P 503.67", "P 845.45", "P 504.67", "P 839.45"], "correct": 3, "explanation": "Rental income is subject to a 5% creditable (expanded) withholding tax. P16,789 x 5% = P839.45. The other figures use wrong rates. Rental EWT = 5% of the rent."}'),
  ('13584e41-31','{"options": ["P 900", "P 840", "P 905", "P 755"], "correct": 2, "explanation": "Individual community tax (cedula) = basic P5 plus P1 for every P1,000 of gross annual income. At P75,000/month the annual income is P900,000, so P900 + P5 = P905. Cedula = P5 basic + P1 per P1,000 income."}'),
  ('697432df-3m','{"options": ["The availability of public transportation options", "The location of nearby coffee shops", "The placement of examination rooms and waiting areas", "The number of parking spaces available"], "correct": 2, "explanation": "For clinic layout, the clinically important factor is the placement of examination rooms and waiting areas (work flow, the 6-meter test lane, patient comfort/privacy). Transport, coffee shops, and parking are peripheral. Layout priority = exam rooms and patient flow."}'),
  ('c60d8f98-3b','{"options": ["Bureau of Internal Revenue (BIR)", "Department of Trade and Industry (DTI)", "Securities and Exchange Commission (SEC)", "National Economic and Development Authority (NEDA"], "correct": 1, "explanation": "A sole proprietorship registers its business name with the Department of Trade and Industry (DTI). The SEC handles corporations/partnerships; the BIR handles tax registration. Sole proprietor business name = DTI."}'),
  ('0a6dcc71-2i','{"options": ["Department of Trade and Industry (DTI)", "Bureau of Internal Revenue (BIR)", "Food and Drug Administration (FDA)", "Department of Labor and Employment (DOLE)"], "correct": 2, "explanation": "New optical management agents and ophthalmic drops must be approved by the Food and Drug Administration (FDA), which regulates health products. DTI/BIR/DOLE do not approve drugs. Drugs and devices = FDA."}'),
  ('9cbb0685-4a','{"options": ["Certificate of Zoning Compliance", "Sanitary Permit", "Proof of Professional Regulation Commission (PRC) license", "Business Plan with Risk and Management"], "correct": 1, "explanation": "For a Barangay Clearance, a Sanitary Permit demonstrates compliance with local health and safety/sanitation standards. Zoning compliance, the PRC license, and a business plan address other requirements. Health/safety compliance = sanitary permit."}'),
  ('5a50880d-32','{"options": ["Drilling machine", "Lens groover", "Frame warmer", "Frame display"], "correct": 1, "explanation": "Semi-rim (nylon supra/nylor) frames hold the lens with a nylon cord seated in a groove, so the lab needs a lens GROOVER to cut that channel. A driller is for rimless, a frame warmer adjusts plastic. Nylon supra = lens groover."}'),
  ('5be87a3e-2a','{"options": ["Recommendations of the frame supplier", "Demographics of the practice population", "Location of the practice", "Practitioner’s choice of frames"], "correct": 1, "explanation": "Frame inventory should be dictated by the demographics of the practice population (ages, faces, budgets, fashion needs of your patients). Supplier or practitioner preference and location are secondary. Stock what your patients are, not what you like."}'),
  ('e1c57191-1o','{"options": ["Overseas Filipino Workers receiving income from sources outside the Philippines", "Resident citizens receiving income from sources within or outside the Philippines", "Non-resident citizens receiving income from the sources within the Philippines", "Aliens, whether residents or not, receiving income from the sources within the Philippines"], "correct": 0, "explanation": "An Overseas Filipino Worker''s income from sources OUTSIDE the Philippines is exempt, so OFWs are NOT required to file an ITR on that foreign income. Resident citizens are taxed worldwide; non-residents and aliens are taxed on Philippine-source income. OFW foreign income = not taxed/filed here."}'),
  ('38dfef56-1y','{"options": ["P500.00", "P5.00", "P5,000.00", "P550.00"], "correct": 0, "explanation": "A corporation''s basic community tax is P500 (versus only P5 basic for an individual). The additional tax scales with receipts/property up to the cap. Corporate cedula basic = P500."}'),
  ('c8971d41-3l','{"options": ["Barangay Clearance", "Tax Identification Number", "Business Permit", "Environmental Compliance Certificate"], "correct": 1, "explanation": "Before operating, a sole proprietor must obtain a Tax Identification Number (and Certificate of Registration) from the BIR. The barangay clearance and business permit come from the LGU. BIR first step = TIN/registration."}'),
  ('d5f0b7e3-2v','{"options": ["File a single local business tax return for all locations", "File separate local business tax returns for each location", "Pay a consolidated local business tax for all locations", "Pay the local business tax only for the main office location"], "correct": 1, "explanation": "With multiple locations, the optometrist files SEPARATE local business tax returns for each LGU where a branch operates (local taxes are paid per jurisdiction). Local tax is collected where each branch sits, so file per location."}'),
  ('82409504-73','{"options": ["General Manager", "Qualified Person", "Owner", "Professional Manager"], "correct": 1, "explanation": "Under FDA Circular 2021-0021, the full-time employee with technical competence in the establishment''s health-product activities is the ''Qualified Person''. The others are generic titles. Technically competent FDA contact = Qualified Person."}'),
  ('1afa455f-5f','{"options": ["Proof of Business Name Registration", "Risk Management Plan", "Standard Operating Procedure", "Marketing and Promotion Plan"], "correct": 3, "explanation": "During an FDA spot inspection the Marketing and Promotion Plan is NOT a required document; inspectors verify the business-name registration, risk management plan, and standard operating procedures. Marketing material is not part of compliance verification."}'),
  ('deb0abfe-29','{"options": ["Expiration – near expiry should be in front", "Price – cheaper in front", "Brand – famous brand in front", "Box size – the smaller boxes in front"], "correct": 0, "explanation": "Contact lens solutions (and any dated stock) are arranged by EXPIRATION with the near-expiry items in front, so they sell first (first-in, first-out). Price, brand, and box size do not drive shelf order for dated goods. Dated stock = FIFO, soonest expiry up front."}'),
  ('09540625-15','{"options": ["To fund local and national government projects.", "To raise revenue from the importation of illegal goods.", "To provide direct financial assistance to low-income individuals.", "To impose a tax on specific goods and services, typically those considered non-essential or harmful."], "correct": 3, "explanation": "Excise tax is imposed on specific goods/services, typically non-essential or harmful ones (so-called sin products like tobacco, alcohol, sweetened drinks). It is not direct aid or a tax on illegal goods. Excise = tax on specific/sin goods."}'),
  ('8a5ec2c4-1j','{"options": ["Last day of January", "Last day of February", "Day of registration of the permit", "Date of birth of the Mayor"], "correct": 0, "explanation": "The mayor''s/business permit is renewed and paid by the last day of January each year (with a January 20 deadline for some LGUs to avoid penalty). Business permit deadline = end of January."}'),
  ('5daf50e8-3m','{"options": ["10 years", "3 years", "5 years", "15 years"], "correct": 2, "explanation": "A DTI Business Name Registration is valid and renewable every 5 years. Business name validity = 5 years."}'),
  ('8f67edc3-1f','{"options": ["to reduce discomfort,", "reduce disability in society", "to promote quality of life", "to develop and implementing policies"], "correct": 3, "explanation": "Developing and implementing policies is a STRATEGY/means, not a stated GOAL of public health. The goals are to reduce discomfort, reduce disability, and promote quality of life (and prolong life). Policy-making is how, not the goal itself."}'),
  ('a23b7e8f-25','{"options": ["Epidemic", "Endemic", "Pandemic"], "correct": 2, "explanation": "The WHO declared COVID-19 a PANDEMIC (worldwide spread across countries/continents) in March 2020. An epidemic is regional; endemic is constant baseline presence. Worldwide = pandemic."}'),
  ('51c7f93c-1v','{"options": ["Macular degeneration", "Diabetic retinopathy", "Cataract", "Glaucoma"], "correct": 2, "explanation": "Cataract is the leading cause of preventable (treatable) blindness in the Philippines, reversible with surgery. Refractive error causes more visual impairment but cataract leads in blindness. PH preventable blindness = cataract."}'),
  ('12481e77-1s','{"options": ["uncorrected refractive error", "cataract", "myopia", "amblyopia"], "correct": 0, "explanation": "Uncorrected refractive error is the most common cause of visual impairment in the Philippines (and worldwide), easily fixed with glasses. Cataract leads in blindness, not overall impairment. Most common impairment = uncorrected refractive error."}'),
  ('48c9c72c-24','{"options": ["20/200 or worse and a visual field of 20 degrees or less in the better eye", "20/100 or worse and a visual field of 20 degrees or less in the better eye", "20/70 or worse and a visual field of 20 degrees or less in the better eye", "20/50 or worse and a visual field of 20 degrees or less in the better eye"], "correct": 0, "explanation": "Legal blindness/PWD visual criterion is best-corrected acuity of 20/200 or worse, or a visual field of 20 degrees or less, in the BETTER eye. The other acuity cutoffs are too lenient. PWD/legal blindness = 20/200 or VF <=20 degrees in the better eye."}'),
  ('80655de3-3h','{"options": ["primary", "secondary", "tertiary"], "correct": 0, "explanation": "Measuring visual acuity and treating simple, minor eye conditions is PRIMARY optometric care (basic, first-contact services). Cataract/glaucoma management is higher level. Basic VA and minor care = primary."}'),
  ('161d1b08-3r','{"options": ["primary", "secondary", "tertiary"], "correct": 2, "explanation": "Managing conditions like cataract and glaucoma is TERTIARY care (specialized/complex management, often surgical or co-managed). Simple care is primary; early detection/treatment is secondary. Complex disease management = tertiary."}'),
  ('3de98b19-2w','{"options": ["endemic", "pandemic", "epidemic"], "correct": 2, "explanation": "An EPIDEMIC is the sudden, rapid spread of an infectious disease through a region or group. A pandemic is global; endemic is steady baseline. Sudden regional outbreak = epidemic."}'),
  ('56aec74d-1s','{"options": ["Neutralizing the chemical with an alkali", "Cold compresses", "Ocular lubricants", "Copious irrigation with water"], "correct": 3, "explanation": "A chemical splash is treated immediately with COPIOUS irrigation using water/saline for many minutes. You never neutralize with the opposite agent (that worsens injury); lubricants/cold compresses come later. Chemical burn = irrigate, irrigate, irrigate."}'),
  ('d4336ee0-19','{"options": ["Physical", "Psychosocial", "Chemical", "biological"], "correct": 0, "explanation": "A physical stressor (noise, heat, radiation, trauma) is one that puts direct strain on the body. Psychosocial, chemical, and biological are other stressor categories. Bodily-strain stressor = physical."}'),
  ('d863d366-67','{"options": ["Sports goggles with CR-29 and strap", "Sports goggles with polycarbonate lens", "Sports goggles with strap and polycarbonate lens", "Plastic frame with polycarbonate lens"], "correct": 2, "explanation": "For a young athlete, the best protection is sports goggles with a polycarbonate lens AND a retaining strap (impact-resistant lens plus secure fit). Polycarbonate alone or a plastic frame is less protective. Sports eye protection = polycarbonate lens + strap goggles."}'),
  ('d142df90-2m','{"options": ["senior practitioners in the field of Optometry", "representative from trusted and accredited industry suppliers", "specialists and academicians in the field of optometry", "representatives from accredited national organization of optometrists"], "correct": 1, "explanation": "Under RA 8050, the Technical Panel for Optometric Education is made up of senior practitioners, specialists/academicians, and representatives of the accredited national optometry organization. A representative of industry suppliers is NOT a member (conflict of interest). Industry supplier = the exception."}'),
  ('f8b64cbe-45','{"options": ["Subpoena ad Testificandum", "Warrant of arrest", "Subpoena Duces Tecum", "Quo Warranto"], "correct": 2, "explanation": "A Subpoena Duces Tecum compels a witness to appear AND bring/produce documents. Subpoena ad Testificandum is to testify only; quo warranto challenges authority. Bring the documents = duces tecum."}'),
  ('9bf304bf-2e','{"options": ["A duly registered Optometrist of good standing", "A natural born or dual citizen of the Philippines", "At least 30 years of age", "All of the above"], "correct": 3, "explanation": "A Board nominee must be a registered optometrist in good standing, a natural-born/Filipino citizen, and at least 30 years old, so ALL OF THE ABOVE applies. Each is a separate statutory qualification under RA 8050. Board qualifications = all listed."}'),
  ('bfdb7b79-3o','{"options": ["Must take course in pharmacology prescribe by CHED", "Pass a special certification examination to be administered by the Board of Optometry", "Must take additional subjects to finish the 6 years curriculum of optometry", "A & B"], "correct": 3, "explanation": "A four-year OD must BOTH take the prescribed pharmacology course and pass the special DPA certification examination given by the Board, so the answer is A and B. DPA privilege = required course plus Board certification exam."}'),
  ('a5bcbdb6-46','{"options": ["1&3", "1&2", "2&3", "1,2 &3"], "correct": 0, "explanation": "The Certificate of Registration is signed by the Chairman of the PRC and by the Chairman and members of the Board of Optometry (items 1 and 3). The PRC chair plus the optometry board sign it. Cert of registration signers = PRC chair + Board chair/members."}'),
  ('e1d0aabc-r','{"options": ["New Optometry law of 1995", "Revised optometry law 1995", "Revised optometry law of 1917", "Revised optometry law of 1919"], "correct": 1, "explanation": "RA 8050 is the Revised Optometry Law of 1995, which modernized optometric practice (including DPAs). It replaced the older optometry law. RA 8050 = Revised Optometry Law of 1995."}'),
  ('42ad69b9-1x','{"options": ["Every three years", "Every two years", "Every year", "Every five years", "Other:"], "correct": 0, "explanation": "The PRC professional identification card is renewable every three years. Professional ID card = 3-year renewal."}'),
  ('583a3d88-1n','{"options": ["Food and Drug Administration", "DOH& FDA", "Board of Optometry", "DILG"], "correct": 2, "explanation": "Updating the list of topical Diagnostic Pharmaceutical Agents is the primary function of the Board of Optometry (it sets and revises the DPA list for the profession). The FDA registers products; the Board defines the optometric DPA list. DPA list updates = Board of Optometry."}'),
  ('396d59eb-1v','{"options": ["Police power", "Eminent Domain", "Foreclosure", "Taxation"], "correct": 1, "explanation": "Eminent domain is the state''s power to take private property for public use WITH just compensation. Police power regulates for public welfare (no compensation for regulation), and taxation raises revenue. Take property + pay for it = eminent domain."}'),
  ('d1149886-4f','{"options": ["Certified true copy of diploma with seal", "Certificate of Authorized Practice", "Professional License", "Certificate of Registration"], "correct": 3, "explanation": "The Certificate of Registration, signed by the PRC chairperson and the Board of Optometry chairman, is the proof of authority to practice optometry. A diploma or a generic license is not the statutory proof. Proof to practice = Certificate of Registration."}'),
  ('33597c63-28','{"options": ["Administrative offense", "Criminal offense", "Civil offense", "Ethical offense"], "correct": 0, "explanation": "A violation of the Code of Ethics for optometrists is an ADMINISTRATIVE offense, handled by the PRC/Board (it can lead to suspension or revocation of the license). It is not inherently criminal or civil. Ethics breach = administrative case."}'),
  ('59a12c08-37','{"options": ["Below 80% on both the theoretical and practical examination", "Below 75% on both the theoretical and practical examination", "Below 70% on both the theoretical and practical examination", "Below 50% on both the theoretical and practical examination"], "correct": 1, "explanation": "An examinee fails if the general weighted average is below 75% (the passing GWA is 75%). The other cutoffs are wrong. Pass = 75% GWA; below = fail."}'),
  ('355b6c3e-4t','{"options": ["Submit to PRC application form to take exam for the fourth time.", "Submit to the board a certificate of employment as optician", "Submit to the board of optometry proof that he has taken a refresher course in a duly accredited institution", "Get a permit from the dean of the school where he graduated"], "correct": 2, "explanation": "After failing three consecutive times, the examinee must show proof of completing a refresher course in a duly accredited institution before retaking the licensure exam. A form or employment certificate is not enough. Three fails = mandatory refresher course."}'),
  ('07b8df07-63','{"options": ["P 839.55", "P 845.45", "P 503.67", "P 839.45"], "correct": 3, "explanation": "Same as the earlier rental item: 5% creditable withholding tax on P16,789 = P839.45. Rental EWT = 5% of rent."}'),
  ('a43522a3-2r','{"options": ["RA 1911", "RA 9711", "RA 1197", "RA 7797"], "correct": 1, "explanation": "RA 9711, the Food and Drug Administration Act of 2009, strengthened and rationalized the FDA''s regulatory capacity over health products including medical devices. RA 9711 = FDA Act of 2009."}'),
  ('4a65ba25-21','{"options": ["P756.86", "P 788.88", "P 989.25", "756.96"], "correct": 3, "explanation": "Monthly percentage tax for a non-VAT business is 3% of gross sales: P25,232 x 3% = P756.96. Percentage tax = 3% of gross sales."}'),
  ('c3069389-2t','{"options": ["RA 9711", "RA 8981", "RA 1988", "RA 8050"], "correct": 1, "explanation": "RA 8981, the PRC Modernization Act of 2000, prescribes the powers and functions of the Commission and the professional regulatory boards. RA 8981 = PRC Modernization Act."}'),
  ('23970d7d-29','{"options": ["Profession", "Occupation", "Technical Vocational", "Professionalism"], "correct": 0, "explanation": "A profession is a vocation/calling requiring learning through extensive academic study. Occupation is broader; technical-vocational is trade-based; professionalism is the conduct, not the calling. Extensive academic study = profession."}'),
  ('97522e22-2q','{"options": ["Professional revenue tax", "Community tax", "Professional tax", "Income tax"], "correct": 2, "explanation": "The professional tax is levied on the privilege of practicing one''s profession (paid via the PTR to the LGU). Community tax is the cedula; income tax is on earnings. Privilege-to-practice tax = professional tax."}'),
  ('1b6401b5-27','{"options": ["Older people with underlying medical conditions", "Children under the age of 18", "Children aged 2 years and below"], "correct": 0, "explanation": "Older people with underlying medical conditions are at highest risk of severe COVID-19. Younger children are generally at lower risk of severe disease. Severe COVID risk = elderly with comorbidities."}'),
  ('12ed5190-1m','{"options": ["Cataract", "Glaucoma", "EOR", "ARMD"], "correct": 2, "explanation": "Globally the main cause of visual IMPAIRMENT is uncorrected refractive error (EOR), easily corrected with spectacles. Cataract leads in blindness, not overall impairment. Global visual impairment = uncorrected refractive error."}'),
  ('44481854-57','{"options": ["OSHS", "DOLE", "Phil Health", "DOH"], "correct": 3, "explanation": "The Department of Health (DOH) is the principal health agency ensuring access to basic public health services for Filipinos. PhilHealth insures; DOLE handles labor. Principal health agency = DOH."}'),
  ('eaad858c-2g','{"options": ["Occupational optometry", "Public Health", "Low Vision"], "correct": 1, "explanation": "Public health is the science of protecting and enhancing the health of populations and communities (prevention at the group level). Occupational optometry and low vision are narrower fields. Community health science = public health."}'),
  ('9e30e12d-3c','{"options": ["Disbursement", "Taxes", "Current Operating Expenses", "Professional Expenses"], "correct": 2, "explanation": "Current operating expenses are the day-to-day costs of running the clinic (rent, utilities, salaries, supplies). Disbursements and professional expenses are narrower terms. Day-to-day running costs = current operating expenses."}'),
  ('a690df8a-3y','{"options": ["Bad debt", "Discounts", "Credit Line", "Gross Income"], "correct": 0, "explanation": "A bad debt is an expense recognized when credit extended to a customer becomes uncollectible. Discounts and credit lines are different. Uncollectible receivable = bad debt."}'),
  ('e4b2fc01-2x','{"options": ["Inventory", "Product Selection", "Bookkeeping", "Clinic Care"], "correct": 2, "explanation": "Bookkeeping is the systematic recording of all financial transactions (purchases, sales, receipts, payments). Inventory and product selection are operational, not financial recording. Recording the money = bookkeeping."}'),
  ('83a394af-26','{"options": ["Corporation", "Semi Internship", "Employment", "Single Proprietorship"], "correct": 3, "explanation": "In a single (sole) proprietorship the law treats the owner and the business as one and the same legal person (unlimited personal liability). A corporation is a separate legal person. Owner = business = sole proprietorship."}'),
  ('1dc7c423-31','{"options": ["Invoice", "Credit Balance", "Liabilities", "Net Worth"], "correct": 0, "explanation": "An invoice is the time-stamped commercial document itemizing a transaction between buyer and seller. A statement of account summarizes amounts owed over time. Itemized transaction record = invoice."}'),
  ('3733b4c3-3c','{"options": ["Semi Internship", "Corporation", "Sole Proprietorship", "Employment"], "correct": 2, "explanation": "A sole proprietorship is the high-risk, high-debt option (the owner bears unlimited personal liability for business debts), so it should be entered with full operational knowledge. Corporations limit liability. Unlimited personal liability = sole proprietorship risk."}'),
  ('5578afcc-2x','{"options": ["Bad Debt", "Net Worth", "Practice Efficiency", "Credit Limit"], "correct": 1, "explanation": "Net worth is the total wealth after accounting for all assets minus all liabilities. Bad debt and credit limit are unrelated. Assets minus liabilities = net worth."}'),
  ('8985d8d7-60','{"options": ["Self-Employment", "Partnership", "Corporation", "Employment"], "correct": 3, "explanation": "Employment (associateship) offers the chance to gain experience, build funds toward eventual self-employment, and time to choose a permanent location carefully. Those are the classic advantages of being employed first. Experience-building entry mode = employment."}'),
  ('f8877e3d-3g','{"options": ["Limited Partnership", "General Partnership", "Unlimited Liability", "Limited Liability"], "correct": 3, "explanation": "A defining corporate feature is limited liability: shareholders are liable only up to the value of their stock. Partnerships carry unlimited liability. Shareholders risk only their shares = limited liability."}'),
  ('f16d4d99-1h','{"options": ["the liability of the partners for the debts of the business is unlimited", "there is no risk of disagreements and friction among partners and management", "each partner is an agent of the partnership and is liable for actions by other partners", "each partner is ‘jointly and severally’ liable for the partnership’s debts"], "correct": 1, "explanation": "''There is no risk of disagreements and friction among partners'' is NOT a disadvantage; in fact partnerships DO risk such conflict, so this is the false/exception statement. Unlimited liability and mutual agency are genuine disadvantages. The ''no friction'' claim is the exception."}'),
  ('453f9029-2d','{"options": ["Semi Internship", "Sole Proprietorship", "Corporation", "Employment"], "correct": 1, "explanation": "The sole proprietorship is the most common, simplest, and least expensive practice to establish (one owner, minimal formalities). Corporations are complex and costly. Simplest, cheapest setup = sole proprietorship."}'),
  ('881bae46-3t','{"options": ["Statement of Account", "Cash Discounts", "Invoices", "Liability Account"], "correct": 0, "explanation": "A statement of account is issued to show the total amount the optometrist owes the company and serves as a request for payment. An invoice records a single transaction. Summary of what you owe + payment request = statement of account."}'),
  ('2d0c252b-1g','{"options": ["Relative ease of set-up and the lower start-up costs.", "Unlimited ability to experiment with different approaches on how to deliver the best patient care possible.", "The liability of the owners towards the creditors is limited to their investment in the company.", "Relative freedom from Government control"], "correct": 2, "explanation": "Limited liability of owners toward creditors is a CORPORATION feature, NOT an advantage of solo practice (a sole proprietor has unlimited liability). Ease of setup, low start-up cost, freedom to experiment, and freedom from government control are the real solo advantages. Limited liability is the exception here."}'),
  ('b56861f8-4k','{"options": ["Asset and Liability", "Net Worth", "Fair Value", "Goodwill Value"], "correct": 3, "explanation": "Goodwill value is the established reputation of a business treated as a quantifiable intangible asset, recognized when one business acquires another. It is not net worth or fair value. Reputation as an intangible asset = goodwill."}'),
  ('4bb5c710-38','{"options": ["Enhanced financial security", "Greater profitability", "Reduced risk of financial liability", "All of the above"], "correct": 3, "explanation": "Documenting financial records gives enhanced financial security, greater profitability, and reduced risk of financial liability, so ALL OF THE ABOVE applies. Good records protect and grow the practice on every front."}'),
  ('9cdc9492-1u','{"options": ["Liquidation", "Incorporation", "Dissolution", "Stock market"], "correct": 1, "explanation": "Incorporation is the legal process of forming a corporate entity (filing with the SEC). Liquidation and dissolution end a company; the stock market is unrelated. Forming a corporation = incorporation."}'),
  ('c6ef823b-9v','{"options": ["Deposits", "Loans", "Depreciable properties", "Inventory"], "correct": 2, "explanation": "Depreciable properties are items not directly consumed but whose value diminishes over years (equipment, furniture, fixtures, building improvements). Inventory is consumed/sold; deposits and loans are financial. Long-life assets that lose value = depreciable properties."}'),
  ('2f72931f-4f','{"options": ["Goodwill value", "Market value", "Fair value", "Minimum value"], "correct": 2, "explanation": "Fair value is the price to sell an asset or transfer a liability in an orderly transaction between market participants at the measurement date. Goodwill and minimum value are different concepts. Orderly market exit price = fair value."}'),
  ('ace91101-2r','{"options": ["RA 1911", "RA 9711", "RA 1197", "RA 7797"], "correct": 1, "explanation": "RA 9711 (FDA Act of 2009) strengthened and rationalized the FDA''s regulatory capacity over medical devices and other health products. RA 9711 = FDA Act of 2009."}'),
  ('67eff127-2j','{"options": ["CN3", "CN5", "CN6", "CN4"], "correct": 3, "decode": "The fully DECUSSATED nerve to the CONTRALATERAL superior oblique is CN4 (trochlear). It is the only cranial nerve that exits dorsally and crosses completely.", "ow": ["CN3 stays ipsilateral and runs most muscles, not the crossed SO.", "CN5 is sensory to the face, not a crossed motor nerve.", "CN6 runs the lateral rectus, uncrossed.", "Correct. CN4 fully decussates to the contralateral superior oblique."]}'),
  ('50d87fa1-2h','{"options": ["Diabetic microvascular ischemia", "Benign variant", "Myasthenia gravis", "Compressive aneurysm"], "correct": 3, "decode": "A PUPIL-INVOLVING CN3 palsy is a surgical red flag for a compressive aneurysm (pupil fibers ride on the outside, hit first by compression). Ischemic causes spare the pupil.", "ow": ["Ischemia typically SPARES the pupil, so a blown pupil argues against it.", "A blown-pupil CN3 palsy is never benign.", "Myasthenia does not fix or dilate the pupil.", "Correct. Pupil involvement means compression, classically an aneurysm."]}'),
  ('ca05691b-1f','{"options": ["Causes bilateral blindness", "Causes nystagmus", "Spares the pupil", "Dilates the pupil"], "correct": 2, "decode": "An ISCHEMIC (diabetic) CN3 palsy classically SPARES the pupil, because the outer pupillary fibers keep their blood supply while the inner motor fibers infarct. Compression is what blows the pupil.", "ow": ["A single CN3 palsy does not cause bilateral blindness.", "Nystagmus is not a feature of a CN3 palsy.", "Correct. Diabetic (ischemic) CN3 palsy spares the pupil.", "Pupil dilation points to compression, not ischemia."]}'),
  ('13a9ca49-17','{"options": ["CN7", "CN5", "CN3", "CN2"], "correct": 1, "decode": "Corneal sensation is carried by CN5 (trigeminal, V1 ophthalmic branch). CN7 moves the lids, CN3 the muscles, CN2 is vision.", "ow": ["CN7 is motor to the lids (blink), not corneal sensation.", "Correct. CN5 (V1) carries corneal sensation.", "CN3 is motor to eye muscles, not sensation.", "CN2 is the optic nerve (vision), not sensation."]}'),
  ('72c0b05c-21','{"options": ["V3 mandibular", "V1 ophthalmic", "V2 maxillary", "All are mixed"], "correct": 1, "decode": "The smallest, purely SENSORY trigeminal division is V1 (ophthalmic). V3 is the largest and carries motor fibers; V2 is sensory but larger.", "ow": ["V3 is the largest and has a motor component.", "Correct. V1 ophthalmic is the smallest, purely sensory division.", "V2 is sensory but larger than V1.", "The divisions differ; V3 has motor fibers, so not all are mixed."]}'),
  ('63918f64-1l','{"options": ["Sphenoidal", "Frontal", "Maxillary", "Ethmoidal"], "correct": 3, "decode": "Orbital cellulitis most often spreads from the ETHMOID sinus, across the paper-thin lamina papyracea on the medial wall. The other sinuses are less common routes.", "ow": ["The sphenoid sits deeper; not the usual route.", "The frontal sinus is a less common source.", "The maxillary sinus is below the floor, less common.", "Correct. The ethmoid sinus is the classic spread route."]}'),
  ('9bc6c65c-25','{"options": ["Orbital cellulitis", "Dacryocystitis", "Blowout fracture", "Retrobulbar neuritis"], "correct": 3, "decode": "Sphenoid sinusitis sits next to the orbital apex and optic nerve, so its classic ocular complication is retrobulbar (optic) neuritis. Cellulitis is the ethmoid pattern.", "ow": ["Orbital cellulitis is the ethmoid complication, not sphenoid.", "Dacryocystitis is a tear-sac infection, unrelated.", "A blowout fracture is traumatic, not infectious.", "Correct. Sphenoid sinusitis classically causes retrobulbar neuritis."]}'),
  ('c7b6a718-26','{"options": ["CN5", "CN3", "CN7", "CN6"], "correct": 2, "decode": "CN7 (facial) mediates both eyelid CLOSURE (orbicularis) and reflex LACRIMAL secretion (parasympathetic). CN5 is sensory; CN3 and CN6 move the globe.", "ow": ["CN5 is sensory to the face and cornea, not lid closure.", "CN3 elevates the lid and moves the eye, not closure.", "Correct. CN7 closes the lids and drives reflex tearing.", "CN6 runs the lateral rectus, not lid closure."]}'),
  ('ec3db832-1x','{"options": ["Superior orbital fissure", "Inferior orbital fissure", "Optic canal", "Foramen rotundum"], "correct": 2, "decode": "The optic nerve (CN2) and ophthalmic artery enter through the OPTIC CANAL. The superior orbital fissure carries the eye-movement nerves instead.", "ow": ["The superior orbital fissure carries CN3, 4, V1, 6, not the optic nerve.", "The inferior orbital fissure carries V2 branches, not CN2.", "Correct. CN2 and the ophthalmic artery use the optic canal.", "Foramen rotundum transmits V2, not the optic nerve."]}'),
  ('0672b586-1j','{"options": ["CN3", "CN4", "CN2", "CN6"], "correct": 1, "decode": "CN4 (trochlear) has the longest intracranial course, looping around the brainstem before its dorsal exit. That long thin course makes it vulnerable to head trauma.", "ow": ["CN3 has a shorter course than the trochlear.", "Correct. CN4 has the longest intracranial course.", "CN2 is a tract, and its course is shorter than CN4''s.", "CN6 has a long course but shorter than CN4''s."]}'),
  ('7f670332-z','{"options": ["CN4", "CN5", "CN6", "CN3"], "correct": 2, "decode": "The lateral rectus is run by CN6 (abducens), following the LR6 rule. CN4 is the superior oblique; CN3 runs the rest; CN5 is sensory.", "ow": ["CN4 is the superior oblique, not the lateral rectus.", "CN5 is sensory, not a motor nerve here.", "Correct. LR6: the lateral rectus is CN6.", "CN3 runs most other muscles, not the lateral rectus."]}'),
  ('5a7030a4-1m','{"options": ["Occipital", "Temporal", "Parietal", "Frontal"], "correct": 0, "decode": "The primary visual cortex (Brodmann area 17) sits in the OCCIPITAL lobe at the back of the brain. The other lobes are not primary vision.", "ow": ["Correct. Area 17 is in the occipital lobe.", "The temporal lobe handles hearing and memory.", "The parietal lobe handles touch and spatial sense.", "The frontal lobe handles planning and movement."]}'),
  ('bd081ca3-1l','{"options": ["Abduction", "Elevation", "Depression", "Intorsion"], "correct": 3, "decode": "The PRIMARY action of the superior oblique is INTORSION (its secondary actions are depression and abduction). Muscles running obliquely twist first.", "ow": ["Abduction is a secondary, not primary, SO action.", "Elevation is not a superior oblique action.", "Depression is a secondary SO action, not primary.", "Correct. The superior oblique''s primary action is intorsion."]}'),
  ('da1f8daa-1w','{"options": ["Lateral rectus", "Superior rectus", "Medial rectus", "Inferior oblique"], "correct": 3, "decode": "The inferior oblique is the ONE extraocular muscle NOT arising from the annulus of Zinn; it originates near the orbital floor (maxilla). The four recti and superior oblique arise from the ring.", "ow": ["The lateral rectus arises from the annulus of Zinn.", "The superior rectus arises from the annulus.", "The medial rectus arises from the annulus.", "Correct. The inferior oblique arises from the orbital floor, not the ring."]}'),
  ('696dcb6b-14','{"options": ["Floor", "Roof", "Medial wall", "Lateral wall"], "correct": 2, "decode": "The thinnest, weakest orbital wall is the MEDIAL wall (lamina papyracea of the ethmoid), which is why infection and blowouts spread there. The floor is also thin but the medial wall is thinnest.", "ow": ["The floor is thin (blowout site) but not the thinnest.", "The roof is relatively thick.", "Correct. The medial wall (lamina papyracea) is thinnest.", "The lateral wall is the thickest, most protective."]}'),
  ('2f6e27d0-1d','{"options": ["CN2", "CN4", "CN3", "CN6"], "correct": 0, "decode": "The superior orbital fissure transmits CN3, 4, V1, and 6, so the EXCEPTION is CN2 (which uses the optic canal). Pick the optic nerve.", "ow": ["Correct. CN2 uses the optic canal, not the superior orbital fissure.", "CN4 passes through the superior orbital fissure.", "CN3 passes through the superior orbital fissure.", "CN6 passes through the superior orbital fissure."]}'),
  ('5f435ec9-1v','{"options": ["Lateral rectus", "Inferior rectus", "Superior rectus", "Medial rectus"], "correct": 3, "decode": "The MEDIAL rectus inserts nearest the limbus (about 5.5 mm) and is the strongest rectus. The insertions follow the spiral of Tillaux, with medial closest.", "ow": ["The lateral rectus inserts farther back than the medial.", "The inferior rectus inserts farther than the medial.", "The superior rectus inserts farthest of the horizontal/vertical recti.", "Correct. The medial rectus inserts nearest the limbus and is strongest."]}'),
  ('9a76408a-11','{"options": ["Medial rectus", "Inferior oblique", "Superior oblique", "Lateral rectus"], "correct": 2, "decode": "The SUPERIOR OBLIQUE is the longest extraocular muscle (its long tendon loops through the trochlea). The recti and inferior oblique are shorter.", "ow": ["The medial rectus is shorter than the superior oblique.", "The inferior oblique is the shortest, not longest.", "Correct. The superior oblique is the longest extraocular muscle.", "The lateral rectus is shorter than the superior oblique."]}'),
  ('e0bb6983-2y','{"options": ["CN7", "CN3", "CN4", "CN6"], "correct": 2, "decode": "Vertical diplopia worse on DOWNGAZE and ADDUCTION, with a compensatory head tilt, is a CN4 (superior oblique) palsy. The head tilt away is the Bielschowsky sign.", "ow": ["CN7 is facial motor, not an eye-movement palsy.", "CN3 palsy gives down-and-out eye and ptosis, not this pattern.", "Correct. Downgaze/adduction diplopia with head tilt is a CN4 palsy.", "CN6 palsy gives horizontal, not vertical, diplopia."]}'),
  ('26f73c47-1w','{"options": ["Recti behind, obliques in front", "Both behind the equator", "Recti in front, obliques behind the equator", "Both in front of the equator"], "correct": 2, "decode": "The RECTI insert IN FRONT of the equator; the OBLIQUES insert BEHIND it. That front-recti, back-obliques arrangement lets the obliques tort and vertically act.", "ow": ["Reversed; recti are in front, obliques behind.", "Not both behind; recti are in front.", "Correct. Recti insert in front, obliques behind the equator.", "Not both in front; obliques insert behind."]}'),
  ('36096f03-2d','{"options": ["Enucleation with implant", "Evisceration", "Exenteration", "Enucleation"], "correct": 1, "decode": "Removing the internal contents while KEEPING the sclera and muscles is evisceration. Enucleation removes the whole globe; exenteration removes the orbit''s contents.", "ow": ["Enucleation removes the whole globe, not just contents.", "Correct. Evisceration keeps the scleral shell and muscles.", "Exenteration removes the entire orbital contents.", "Enucleation removes the globe, sclera included."]}'),
  ('fcaaca20-21','{"options": ["Whitnall''s ligament", "Lockwood''s ligament", "Check ligament", "Annulus of Zinn"], "correct": 1, "decode": "The suspensory ligament of the eyeball, a thickening of Tenon''s capsule that slings the globe, is Lockwood''s ligament. Whitnall''s slings the levator; the annulus is the muscle origin.", "ow": ["Whitnall''s ligament is the superior (levator) suspensory ligament.", "Correct. Lockwood''s ligament is the suspensory sling of the globe.", "Check ligaments limit rectus muscle excursion, different structures.", "The annulus of Zinn is the common muscle origin, not a sling."]}'),
  ('0ebb6cba-y','{"options": ["5", "6", "7", "8"], "correct": 2, "decode": "Seven bones form the bony orbit: frontal, sphenoid, zygomatic, maxilla, ethmoid, lacrimal, and palatine. Not 5, 6, or 8.", "ow": ["Fewer than the seven orbital bones.", "Fewer than the seven orbital bones.", "Correct. Seven bones form the orbit.", "One more than the seven orbital bones."]}'),
  ('836b9b06-1h','{"options": ["Produces the aqueous tear layer", "Separates lid from orbit", "Drains aqueous from the eye", "Rotates the globe on gaze"], "correct": 1, "decode": "The orbital SEPTUM matters because it SEPARATES the lid from the orbit, the barrier dividing preseptal from orbital cellulitis. It does not make tears, drain aqueous, or move the globe.", "ow": ["Tears are made by lacrimal and meibomian glands, not the septum.", "Correct. The septum separates the lid from the orbit.", "Aqueous drains through the trabecular meshwork, not the septum.", "The septum does not rotate the globe."]}'),
  ('c43ccf94-1m','{"options": ["Lipid → aqueous → mucin", "Lipid → mucin → aqueous", "Mucin → aqueous → lipid", "Aqueous → lipid → mucin"], "correct": 0, "decode": "From outside (air) inward toward the cornea, the tear film is LIPID, then AQUEOUS, then MUCIN. Lipid outermost slows evaporation; mucin innermost anchors to the cornea.", "ow": ["Correct. Lipid (outer), aqueous (middle), mucin (inner).", "Mucin is innermost, not middle.", "Reversed order; lipid is outermost, not innermost.", "Lipid is the outer layer, not the middle."]}'),
  ('a406ed5f-18','{"options": ["All equal", "Lipid", "Aqueous", "Mucin"], "correct": 2, "decode": "The AQUEOUS layer is by far the thickest tear layer (the bulk of tear volume). Lipid and mucin are thin films at the outer and inner surfaces.", "ow": ["The layers are not equal; aqueous dominates.", "The lipid layer is a thin outer film.", "Correct. The aqueous layer is the thickest.", "The mucin layer is a thin inner film."]}'),
  ('4c151280-1f','{"options": ["Glands of Krause and Wolfring", "Conjunctival goblet cells", "Meibomian glands of the tarsus", "The main lacrimal gland"], "correct": 0, "decode": "BASIC (resting) aqueous tears come from the accessory glands of Krause and Wolfring. The MAIN lacrimal gland handles REFLEX tearing; goblet cells make mucin; meibomian glands make lipid.", "ow": ["Correct. Krause and Wolfring make basal aqueous tears.", "Goblet cells secrete mucin, not aqueous.", "Meibomian glands secrete lipid, not aqueous.", "The main gland provides reflex, not basal, secretion."]}'),
  ('9081766e-1j','{"options": ["Tear film stability; aqueous volume", "Both measure tear film stability", "Aqueous volume; tear film stability", "Both measure aqueous volume"], "correct": 2, "decode": "Schirmer''s measures aqueous VOLUME (strip wetting); TBUT measures tear film STABILITY (time to breakup). Match volume to Schirmer, stability to TBUT.", "ow": ["Reversed; Schirmer is volume, TBUT is stability.", "Schirmer measures volume, not stability.", "Correct. Schirmer = aqueous volume; TBUT = film stability.", "TBUT measures stability, not volume."]}'),
  ('02f0a82f-22','{"options": ["Punctal stenosis", "Aqueous-deficient dry eye", "Evaporative dry eye", "Reflex hypersecretion"], "correct": 2, "decode": "Normal Schirmer (good volume) but short TBUT (unstable film) points to EVAPORATIVE dry eye (meibomian/lipid problem). Aqueous-deficient dry eye would give a LOW Schirmer.", "ow": ["Punctal stenosis causes tearing overflow, not a short TBUT.", "Aqueous deficiency would lower the Schirmer, which here is normal.", "Correct. Normal Schirmer with short TBUT is evaporative dry eye.", "Reflex hypersecretion raises tearing, not this pattern."]}'),
  ('25558406-11','{"options": ["Inferior meatus", "Superior meatus", "Middle meatus", "Sphenoethmoidal recess"], "correct": 0, "decode": "The nasolacrimal duct drains into the INFERIOR meatus (under the inferior turbinate). The other meatus drain paranasal sinuses.", "ow": ["Correct. The nasolacrimal duct drains into the inferior meatus.", "The superior meatus drains posterior ethmoid sinuses.", "The middle meatus drains most anterior sinuses.", "The sphenoethmoidal recess drains the sphenoid sinus."]}'),
  ('1588d9e7-1a','{"options": ["Complete ptosis from levator palsy", "Partial ptosis from Müller''s paralysis", "No ptosis, only miosis", "Variable, fatiguable ptosis"], "correct": 1, "decode": "Horner''s paralyzes Müller''s muscle (sympathetic), giving a PARTIAL ptosis (plus miosis, anhidrosis). Levator (CN3) palsy gives a complete ptosis; myasthenia gives fatiguable ptosis.", "ow": ["A complete ptosis is a levator (CN3) problem, not Horner''s.", "Correct. Horner''s gives partial ptosis from Müller''s paralysis.", "Horner''s does produce a mild ptosis, not miosis alone.", "Fatiguable ptosis is myasthenia, not Horner''s."]}'),
  ('3c2b3a76-16','{"options": ["IgM", "IgG", "IgA", "IgE"], "correct": 2, "decode": "The predominant tear immunoglobulin is IgA (secretory), the mucosal antibody. IgG, IgM, and IgE are minor in tears.", "ow": ["IgM is not the predominant tear antibody.", "IgG is present but not predominant in tears.", "Correct. Secretory IgA predominates in tears.", "IgE relates to allergy, not the main tear antibody."]}'),
  ('1b09c676-1d','{"options": ["Aberrant CN7 regeneration", "A tumor of the lacrimal gland", "Reflex hypersecretion in dry eye", "Stenosis of the lacrimal punctum"], "correct": 0, "decode": "''Crocodile tears'' (tearing while eating) come from ABERRANT CN7 regeneration, misrouting salivary fibers to the lacrimal gland. It is not a tumor, dry eye, or punctal problem.", "ow": ["Correct. Aberrant CN7 regeneration causes gustatory tearing.", "A lacrimal gland tumor does not cause gustatory tearing.", "Dry eye hypersecretion is reflex, not meal-triggered.", "Punctal stenosis blocks drainage, not this."]}'),
  ('5c6f49d0-1e','{"options": ["Fornix", "Bulbar conjunctiva", "Plica semilunaris", "Lid margins and limbus"], "correct": 3, "decode": "Goblet cells (mucin) populate the conjunctiva but are ABSENT at the lid margins and limbus (transition zones). They are densest in the fornix and plica.", "ow": ["The fornix is rich in goblet cells.", "The bulbar conjunctiva contains goblet cells.", "The plica semilunaris is goblet-cell rich.", "Correct. Goblet cells are absent at the lid margins and limbus."]}'),
  ('3af77fb8-2k','{"options": ["Lacrimal gland agenesis", "Gonococcal conjunctivitis", "Nasolacrimal duct obstruction", "Congenital glaucoma"], "correct": 2, "decode": "A newborn with epiphora and mucopurulent discharge since birth has congenital nasolacrimal duct OBSTRUCTION (a blocked, infected sac). Gonococcal conjunctivitis appears in the first days; congenital glaucoma gives a cloudy enlarged cornea.", "ow": ["Gland agenesis causes dryness, not watering and discharge.", "Gonococcal conjunctivitis is hyperacute in the first days of life.", "Correct. Congenital nasolacrimal duct obstruction fits epiphora since birth.", "Congenital glaucoma gives a cloudy, enlarged cornea, not discharge."]}'),
  ('5eb1b129-2m','{"options": ["10 D", "19 D", "43 D", "59 D"], "correct": 2, "decode": "The cornea provides about 43 D, the eye''s STRONGEST refracting surface (air-to-tissue interface). The lens adds about 19 D. Pick the larger corneal value.", "ow": ["10 D is far too low for the cornea.", "19 D is roughly the LENS power, not the cornea.", "Correct. The cornea contributes about 43 D.", "59 D is the whole eye''s power, not the cornea alone."]}'),
  ('136a3660-1m','{"options": ["Bowman''s", "Stroma", "Endothelium", "Epithelium"], "correct": 1, "decode": "The STROMA is about 90% of corneal thickness (regularly packed collagen). Epithelium, Bowman''s, and endothelium are thin layers.", "ow": ["Bowman''s is a thin acellular layer.", "Correct. The stroma is about 90% of corneal thickness.", "The endothelium is a single cell layer.", "The epithelium is only a few cell layers."]}'),
  ('7d433ec9-1e','{"options": ["Epithelium", "Bowman''s membrane", "Descemet''s membrane", "Tear film"], "correct": 1, "decode": "BOWMAN''S membrane cannot regenerate; injury to it heals with scar. The epithelium regenerates readily; Descemet''s can be re-secreted by endothelium.", "ow": ["The epithelium regenerates quickly.", "Correct. Bowman''s membrane does not regenerate and scars.", "Descemet''s can be re-formed by the endothelium.", "The tear film is not a corneal layer that regenerates."]}'),
  ('dde4badb-k','{"options": ["Thinnest at the limbus", "Uniform throughout", "Greater centrally than peripherally", "Thinner centrally than peripherally"], "correct": 3, "decode": "The cornea is THINNER CENTRALLY (~0.52 mm) and thicker peripherally (~0.65 mm). It is not uniform, and it is not thickest centrally.", "ow": ["It is actually thicker, not thinnest, at the limbus.", "It is not uniform; center is thinner.", "Reversed; the center is thinner, not thicker.", "Correct. The cornea is thinner centrally than peripherally."]}'),
  ('71818185-1a','{"options": ["Evaporation from the tear film", "The integrity of Bowman''s layer", "Mucin from goblet cells", "The endothelial Na-K pump"], "correct": 3, "decode": "Corneal clarity (deturgescence, staying dehydrated) is maintained by the ENDOTHELIAL Na-K pump that draws water out. Bowman''s, tears, and mucin do not run the pump.", "ow": ["Evaporation is minor; the pump keeps the cornea clear.", "Bowman''s provides structure, not fluid control.", "Mucin anchors the tear film, not corneal hydration.", "Correct. The endothelial Na-K pump keeps the cornea deturgescent."]}'),
  ('a7d66df5-1k','{"options": ["Bowman''s degenerates", "Endothelial cell loss disables the pump", "Goblet cells fail", "Epithelial tight junctions fail"], "correct": 1, "decode": "Fuchs'' dystrophy loses ENDOTHELIAL cells, disabling the pump, so fluid builds up and the cornea swells. It is not a Bowman''s, goblet, or epithelial problem.", "ow": ["Bowman''s is not the failing layer in Fuchs''.", "Correct. Endothelial loss disables the pump, causing edema.", "Goblet cells make mucin, unrelated to corneal edema.", "Epithelial junctions are not the Fuchs'' defect."]}'),
  ('9296b007-11','{"options": ["The EOM insertions", "The limbus", "The equator", "The optic nerve entrance"], "correct": 3, "decode": "The sclera is THICKEST at the OPTIC NERVE entrance (~1 mm) and thinnest under the rectus insertions. The nerve entrance anchors the tough coat.", "ow": ["Under the rectus insertions the sclera is thinnest.", "The limbus is a transition, not the thickest point.", "The equator is intermediate, not the thickest.", "Correct. The sclera is thickest at the optic nerve entrance."]}'),
  ('ea76ab03-1e','{"options": ["They contain different cell types", "The sclera is much thicker than cornea", "Corneal collagen is regularly spaced", "The cornea is more vascular than sclera"], "correct": 2, "decode": "The cornea is clear because its collagen is REGULARLY, uniformly spaced (destructive interference of scatter); scleral collagen is irregular, so it scatters all light and looks white.", "ow": ["Both are mostly collagen; spacing, not cell type, is the key.", "Thickness is not why the sclera is opaque.", "Correct. Regular corneal collagen spacing gives transparency.", "The cornea is avascular, not more vascular, than sclera."]}'),
  ('4fa4357d-1y','{"options": ["Descemet''s and endothelium", "Stroma and Bowman''s layer", "Epithelium and stroma", "Epithelium and Bowman''s layer"], "correct": 0, "decode": "The nasociliary (CN5) nerves supply the cornea except DESCEMET''S and the ENDOTHELIUM (the deep non-innervated layers). The anterior layers are richly innervated.", "ow": ["Correct. Descemet''s and endothelium lack corneal innervation.", "The stroma and Bowman''s ARE innervated.", "The epithelium and stroma are innervated.", "The epithelium and Bowman''s are innervated."]}'),
  ('dce7f27c-i','{"options": ["An ectasia of the anterior sclera", "A rupture of Descemet''s membrane", "Descemet''s bulging through the stroma", "A defect of the corneal epithelium"], "correct": 2, "decode": "A descemetocele is Descemet''s membrane BULGING through a thinned stroma (deep ulcer down to Descemet''s), a pre-perforation emergency. It is not a scleral ectasia, a simple tear, or an epithelial defect.", "ow": ["An anterior scleral ectasia is a staphyloma, not a descemetocele.", "A rupture is a break; a descemetocele is an intact bulge.", "Correct. A descemetocele is Descemet''s bulging through the stroma.", "An epithelial defect is superficial, not down to Descemet''s."]}'),
  ('397c06a4-2e','{"options": ["Trabecular meshwork", "Ciliary body band", "Schwalbe''s line", "Scleral spur"], "correct": 2, "decode": "The most anterior gonioscopy landmark, a glistening line at the end of Descemet''s, is Schwalbe''s line. Moving posteriorly you then reach the trabecular meshwork, scleral spur, and ciliary body band.", "ow": ["The trabecular meshwork lies just behind Schwalbe''s line.", "The ciliary body band is the most posterior landmark.", "Correct. Schwalbe''s line is the most anterior angle landmark.", "The scleral spur lies posterior to the meshwork."]}'),
  ('64819277-1n','{"options": ["Variable by gaze", "Equal", "Larger", "Smaller"], "correct": 2, "decode": "The horizontal corneal diameter (~12 mm) is LARGER than the vertical (~11 mm), so the cornea is a slightly wider oval. Not equal or smaller.", "ow": ["It is a fixed shape, not gaze-dependent.", "The two diameters are not equal.", "Correct. The horizontal corneal diameter is larger than the vertical.", "The horizontal is larger, not smaller."]}'),
  ('a3b500d0-r','{"options": ["Iris, ciliary body, choroid", "Iris, lens, vitreous", "Sclera, choroid, retina", "Cornea, lens, retina"], "correct": 0, "decode": "The uveal tract is the middle vascular coat: IRIS, CILIARY BODY, and CHOROID. The lens, vitreous, sclera, cornea, and retina are not uvea.", "ow": ["Correct. The uvea is iris, ciliary body, and choroid.", "The lens and vitreous are not uveal structures.", "The sclera and retina are separate coats.", "The cornea, lens, and retina are not the uvea."]}'),
  ('0348a715-1h','{"options": ["Has no effect on the lens", "Tightens the zonules, flattening the lens", "Pulls the lens backward", "Relaxes the zonules, letting the lens round up"], "correct": 3, "decode": "In accommodation the ciliary muscle CONTRACTS, which RELAXES the zonules, letting the elastic lens ROUND UP (more power) for near focus. The tightening/flattening option is the resting, distance state.", "ow": ["The ciliary muscle strongly affects lens shape.", "Tightening zonules and flattening is the resting (distance) state.", "The lens rounds up, it does not move backward.", "Correct. Ciliary contraction relaxes zonules so the lens rounds up."]}'),
  ('48b29f51-25','{"options": ["Pars plicata", "Iris root", "Pars plana", "Limbus"], "correct": 2, "decode": "Vitreoretinal surgery enters through the PARS PLANA, a safe zone with no retina or major vessels, about 3-4 mm behind the limbus. The pars plicata, iris root, and limbus are unsafe entries.", "ow": ["The pars plicata has ciliary processes; not the safe entry.", "The iris root is anterior and vascular, not the entry.", "Correct. The pars plana is the safe surgical entry.", "The limbus is the anterior-segment entry, not for vitreoretinal work."]}'),
  ('fe136db7-13','{"options": ["Parasympathetic CN3", "CN7", "CN5", "Sympathetic fibers"], "correct": 0, "decode": "The sphincter pupillae (constrictor) is run by PARASYMPATHETIC CN3 fibers. The dilator is sympathetic; CN5 is sensory, CN7 motor to the face.", "ow": ["Correct. Parasympathetic CN3 drives the sphincter (miosis).", "CN7 is facial motor, not iris sphincter.", "CN5 is sensory, not the sphincter''s nerve.", "Sympathetic fibers run the DILATOR, not the sphincter."]}'),
  ('c93de2c5-u','{"options": ["Ora serrata", "Equator", "Anterior periphery", "Posterior pole"], "correct": 3, "decode": "The choroid is thickest at the POSTERIOR POLE (highest metabolic demand near the macula) and thins toward the ora serrata. Pick the back of the eye.", "ow": ["The choroid is thinnest near the ora serrata.", "The equator is intermediate thickness.", "The anterior periphery is thin choroid.", "Correct. The choroid is thickest at the posterior pole."]}'),
  ('dd0b5c71-29','{"options": ["Marcus-Gunn pupil", "Argyll-Robertson pupils", "Horner''s syndrome", "Adie''s tonic pupils"], "correct": 1, "decode": "Bilateral small, irregular pupils with light-near dissociation (react to near, not light) are Argyll-Robertson pupils (neurosyphilis). Adie''s is a large tonic pupil; Horner''s is small but reacts to light.", "ow": ["A Marcus-Gunn pupil is an afferent defect, not this.", "Correct. Light-near dissociation with small irregular pupils is Argyll-Robertson.", "Horner''s is a small pupil that still reacts to light.", "Adie''s is a large tonic pupil, not small and bilateral."]}'),
  ('a9c03ece-1e','{"options": ["Optic chiasm", "Ciliary ganglion / short ciliary nerve", "Pretectal nucleus", "Superior cervical ganglion"], "correct": 1, "decode": "An Adie''s tonic pupil comes from a lesion at the CILIARY GANGLION / short ciliary nerves (postganglionic parasympathetic). This denervation gives supersensitivity to dilute pilocarpine.", "ow": ["The chiasm handles vision fibers, not the tonic pupil.", "Correct. Adie''s is a ciliary ganglion / short ciliary nerve lesion.", "The pretectal nucleus is the light-reflex relay, not Adie''s site.", "The superior cervical ganglion is sympathetic (Horner''s), not Adie''s."]}'),
  ('d948d901-1b','{"options": ["An Argyll-Robertson pupil", "A normal healthy pupil", "A Horner''s syndrome pupil", "A tonic Adie''s pupil"], "correct": 3, "decode": "Dilute 0.125% pilocarpine constricts a tonic ADIE''S pupil (denervation supersensitivity) but not a normal pupil. That weak-dose constriction is the diagnostic tell.", "ow": ["Argyll-Robertson pupils are not defined by this supersensitivity test.", "A normal pupil does not react to such a weak dose.", "Horner''s is diagnosed with cocaine/apraclonidine, not this.", "Correct. A tonic Adie''s pupil constricts to dilute pilocarpine."]}'),
  ('05bd8ed9-1f','{"options": ["Iris root only", "Ciliary zone", "Pupillary zone", "Posterior pigment epithelium only"], "correct": 1, "decode": "The dilator pupillae lies in the CILIARY zone (outer iris), radiating like spokes; the sphincter sits in the pupillary zone (inner ring). Match dilator to the outer ciliary zone.", "ow": ["The dilator spans the ciliary zone, not just the root.", "Correct. The dilator pupillae lies in the ciliary zone.", "The pupillary zone holds the sphincter, not the dilator.", "The posterior pigment epithelium is separate from the dilator muscle."]}'),
  ('2b5589a0-1i','{"options": ["Outer retina", "Inner retina", "The whole retina equally", "Only the fovea"], "correct": 0, "decode": "The choriocapillaris (from the choroid) supplies the OUTER retina (photoreceptors, RPE) by diffusion; the central retinal artery supplies the INNER retina. Match choroid to outer.", "ow": ["Correct. The choriocapillaris supplies the outer retina.", "The inner retina is fed by the central retinal artery.", "The two supplies split the retina, not equally shared.", "It supplies the outer retina broadly, not only the fovea."]}'),
  ('f7432d79-18','{"options": ["Bruch''s membrane", "Lamina cribrosa", "Sclera", "Internal limiting membrane"], "correct": 0, "decode": "Between the choroid and the RPE lies BRUCH''S membrane (the basement complex where drusen deposit). The lamina cribrosa is at the optic nerve; the ILM is the innermost retina.", "ow": ["Correct. Bruch''s membrane lies between choroid and RPE.", "The lamina cribrosa is at the optic nerve head.", "The sclera is the outer coat, external to the choroid.", "The internal limiting membrane is the innermost retinal layer."]}'),
  ('25364d21-16','{"options": ["1 mm", "6 mm", "8 mm", "3–4 mm"], "correct": 3, "decode": "The normal resting pupil is about 3-4 mm in room light. 1 mm is a pinpoint; 6-8 mm is a dilated pupil.", "ow": ["1 mm is a pinpoint (miotic) pupil.", "6 mm is a dilated pupil, not resting.", "8 mm is markedly dilated.", "Correct. The resting pupil is about 3-4 mm."]}'),
  ('5b425fe5-w','{"options": ["The anterior lens epithelium", "The choriocapillaris", "The trabecular meshwork", "Non-pigment ciliary epithelium"], "correct": 3, "decode": "Aqueous is produced by the NON-PIGMENTED ciliary epithelium (of the ciliary processes). The trabecular meshwork is the DRAIN, not the source; the lens epithelium and choriocapillaris are unrelated.", "ow": ["The lens epithelium does not make aqueous.", "The choriocapillaris supplies the outer retina, not aqueous.", "The trabecular meshwork drains aqueous, it does not make it.", "Correct. The non-pigmented ciliary epithelium produces aqueous."]}'),
  ('ae5fa7f3-1t','{"options": ["20%", "50%", "80%", "100%"], "correct": 2, "decode": "About 80% of aqueous leaves through the TRABECULAR (conventional) meshwork; the remaining ~20% goes uveoscleral. Match the meshwork to the larger share.", "ow": ["20% is the UVEOSCLERAL share, not trabecular.", "50% understates the trabecular route.", "Correct. About 80% of outflow is trabecular.", "Not 100%; some outflow is uveoscleral."]}'),
  ('e6ee962b-2c','{"options": ["Anterior capsule", "All equal", "Posterior capsule", "Equatorial capsule only"], "correct": 0, "decode": "The ANTERIOR lens capsule is the thickest region and the thickest basement membrane in the body (it keeps thickening with age). The posterior capsule is thinnest.", "ow": ["Correct. The anterior capsule is the thickest basement membrane in the body.", "The regions differ; anterior is thickest.", "The posterior capsule is the thinnest region.", "The equatorial capsule is not the thickest."]}'),
  ('b2e94aaa-12','{"options": ["Rupture of the zonular fibers", "Posterior lens displacement", "Atrophy of the ciliary muscle", "Hardening of the lens nucleus"], "correct": 3, "decode": "Presbyopia is primarily the HARDENING (sclerosis) of the lens nucleus, so it can no longer round up. It is not zonule rupture, lens displacement, or ciliary atrophy.", "ow": ["Zonules do not rupture in presbyopia.", "The lens does not displace in presbyopia.", "The ciliary muscle is relatively preserved; the lens stiffens.", "Correct. Presbyopia is mainly lens nucleus hardening."]}'),
  ('d5147160-x','{"options": ["100% water", "50% water", "98.5% water", "75% water"], "correct": 2, "decode": "The vitreous is about 98-99% water (with collagen and hyaluronan giving the gel). It is not pure water or as low as 75%.", "ow": ["Not quite 100%; it has collagen and hyaluronan.", "Far too low; vitreous is mostly water.", "Correct. The vitreous is about 98.5% water.", "Higher than 75%; vitreous is about 98-99% water."]}'),
  ('96aeb0cc-12','{"options": ["A higher protein content", "A lower osmolarity", "A higher glucose level", "More ascorbic acid"], "correct": 3, "decode": "Aqueous has MORE ASCORBIC ACID (vitamin C) than plasma, an antioxidant concentrated in the eye. It has LESS protein and glucose than plasma and similar osmolarity.", "ow": ["Aqueous has far LESS protein than plasma.", "Aqueous osmolarity is similar to plasma, not clearly lower.", "Aqueous glucose is lower than plasma.", "Correct. Aqueous has more ascorbic acid than plasma."]}'),
  ('dcf8ce67-13','{"options": ["10–21 mmHg", "30–40 mmHg", "22–30 mmHg", "5–10 mmHg"], "correct": 0, "decode": "Normal IOP is 10-21 mmHg. Higher ranges are elevated; 5-10 is low (hypotony).", "ow": ["Correct. Normal IOP is 10-21 mmHg.", "30-40 is markedly elevated.", "22-30 is elevated (ocular hypertension range).", "5-10 is low, toward hypotony."]}'),
  ('c5f35e3f-17','{"options": ["Aqueous fills the posterior segment", "Vitreous is made by the ciliary body", "They are chemically identical fluids", "Aqueous is replaced; vitreous is not"], "correct": 3, "decode": "Aqueous is continuously produced and REPLACED (turnover); vitreous is formed once and NOT replaced. That turnover difference is the key contrast.", "ow": ["Aqueous fills the anterior segment; vitreous fills the posterior.", "Vitreous is embryologic, not made by the ciliary body.", "They differ in composition and turnover.", "Correct. Aqueous turns over; vitreous does not."]}'),
  ('b2b5035e-23','{"options": ["The ora serrata", "Cloquet''s canal", "Bruch''s membrane", "The lamina cribrosa"], "correct": 1, "decode": "The hyaloid artery remnant running through the vitreous is Cloquet''s canal (from lens to disc). The ora serrata, Bruch''s, and lamina cribrosa are unrelated structures.", "ow": ["The ora serrata is the retina''s anterior edge.", "Correct. Cloquet''s canal is the hyaloid artery remnant.", "Bruch''s membrane lies between choroid and RPE.", "The lamina cribrosa is at the optic nerve head."]}'),
  ('6d34f857-28','{"options": ["Prostaglandin analogs", "Carbonic anhydrase inhibitors", "Alpha-2 agonists", "Beta blockers"], "correct": 0, "decode": "PROSTAGLANDIN analogs lower IOP mainly by increasing UVEOSCLERAL outflow. The others reduce aqueous PRODUCTION (CAI, beta blockers, alpha-2) or add some trabecular outflow.", "ow": ["Correct. Prostaglandin analogs increase uveoscleral outflow.", "Carbonic anhydrase inhibitors cut aqueous production.", "Alpha-2 agonists mainly reduce production.", "Beta blockers reduce aqueous production."]}'),
  ('bad65df5-1i','{"options": ["Avascular only", "Identical curvature", "More curved", "Less curved"], "correct": 2, "decode": "The POSTERIOR lens surface is MORE curved (steeper) than the anterior. Both are convex, but the back is steeper.", "ow": ["The lens is avascular, but the question is about curvature.", "The two surfaces are not identical; the back is steeper.", "Correct. The posterior lens surface is more curved.", "The posterior surface is more, not less, curved."]}'),
  ('5afae6ce-11','{"options": ["It is too small for vessels", "Vessels would obstruct the optical path", "It is replaced daily", "It has no metabolic needs"], "correct": 1, "decode": "The lens is AVASCULAR because blood vessels would scatter light and obstruct the OPTICAL PATH; it lives on aqueous nutrition instead. It is not about size or lack of metabolism.", "ow": ["Size is not why it lacks vessels.", "Correct. Vessels would block the optical path, so it stays avascular.", "The lens is not replaced daily; fibers are retained for life.", "The lens does have metabolic needs, met by the aqueous."]}'),
  ('3e0e340d-1b','{"options": ["Photoreceptors from the RPE", "RPE from Bruch''s membrane", "NFL from ganglion cells", "Choroid from sclera"], "correct": 0, "decode": "A (rhegmatogenous) retinal detachment separates the neurosensory retina (PHOTORECEPTORS) from the RPE, along the old embryonic cleft. It is not an RPE-Bruch''s or choroid-sclera split.", "ow": ["Correct. Detachment separates photoreceptors from the RPE.", "RPE-Bruch''s separation is a PED, not a retinal detachment.", "NFL-ganglion is within the neural retina, not the detachment plane.", "Choroid-sclera separation is a choroidal detachment."]}'),
  ('f44b428d-k','{"options": ["Equal numbers of rods and cones", "Cones only, no capillaries", "Rods only, densely packed", "No photoreceptors at all"], "correct": 1, "decode": "The foveola contains CONES ONLY and is AVASCULAR (no capillaries), giving the sharpest vision. No rods and no vessels is the tell.", "ow": ["The foveola is cone-only, not a rod-cone mix.", "Correct. The foveola is cones only, with no capillaries.", "The foveola has cones, not rods.", "It is packed with cones, not devoid of photoreceptors."]}')
)
UPDATE question_reviews r
SET payload = r.payload || d.patch::jsonb
FROM d
WHERE r.question_id = d.qid;
